/// Recipe `${VAR}` expansion runs after the TOML is parsed, so an env value
/// containing a quote and newline cannot inject a new recipe key. The
/// variable is set on the child process only, never on this test process.
#[test]
fn recipe_expansion_cannot_inject_keys() {
    let td = workdir("recipe-inj");
    let app = td.join("app");
    write(&app.join("bin/run.sh"), "#!/bin/sh\necho hi\n");
    write(
        &app.join("onelf.toml"),
        "[package]\ncommand = \"bin/run.sh\"\ndescription = \"${ONELF_INJ}\"\n\n[bundle]\nskip = true\n",
    );

    let pkg = td.join("i.onelf");
    // Spliced into raw TOML before parsing, this would close the string and
    // open a `name` key. Post-parse expansion keeps it as one value.
    let payload = "evil\"\nname = \"HACKED";
    let o = Command::new(onelf())
        .args([
            "build",
            app.to_str().unwrap(),
            "--output",
            pkg.to_str().unwrap(),
        ])
        .env("ONELF_INJ", payload)
        .output()
        .expect("spawn onelf build");
    assert!(
        o.status.success(),
        "build: {}",
        String::from_utf8_lossy(&o.stderr)
    );

    let o = run_onelf(&["info", pkg.to_str().unwrap()], None);
    let info = String::from_utf8_lossy(&o.stdout);
    // If expansion happened before parse, the value would have split into a
    // separate `name` key and the description would be just "evil"; the
    // marker only survives inside the description when expansion is
    // post-parse.
    assert!(
        info.contains("HACKED"),
        "injected marker must survive as a literal description value:\n{info}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// Every path under `dir` with its contents, sorted, so a failed build
/// can be proven to have left the tree exactly as it found it.
fn tree_snapshot(dir: &Path) -> Vec<(String, Vec<u8>)> {
    let mut out: Vec<(String, Vec<u8>)> = jwalk::WalkDir::new(dir)
        .sort(true)
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| e.file_type().is_file())
        .map(|e| {
            let rel = e
                .path()
                .strip_prefix(dir)
                .unwrap()
                .to_string_lossy()
                .into_owned();
            let bytes = std::fs::read(e.path()).unwrap();
            (rel, bytes)
        })
        .collect();
    out.sort_by(|a, b| a.0.cmp(&b.0));
    out
}

/// A sets-only recipe: the AppDir stands as authored and the declared
/// sets are what the runtime would fetch, so selection lists have
/// declarations to be validated against.
fn sets_recipe(command_sets: &str, entrypoints: &str) -> String {
    format!(
        "[package]\ncommand = \"bin/run.sh\"\nmtime = 0\n{command_sets}\n\
         [bundle]\nskip = true\n\n\
         [sysroot.sets.gtk]\npackages = [\"gtk3\"]\nurl = \"https://e/gtk.onelf\"\n\
         blake3 = \"0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef\"\n\
         {entrypoints}"
    )
}

/// A `sets` list naming a set the recipe does not declare fails at
/// recipe load, before the build touches the tree: nothing is staged,
/// nothing is recorded, and no output is written.
#[test]
fn an_unknown_set_name_fails_before_the_tree_is_written() {
    let td = workdir("sets-unknown");
    let app = td.join("app");
    write(&app.join("bin/run.sh"), "#!/bin/sh\necho hi\n");
    write(
        &app.join("onelf.toml"),
        &sets_recipe("sets = [\"ghost\"]", ""),
    );
    let before = tree_snapshot(&app);
    let pkg = td.join("u.onelf");
    let o = Command::new(onelf())
        .args([
            "build",
            app.to_str().unwrap(),
            "--output",
            pkg.to_str().unwrap(),
        ])
        .output()
        .expect("spawn onelf build");
    assert_eq!(o.status.code(), Some(1));
    let err = String::from_utf8_lossy(&o.stderr);
    assert!(err.contains("[package]: unknown set name 'ghost'"), "{err}");
    assert!(!pkg.exists(), "a refused build writes no output");
    assert_eq!(tree_snapshot(&app), before, "the tree must stand untouched");
    let _ = std::fs::remove_dir_all(&td);
}

/// A name repeated within one selection list is refused at load, with
/// the list it was written in named, and the tree stands untouched.
#[test]
fn a_duplicate_set_name_fails_before_the_tree_is_written() {
    let td = workdir("sets-dup");
    let app = td.join("app");
    write(&app.join("bin/run.sh"), "#!/bin/sh\necho hi\n");
    write(
        &app.join("onelf.toml"),
        &sets_recipe(
            "",
            "[[entrypoint]]\nname = \"cli\"\npath = \"bin/run.sh\"\nsets = [\"gtk\", \"gtk\"]\n",
        ),
    );
    let before = tree_snapshot(&app);
    let pkg = td.join("d.onelf");
    let o = Command::new(onelf())
        .args([
            "build",
            app.to_str().unwrap(),
            "--output",
            pkg.to_str().unwrap(),
        ])
        .output()
        .expect("spawn onelf build");
    assert_eq!(o.status.code(), Some(1));
    let err = String::from_utf8_lossy(&o.stderr);
    assert!(
        err.contains("entrypoint 'cli': duplicate set name 'gtk'"),
        "{err}"
    );
    assert!(!pkg.exists(), "a refused build writes no output");
    assert_eq!(tree_snapshot(&app), before, "the tree must stand untouched");
    let _ = std::fs::remove_dir_all(&td);
}

/// An explicit selection is emitted as `.onelf/entrypoint-sets`: the
/// declared pin table paired with one exact selection per final
/// entrypoint. The legacy recipe beside it, every list omitted, emits
/// no record, and every other generated record the two packages carry
/// stays identical. The packed recipe text itself differs between the
/// two builds, so its own entry is set aside before the comparison.
#[test]
fn an_explicit_selection_emits_its_record_and_leaves_the_rest_unchanged() {
    let td = workdir("sets-legacy");
    let app = td.join("app");
    write(&app.join("bin/run.sh"), "#!/bin/sh\necho hi\n");

    let selected = sets_recipe(
        "sets = [\"gtk\"]",
        "[[entrypoint]]\nname = \"cli\"\npath = \"bin/run.sh\"\nargs = [\"--cli\"]\nsets = []\n",
    );
    write(&app.join("onelf.toml"), &selected);
    let with = td.join("with.onelf");
    let o = Command::new(onelf())
        .args([
            "build",
            app.to_str().unwrap(),
            "--output",
            with.to_str().unwrap(),
        ])
        .output()
        .expect("spawn onelf build");
    assert!(
        o.status.success(),
        "an explicit selection builds onto a capable runtime: {}",
        String::from_utf8_lossy(&o.stderr)
    );

    let legacy = sets_recipe(
        "",
        "[[entrypoint]]\nname = \"cli\"\npath = \"bin/run.sh\"\nargs = [\"--cli\"]\n",
    );
    write(&app.join("onelf.toml"), &legacy);
    let without = td.join("without.onelf");
    let o = Command::new(onelf())
        .args([
            "build",
            app.to_str().unwrap(),
            "--output",
            without.to_str().unwrap(),
        ])
        .output()
        .expect("spawn onelf build");
    assert!(
        o.status.success(),
        "the legacy recipe still builds: {}",
        String::from_utf8_lossy(&o.stderr)
    );

    // The packed recipe text differs by the lists themselves, and only
    // the explicit build carries the selection record, so both rows are
    // set aside; everything else the package carries must match.
    let listing = |pkg: &Path| {
        let out = run_onelf(&["list", pkg.to_str().unwrap()], None);
        String::from_utf8_lossy(&out.stdout)
            .lines()
            .filter(|l| !l.ends_with(" onelf.toml"))
            .filter(|l| !l.ends_with(".onelf/entrypoint-sets"))
            .collect::<Vec<_>>()
            .join("\n")
    };
    assert_eq!(
        listing(&with),
        listing(&without),
        "selection lists must not change the rest of the package structure"
    );
    let record_of = |pkg: &Path| {
        run_onelf(
            &[
                "extract",
                pkg.to_str().unwrap(),
                "-o",
                "-",
                "--file",
                ".onelf/entrypoint-sets",
            ],
            None,
        )
    };
    let carried = record_of(&with);
    assert!(
        carried.status.success(),
        "the explicit build emits the record"
    );
    let record = onelf_format::runtime_metadata::EntrypointSets::decode(&carried.stdout)
        .expect("the emitted record decodes");
    assert_eq!(
        record
            .entrypoints
            .iter()
            .map(|e| (e.name.as_str(), e.sets.len()))
            .collect::<Vec<_>>(),
        [("cli", 0), ("run.sh", 1),],
        "the primary selects its written list and the named entrypoint selects none"
    );
    let absent = record_of(&without);
    assert!(
        !absent.status.success(),
        "the legacy build carries no selection record"
    );
    assert!(absent.stdout.is_empty());

    let recorded = |pkg: &Path| {
        let out = run_onelf(
            &[
                "extract",
                pkg.to_str().unwrap(),
                "-o",
                "-",
                "--file",
                ".onelf/sets",
            ],
            None,
        );
        String::from_utf8_lossy(&out.stdout).into_owned()
    };
    assert!(recorded(&with).contains("gtk.onelf"), "the pin is recorded");
    assert_eq!(
        recorded(&with),
        recorded(&without),
        "the recorded sets must not depend on the selection lists"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// The documented user asset dirs `.onelf/icons/` and `.onelf/desktop/`
/// are accepted from source and round-trip through `icon`/`desktop`,
/// while the rest of the `.onelf/` namespace stays reserved.
#[test]
fn source_onelf_assets_are_accepted() {
    let td = workdir("assets");
    let app = td.join("app");
    write(&app.join("bin/run.sh"), "#!/bin/sh\necho hi\n");
    write(&app.join(".onelf/icons/default.png"), "PNGDATA");
    write(
        &app.join(".onelf/desktop/default.desktop"),
        "[Desktop Entry]\nName=App\nExec=run.sh\n",
    );

    let pkg = td.join("a.onelf");
    let o = run_onelf(
        &[
            "pack",
            "--command",
            "bin/run.sh",
            "--output",
            pkg.to_str().unwrap(),
            app.to_str().unwrap(),
        ],
        None,
    );
    assert!(
        o.status.success(),
        "packing .onelf/icons and .onelf/desktop must succeed; got: {}",
        String::from_utf8_lossy(&o.stderr)
    );

    let icon_out = td.join("out.png");
    let i = run_onelf(
        &[
            "icon",
            pkg.to_str().unwrap(),
            "-o",
            icon_out.to_str().unwrap(),
        ],
        None,
    );
    assert!(i.status.success(), "icon extract failed");
    assert_eq!(std::fs::read(&icon_out).unwrap(), b"PNGDATA");

    let desk_out = td.join("out.desktop");
    let d = run_onelf(
        &[
            "desktop",
            pkg.to_str().unwrap(),
            "-o",
            desk_out.to_str().unwrap(),
        ],
        None,
    );
    assert!(d.status.success(), "desktop extract failed");
    assert!(
        String::from_utf8_lossy(&std::fs::read(&desk_out).unwrap()).contains("Name=App"),
        "extracted desktop file should carry the source content"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A statically linked entrypoint is what memfd mode is for, and forcing the
/// mode has to keep working for it. This is the control for the two refusals
/// below: they must reject the impossible case without taking this with them.
#[test]
fn a_static_entrypoint_still_runs_from_a_memfd() {
    let td = workdir("memfd-static");
    let app = td.join("app");
    let src = td.join("hello.c");
    write(
        &src,
        "#include <stdio.h>\nint main(){puts(\"from-memfd\");return 0;}\n",
    );

    let bin = app.join("bin/hello");
    std::fs::create_dir_all(bin.parent().unwrap()).unwrap();
    let compiler = if have("cc") {
        "cc"
    } else if have("gcc") {
        "gcc"
    } else {
        skip("cc", "no C compiler available");
        return;
    };
    let built = Command::new(compiler)
        .args(["-O0", "-static", "-o"])
        .arg(&bin)
        .arg(&src)
        .status()
        .map(|s| s.success())
        .unwrap_or(false);
    if !built {
        skip("staticlibc", "no static libc available to link against");
        let _ = std::fs::remove_dir_all(&td);
        return;
    }

    let pkg = td.join("hello.onelf");
    let out = run_onelf(
        &[
            "pack",
            app.to_str().unwrap(),
            "-o",
            pkg.to_str().unwrap(),
            "--command",
            "bin/hello",
        ],
        None,
    );
    assert!(out.status.success(), "pack failed: {out:?}");

    let mut c = Command::new(&pkg);
    c.env("ONELF_MODE", "memfd");
    isolate(&mut c, &td);
    let run = run_package(&mut c);
    assert!(
        run.status.success(),
        "forced memfd must still run a static entrypoint: {}",
        String::from_utf8_lossy(&run.stderr)
    );
    assert!(
        String::from_utf8_lossy(&run.stdout).contains("from-memfd"),
        "expected the program's own output"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// Forcing memfd on an entrypoint that needs bundled libraries has to fail
/// with a message about the mode. Left alone it execs successfully and the
/// *loader* fails afterwards, naming a library, in a process onelf no longer
/// controls, so the mode that caused it is never mentioned.
#[test]
fn forcing_memfd_on_a_linked_entrypoint_says_so() {
    // No "memfd" in the directory name: the failure this guards against
    // prints the package's own path, so a tag containing "memfd" would
    // satisfy the assertion below whether or not the guard exists.
    let td = workdir("forced-mode");
    let app = td.join("app");
    let src = td.join("m.c");
    let bin = app.join("bin/m");
    std::fs::create_dir_all(bin.parent().unwrap()).unwrap();
    if !cc_libm(&src, &bin) {
        skip("cc", "no C compiler available");
        let _ = std::fs::remove_dir_all(&td);
        return;
    }

    let pkg = td.join("m.onelf");
    let out = run_onelf(
        &[
            "pack",
            app.to_str().unwrap(),
            "-o",
            pkg.to_str().unwrap(),
            "--command",
            "bin/m",
        ],
        None,
    );
    assert!(out.status.success(), "pack failed: {out:?}");

    let mut c = Command::new(&pkg);
    c.env("ONELF_MODE", "memfd");
    isolate(&mut c, &td);
    let run = run_package(&mut c);
    assert!(!run.status.success(), "forced memfd must not succeed here");
    let err = String::from_utf8_lossy(&run.stderr);
    assert!(
        err.contains("ONELF_MODE") && err.contains("memfd mode cannot satisfy"),
        "the error has to point at the mode, not at whichever library the \
         loader happened to miss, got: {err}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// `--memfd` on a bundle-libs entrypoint builds a package that fails for
/// every user at every launch, because bundle-libs links it against a library
/// it puts inside the package. Refuse at pack time and write nothing.
#[test]
fn packing_refuses_memfd_for_a_bundled_entrypoint() {
    let Some(_pe) = patchelf() else {
        skip("patchelf", "patchelf not available");
        return;
    };
    let td = workdir("memfd-pack");
    let app = td.join("app");
    let src = td.join("m.c");
    let bin = app.join("bin/m");
    std::fs::create_dir_all(bin.parent().unwrap()).unwrap();
    if !cc_libm(&src, &bin) {
        skip("cc", "no C compiler available");
        let _ = std::fs::remove_dir_all(&td);
        return;
    }

    let bundled = run_onelf(&["bundle-libs", app.to_str().unwrap()], None);
    assert!(bundled.status.success(), "bundle-libs failed: {bundled:?}");

    let pkg = td.join("m.onelf");
    let out = run_onelf(
        &[
            "pack",
            app.to_str().unwrap(),
            "-o",
            pkg.to_str().unwrap(),
            "--command",
            "bin/m",
            "--memfd",
        ],
        None,
    );
    assert!(!out.status.success(), "pack must refuse --memfd here");
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(
        err.contains("--memfd"),
        "the error has to name the flag, got: {err}"
    );
    assert!(
        !pkg.exists(),
        "a package that cannot run must not be left behind"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A process that daemonizes must keep working after the launcher returns.
///
/// It forks a background copy, lets the foreground exit, and closes every
/// descriptor it inherited. That last part hangs up the death pipe the FUSE
/// mode waits on, so the signal says "finished" while the real work is only
/// starting. Tearing the filesystem down there leaves the surviving process
/// blocked on its next read, which looks exactly like the app having hung.
#[test]
fn a_daemonized_process_outlives_the_launcher() {
    if !fuse_available() {
        skip("fuse", "FUSE is not mountable here");
        return;
    }
    let td = workdir("daemonize");
    let app = td.join("app");
    let src = td.join("d.c");
    let bin = app.join("bin/d");
    std::fs::create_dir_all(bin.parent().unwrap()).unwrap();

    let result = td.join("result");
    write(&app.join("data.txt"), "payload\n");
    write(
        &src,
        &format!(
            "#include <unistd.h>\n#include <stdio.h>\n#include <stdlib.h>\n\
             int main(void){{\n\
             \x20 if (fork() != 0) {{ _exit(0); }}\n\
             \x20 setsid();\n\
             \x20 for (int fd = 3; fd < 256; fd++) close(fd);\n\
             \x20 sleep(2);\n\
             \x20 const char *d = getenv(\"ONELF_DIR\");\n\
             \x20 char p[512];\n\
             \x20 snprintf(p, sizeof p, \"%s/data.txt\", d ? d : \"/nonexistent\");\n\
             \x20 FILE *in = fopen(p, \"r\");\n\
             \x20 FILE *out = fopen(\"{}\", \"w\");\n\
             \x20 if (out) {{ fprintf(out, in ? \"READ-OK\" : \"READ-FAILED\"); fclose(out); }}\n\
             \x20 return 0;\n}}\n",
            result.display()
        ),
    );
    if !cc(&src, &bin) {
        let _ = std::fs::remove_dir_all(&td);
        return;
    }

    let pkg = td.join("d.onelf");
    let out = run_onelf(
        &[
            "pack",
            app.to_str().unwrap(),
            "-o",
            pkg.to_str().unwrap(),
            "--command",
            "bin/d",
        ],
        None,
    );
    assert!(out.status.success(), "pack failed: {out:?}");

    let mut c = Command::new(&pkg);
    c.env("ONELF_MODE", "fuse");
    isolate(&mut c, &td);
    let run = run_package(&mut c);
    assert!(
        run.status.success(),
        "launcher must return promptly and successfully: {}",
        String::from_utf8_lossy(&run.stderr)
    );

    // The daemonized process reads the mount two seconds after the launcher
    // is gone, so this waits past that before deciding.
    let mut got = String::new();
    for _ in 0..60 {
        std::thread::sleep(std::time::Duration::from_millis(200));
        if let Ok(s) = std::fs::read_to_string(&result) {
            got = s;
            break;
        }
    }
    assert_eq!(
        got, "READ-OK",
        "the daemonized process could not read the package after the launcher exited"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// The launcher has to return when the process it started exits, not when the
/// last thing that process spawned exits.
///
/// A caller that starts a daemon does the same thing every time: wait for the
/// launcher, then look for whatever the daemon was supposed to set up. If the
/// launcher instead waits for the daemon to finish, that check runs after the
/// daemon has already gone, and a daemon that started perfectly well is
/// reported dead.
#[test]
fn the_launcher_returns_without_waiting_for_a_daemon() {
    if !fuse_available() {
        skip("fuse", "FUSE is not mountable here");
        return;
    }
    let td = workdir("prompt-return");
    let app = td.join("app");
    let src = td.join("p.c");
    let bin = app.join("bin/p");
    std::fs::create_dir_all(bin.parent().unwrap()).unwrap();

    // Forks a background process that outlives the launcher by 5 seconds,
    // the same shape as a daemon holding a socket open.
    // Detaches from every inherited descriptor first, exactly as a daemon
    // does. Holding the launcher's stdout would make the test measure the
    // harness waiting on a pipe rather than the launcher waiting on a process.
    write(
        &src,
        "#include <unistd.h>\n#include <fcntl.h>\nint main(void){\n\
         \x20 if (fork() != 0) { _exit(0); }\n\
         \x20 setsid();\n\
         \x20 int n = open(\"/dev/null\", O_RDWR);\n\
         \x20 dup2(n, 0); dup2(n, 1); dup2(n, 2);\n\
         \x20 for (int fd = 3; fd < 256; fd++) close(fd);\n\
         \x20 sleep(5);\n\
         \x20 return 0;\n}\n",
    );
    if !cc(&src, &bin) {
        let _ = std::fs::remove_dir_all(&td);
        return;
    }

    let pkg = td.join("p.onelf");
    let out = run_onelf(
        &[
            "pack",
            app.to_str().unwrap(),
            "-o",
            pkg.to_str().unwrap(),
            "--command",
            "bin/p",
        ],
        None,
    );
    assert!(out.status.success(), "pack failed: {out:?}");

    let mut c = Command::new(&pkg);
    c.env("ONELF_MODE", "fuse");
    isolate(&mut c, &td);
    let started = std::time::Instant::now();
    let run = run_package(&mut c);
    let waited = started.elapsed();

    assert!(run.status.success(), "launcher failed: {run:?}");
    assert!(
        waited < std::time::Duration::from_secs(3),
        "launcher waited {waited:?} for a background process that sleeps 5s; \
         it should return as soon as the process it started exits"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// Pack a package whose entrypoint is the shell script `body`.
fn pack_script(td: &Path, tag: &str, body: &str) -> PathBuf {
    let app = td.join(tag);
    std::fs::create_dir_all(app.join("bin")).unwrap();
    write(&app.join("bin/run"), body);
    std::fs::set_permissions(
        app.join("bin/run"),
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();
    let pkg = td.join(format!("{tag}.onelf"));
    let o = Command::new(onelf())
        .args(["pack", app.to_str().unwrap(), "-o", pkg.to_str().unwrap()])
        .args(["--command", "bin/run", "--mtime", "0", "--name", tag])
        .output()
        .expect("spawn onelf pack");
    assert!(
        o.status.success(),
        "pack failed: {}",
        String::from_utf8_lossy(&o.stderr)
    );
    pkg
}

/// The mountpoint under `run_dir` that this process's mount namespace
/// currently lists, if any.
fn helper_mount_under(run_dir: &Path) -> Option<PathBuf> {
    helper_mounts_under(run_dir).into_iter().next()
}

/// Every mountpoint under `run_dir` that this process's mount namespace
/// currently lists, in the order they were mounted.
fn helper_mounts_under(run_dir: &Path) -> Vec<PathBuf> {
    let info = std::fs::read_to_string("/proc/self/mountinfo").unwrap_or_default();
    let prefix = format!("{}/onelf-", run_dir.display());
    info.lines()
        .filter_map(|line| {
            let mp = line.split(' ').nth(4)?.replace("\\040", " ");
            mp.starts_with(&prefix).then(|| PathBuf::from(mp))
        })
        .collect()
}

/// Launch `pkg` through the host's FUSE helper and wait for its mount to
/// appear. `None` when the helper cannot mount here, which is a documented
/// soft-skip like the other environment probes.
///
/// The launch does not share its mount, so the server is the launcher
/// itself and killing the launch's process group kills the server too.
fn launch_via_helper(pkg: &Path, td: &Path) -> Option<(std::process::Child, PathBuf)> {
    use std::os::unix::process::CommandExt;

    let mut cmd = Command::new(pkg);
    cmd.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", "fuse")
        .env("ONELF_FUSE_NO_NAMESPACE", "1")
        .env("ONELF_FUSE_NO_SHARE", "1")
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .process_group(0);
    isolate(&mut cmd, td);
    let mut child = cmd.spawn().expect("spawn package");
    let run_dir = td.join("xdg-run");
    for _ in 0..200 {
        if let Some(mp) = helper_mount_under(&run_dir) {
            return Some((child, mp));
        }
        if child.try_wait().unwrap().is_some() {
            skip("helperfuse", "the FUSE helper cannot mount here");
            return None;
        }
        std::thread::sleep(std::time::Duration::from_millis(25));
    }
    let _ = child.kill();
    skip("helperfuse", "the FUSE helper mount did not appear");
    None
}

/// The app never holds the mount's `/dev/fuse` descriptor, on either
/// mount path. An inherited one keeps the connection alive after the
/// server dies, and the holder then blocks on the mount unkillably.
#[test]
fn the_app_does_not_inherit_the_fuse_descriptor() {
    if !fuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("fusefd");
    let pkg = pack_script(
        &td,
        "fds",
        "#!/bin/sh\nfor f in /proc/self/fd/*; do readlink \"$f\"; done\n",
    );
    for helper in [false, true] {
        if helper && !helperfuse_available() {
            continue;
        }
        let mut cmd = Command::new(&pkg);
        cmd.env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("ONELF_MODE", "fuse");
        if helper {
            cmd.env("ONELF_FUSE_NO_NAMESPACE", "1");
        }
        isolate(&mut cmd, &td);
        let out = run_package(&mut cmd);
        if !out.status.success() {
            skip(
                if helper { "helperfuse" } else { "fuse" },
                &format!("helper={helper} cannot mount here"),
            );
            continue;
        }
        let stdout = String::from_utf8_lossy(&out.stdout);
        assert!(
            stdout.contains("/dev/") && !stdout.contains("/dev/fuse"),
            "helper={helper}: the app holds the mount's descriptor:\n{stdout}"
        );
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// The same holds on the userland exec path, where no `execve` runs to
/// drop close-on-exec descriptors. A binary rebuilt after `bundle-libs`
/// and packed as is keeps its `PT_INTERP`, which is what selects that path.
#[test]
fn the_app_does_not_inherit_the_fuse_descriptor_under_userland_exec() {
    if !fuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("fusefd-ulexec");
    let src = td.join("fds.c");
    write(
        &src,
        r#"
#include <stdio.h>
#include <dirent.h>
#include <unistd.h>
int main(void) {
    char buf[4096];
    ssize_t n = readlink("/proc/self/exe", buf, sizeof buf - 1);
    if (n > 0) { buf[n] = 0; printf("exe %s\n", buf); }
    DIR *d = opendir("/proc/self/fd");
    struct dirent *e;
    while (d && (e = readdir(d))) {
        char p[64];
        if (e->d_name[0] == '.') continue;
        snprintf(p, sizeof p, "/proc/self/fd/%s", e->d_name);
        n = readlink(p, buf, sizeof buf - 1);
        if (n > 0) { buf[n] = 0; printf("%s %s\n", e->d_name, buf); }
    }
    return 0;
}
"#,
    );
    let app = td.join("app");
    let bin = app.join("bin/fds");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    if !cc(&src, &bin) {
        return;
    }
    let o = run_onelf(&["bundle-libs", app.to_str().unwrap()], None);
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    // The rebuild after bundling: PT_INTERP is back, .onelf/interp stays.
    assert!(cc(&src, &bin));
    let pkg = td.join("fds.onelf");
    let o = run_onelf(
        &[
            "pack",
            app.to_str().unwrap(),
            "-o",
            pkg.to_str().unwrap(),
            "--command",
            "bin/fds",
        ],
        None,
    );
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));

    let mut cmd = Command::new(&pkg);
    cmd.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", "fuse");
    isolate(&mut cmd, &td);
    let out = run_package(&mut cmd);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        stdout.contains(&format!("exe {}", pkg.display())),
        "expected the userland exec path (exe is the package):\n{stdout}"
    );
    let leaked = stdout
        .lines()
        .filter(|l| !l.starts_with("exe "))
        .any(|l| l.contains("/dev/fuse") || l.contains("fds.onelf"));
    assert!(
        !leaked,
        "the app holds a descriptor execve would have closed:\n{stdout}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// An argument that is not UTF-8 reaches the app as the bytes it was.
/// A file manager passes whatever name the file has, and the runtime used
/// to collect argv as `String`, which aborts the launch on such a name.
#[test]
fn a_non_utf8_argument_reaches_the_app_intact() {
    use std::os::unix::ffi::OsStrExt;

    let td = workdir("argv-bytes");
    let pkg = pack_script(
        &td,
        "hexdump",
        "#!/bin/sh\nprintf '%s' \"$1\" | od -An -tx1\n",
    );
    for mode in ["cache", "fuse"] {
        if mode == "fuse" && !fuse_available() {
            continue;
        }
        let mut cmd = Command::new(&pkg);
        cmd.arg(std::ffi::OsStr::from_bytes(b"caf\xe9.txt"))
            .env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("ONELF_MODE", mode);
        isolate(&mut cmd, &td);
        let out = run_package(&mut cmd);
        assert!(
            out.status.success(),
            "{mode}: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        let hex = String::from_utf8_lossy(&out.stdout).replace(char::is_whitespace, "");
        assert_eq!(hex, "636166e92e747874", "{mode}");
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// Two packages shipping the same bytes with different modes get their
/// own blob each. A blob is one inode hardlinked into every tree that
/// carries it, so a shared one took the first package's mode, and the
/// second package's copy of an executable came out unexecutable.
#[test]
fn cas_blobs_with_different_modes_do_not_share_an_inode() {
    use std::os::unix::fs::PermissionsExt;

    let td = workdir("cas-mode");
    let body = "#!/bin/sh\necho SAME BYTES\n";
    // Package A carries the script as plain data, package B runs it.
    let a = td.join("a");
    write(&a.join("bin/run"), "#!/bin/sh\necho A\n");
    std::fs::set_permissions(a.join("bin/run"), PermissionsExt::from_mode(0o755)).unwrap();
    write(&a.join("share/script.sh"), body);
    std::fs::set_permissions(a.join("share/script.sh"), PermissionsExt::from_mode(0o644)).unwrap();
    let b = td.join("b");
    write(&b.join("bin/run"), body);
    std::fs::set_permissions(b.join("bin/run"), PermissionsExt::from_mode(0o755)).unwrap();

    let mut pkgs = Vec::new();
    for (app, name) in [(&a, "a"), (&b, "b")] {
        let pkg = td.join(format!("{name}.onelf"));
        let o = Command::new(onelf())
            .args(["pack", app.to_str().unwrap(), "-o", pkg.to_str().unwrap()])
            .args(["--command", "bin/run", "--mtime", "0", "--name", name])
            .output()
            .expect("spawn onelf pack");
        assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
        pkgs.push(pkg);
    }
    for (pkg, expect) in pkgs.iter().zip(["A", "SAME BYTES"]) {
        let mut cmd = Command::new(pkg);
        cmd.env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("ONELF_MODE", "cache");
        isolate(&mut cmd, &td);
        let out = run_package(&mut cmd);
        assert!(
            out.status.success(),
            "{}: {}",
            pkg.display(),
            String::from_utf8_lossy(&out.stderr)
        );
        assert!(String::from_utf8_lossy(&out.stdout).contains(expect));
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// A binary the packer could not give an RPATH still finds its own
/// libraries. Distribution binaries carry no RPATH slot, and without
/// patchelf at bundle time nothing can add one; the runtime used to hand
/// such a binary only the host-side directories, and it failed on its
/// own libc.
#[test]
fn a_binary_without_an_rpath_still_finds_the_bundled_libc() {
    let td = workdir("norpath");
    let src = td.join("app.c");
    write(
        &src,
        "#include <stdio.h>\nint main(void){puts(\"NO RPATH OK\");return 0;}\n",
    );
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    if !cc(&src, &app.join("bin/app")) {
        return;
    }
    // No patchelf reachable: an empty PATH and a bogus override.
    let o = Command::new(onelf())
        .args(["bundle-libs", app.to_str().unwrap()])
        .env("PATH", td.to_str().unwrap())
        .env(
            "ONELF_PATCHELF",
            td.join("no-such-patchelf").to_str().unwrap(),
        )
        .output()
        .expect("spawn onelf bundle-libs");
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    let data = std::fs::read(app.join("bin/app")).unwrap();
    assert!(
        !data.windows(7).any(|w| w == b"$ORIGIN"),
        "the fixture grew an RPATH after all; the test needs one without"
    );

    let pkg = td.join("app.onelf");
    let o = Command::new(onelf())
        .args(["pack", app.to_str().unwrap(), "-o", pkg.to_str().unwrap()])
        .args(["--command", "bin/app", "--mtime", "0"])
        .output()
        .expect("spawn onelf pack");
    assert!(o.status.success());
    let mut run = Command::new(&pkg);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", "cache")
        .env("ONELF_NO_RESOLVER", "1");
    isolate(&mut run, &td);
    let out = run_package(&mut run);
    assert!(
        out.status.success() && String::from_utf8_lossy(&out.stdout).contains("NO RPATH OK"),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// Stopping and resuming the app must not stop the server. A stopped child
/// raises SIGCHLD too, and a server that took that for an exit parked in
/// `waitpid` while the resumed app blocked forever on its next read from
/// the mount. Ctrl-Z, `kill -STOP`, and a debugger attaching all do this.
#[test]
fn a_stopped_and_resumed_app_still_reads_from_the_mount() {
    use std::io::BufRead;

    if !fuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("stopcont");
    write(&td.join("stopper/data.txt"), "STILL SERVED\n");
    let pkg = pack_script(
        &td,
        "stopper",
        "#!/bin/sh\necho \"pid $$\"\nsleep 2\ncat \"$ONELF_DIR/data.txt\"\n",
    );
    let mut cmd = Command::new(&pkg);
    cmd.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", "fuse")
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::null());
    isolate(&mut cmd, &td);
    let mut child = loop {
        match cmd.spawn() {
            Ok(c) => break c,
            Err(e) if e.kind() == std::io::ErrorKind::ExecutableFileBusy => {
                std::thread::sleep(std::time::Duration::from_millis(20));
            }
            Err(e) => panic!("spawn package: {e}"),
        }
    };
    let mut stdout = std::io::BufReader::new(child.stdout.take().unwrap());
    let mut first = String::new();
    stdout.read_line(&mut first).unwrap();
    let app_pid = first.trim().strip_prefix("pid ").expect("pid line");
    for sig in ["-STOP", "-CONT"] {
        let st = Command::new("kill").args([sig, app_pid]).status().unwrap();
        assert!(st.success(), "kill {sig} {app_pid}");
        std::thread::sleep(std::time::Duration::from_millis(200));
    }
    let reader = std::thread::spawn(move || {
        let mut rest = String::new();
        std::io::Read::read_to_string(&mut stdout, &mut rest).unwrap();
        rest
    });
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(15);
    let status = loop {
        if let Some(st) = child.try_wait().unwrap() {
            break st;
        }
        if std::time::Instant::now() > deadline {
            let _ = Command::new("kill").args(["-9", app_pid]).status();
            let _ = child.kill();
            panic!("the app hung after being stopped and resumed");
        }
        std::thread::sleep(std::time::Duration::from_millis(50));
    };
    let rest = reader.join().unwrap();
    assert!(status.success(), "exit {status}:\n{rest}");
    assert!(rest.contains("STILL SERVED"), "output:\n{rest}");
    let _ = std::fs::remove_dir_all(&td);
}

/// A mount served through the host's FUSE helper outlives a runtime that
/// was killed, and the kernel cannot tear it down on its own. The next
/// launch of any package reclaims it.
#[test]
fn a_dead_helper_mount_is_reclaimed_by_the_next_launch() {
    if !fuse_available() || !helperfuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("deadmount");
    let sleeper = pack_script(&td, "sleeper", "#!/bin/sh\nsleep 4\n");
    let other = pack_script(&td, "other", "#!/bin/sh\necho OTHER\n");

    let Some((mut child, mountpoint)) = launch_via_helper(&sleeper, &td) else {
        return;
    };
    // The runtime and the app it launched share the mountpoint lock, so
    // the whole group has to die for the mount to count as abandoned.
    kill_group(&mut child);
    child.wait().unwrap();
    assert!(
        helper_mount_under(&td.join("xdg-run")).is_some(),
        "the mount outlives its killed runtime"
    );

    let mut run = Command::new(&other);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap());
    isolate(&mut run, &td);
    assert!(
        reclaimed_by(&mut run, std::slice::from_ref(&mountpoint)),
        "the dead mount is gone from the namespace"
    );
    assert!(
        std::fs::symlink_metadata(&mountpoint).is_err(),
        "the dead mount's directory is removed"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A live helper mount belongs to a running instance and is left alone by
/// another package's launch.
#[test]
fn a_live_helper_mount_survives_another_launch() {
    if !fuse_available() || !helperfuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("livemount");
    let sleeper = pack_script(&td, "sleeper", "#!/bin/sh\nsleep 4\n");
    let other = pack_script(&td, "other", "#!/bin/sh\necho OTHER\n");

    let Some((mut child, mountpoint)) = launch_via_helper(&sleeper, &td) else {
        return;
    };

    let mut run = Command::new(&other);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap());
    isolate(&mut run, &td);
    let out = run_package(&mut run);
    assert!(out.status.success());

    assert!(
        helper_mounts_under(&td.join("xdg-run")).contains(&mountpoint),
        "the live mount is still in the namespace"
    );
    assert!(
        mountpoint.join("bin/run").is_file(),
        "the live mount still answers"
    );
    assert!(
        child.try_wait().unwrap().is_none(),
        "the instance is still running"
    );

    // Once the instance is gone its mount is abandoned, and the next launch
    // reclaims it, which also leaves nothing behind on this machine.
    kill_group(&mut child);
    child.wait().unwrap();
    assert!(
        reclaimed_by(&mut run, std::slice::from_ref(&mountpoint)),
        "the abandoned mount is reclaimed"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// Launch `run` until this process's mount namespace lists none of the
/// `abandoned` mounts. A killed group's processes release the mountpoint
/// lock as they die, which is not instantaneous, and a launch that arrives
/// before the last of them is right to leave the mount alone.
///
/// The check names the abandoned mounts rather than asking for none at
/// all: on a host without user namespaces `run` mounts through the helper
/// as well, and its own shared mount stays until its server notices that
/// nothing uses it.
fn reclaimed_by(run: &mut Command, abandoned: &[PathBuf]) -> bool {
    for _ in 0..40 {
        let out = run_package(run);
        assert!(
            out.status.success() && String::from_utf8_lossy(&out.stdout).contains("OTHER"),
            "the next package runs: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        let listed = |mp: &PathBuf| {
            mp.parent()
                .is_some_and(|dir| helper_mounts_under(dir).contains(mp))
        };
        if !abandoned.iter().any(listed) {
            return true;
        }
        std::thread::sleep(std::time::Duration::from_millis(50));
    }
    false
}

/// SIGKILL `child` and every process in its group, and wait for all of
/// it to be gone. `wait` on the child alone reaps the runtime; the app it
/// forked and that app's children are still being torn down for a few
/// milliseconds, and until then they hold the locks they inherited. The
/// child is reaped first, since an unreaped zombie still counts as a
/// member of the group and would hold the poll below to its deadline.
fn kill_group(child: &mut std::process::Child) {
    let group = format!("-{}", child.id());
    let st = Command::new("kill")
        .args(["-9", "--", &group])
        .status()
        .expect("spawn kill");
    assert!(st.success());
    child.wait().unwrap();
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
    loop {
        let alive = Command::new("kill")
            .args(["-0", "--", &group])
            .stderr(std::process::Stdio::null())
            .status()
            .expect("spawn kill")
            .success();
        if !alive || std::time::Instant::now() > deadline {
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(5));
    }
}

/// The app of the sharing tests. It prints its user namespace, the package
/// directory and its data, waits for `$RELEASE` to appear, and prints its
/// data again.
const SHARE_APP: &str = r#"#!/bin/sh
echo "ns=$(readlink /proc/self/ns/user) dir=$ONELF_DIR data=$(cat "$ONELF_DIR/data.txt")"
i=0
while [ ! -e "$RELEASE" ] && [ $i -lt 400 ]; do sleep 0.05; i=$((i+1)); done
echo "data=$(cat "$ONELF_DIR/data.txt")"
"#;

/// Pack [`SHARE_APP`] with `data` as its data to `out`. Every package it
/// makes has the same name, so only the content tells them apart.
fn pack_share_app(td: &Path, data: &str, out: &Path) {
    let app = td.join("share-app");
    write(&app.join("data.txt"), data);
    write(&app.join("bin/run"), SHARE_APP);
    std::fs::set_permissions(
        app.join("bin/run"),
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();
    let o = Command::new(onelf())
        .args(["pack", app.to_str().unwrap(), "-o", out.to_str().unwrap()])
        .args(["--command", "bin/run", "--mtime", "0", "--name", "shareapp"])
        .output()
        .expect("spawn onelf pack");
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
}

/// Start [`SHARE_APP`] packed at `pkg` and return it with the first line
/// it printed, which it prints once it runs.
fn start_share_app(pkg: &Path, td: &Path, envs: &[(&str, &str)]) -> (std::process::Child, String) {
    use std::io::BufRead;

    let mut cmd = Command::new(pkg);
    cmd.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", "fuse")
        .env("RELEASE", td.join("release"))
        .envs(envs.iter().copied())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    isolate(&mut cmd, td);
    let mut child = spawn_package(&mut cmd);
    let mut line = String::new();
    std::io::BufReader::new(child.stdout.as_mut().unwrap())
        .read_line(&mut line)
        .unwrap();
    (child, line)
}

/// Let every [`SHARE_APP`] started under `td` finish, and return what
/// each printed after its first line.
fn release_share_apps(td: &Path, apps: Vec<std::process::Child>) -> Vec<String> {
    std::fs::write(td.join("release"), "").unwrap();
    apps.into_iter()
        .map(|app| {
            let out = app.wait_with_output().unwrap();
            assert!(
                out.status.success(),
                "{}",
                String::from_utf8_lossy(&out.stderr)
            );
            String::from_utf8_lossy(&out.stdout).into_owned()
        })
        .collect()
}

/// The processes running the packed file at `pkg` itself, whether it is
/// still there or was replaced: the FUSE servers of its launches, and a
/// launch that has not yet started its app.
fn servers_of(pkg: &Path) -> Vec<u32> {
    let replaced = format!("{} (deleted)", pkg.display());
    let mine = std::process::id();
    std::fs::read_dir("/proc")
        .unwrap()
        .flatten()
        .filter_map(|e| {
            let pid: u32 = e.file_name().to_str()?.parse().ok()?;
            let exe = std::fs::read_link(e.path().join("exe")).ok()?;
            (pid != mine && (exe == pkg || exe.to_str() == Some(replaced.as_str()))).then_some(pid)
        })
        .collect()
}

/// The FUSE servers among [`servers_of`]: the processes of `pkg` that
/// hold a FUSE connection. A launch's proxy and the guardian of a shared
/// mount's launch run the packed file too, but serve nothing.
fn fuse_servers_of(pkg: &Path) -> Vec<u32> {
    servers_of(pkg)
        .into_iter()
        .filter(|pid| {
            std::fs::read_dir(format!("/proc/{pid}/fd"))
                .into_iter()
                .flatten()
                .flatten()
                .any(|fd| std::fs::read_link(fd.path()).is_ok_and(|t| t == Path::new("/dev/fuse")))
        })
        .collect()
}

/// Wait for every server of `pkg` to leave. False when one is still
/// running after twice the time a server takes to notice it is unused.
fn servers_gone(pkg: &Path) -> bool {
    for _ in 0..300 {
        if servers_of(pkg).is_empty() {
            return true;
        }
        std::thread::sleep(std::time::Duration::from_millis(50));
    }
    false
}

/// When the process `pid` started, in clock ticks since boot, or None
/// when it has exited. Together with the pid this names one process, the
/// way the runtime's own record check does.
fn started_at(pid: u32) -> Option<u64> {
    let stat = std::fs::read_to_string(format!("/proc/{pid}/stat")).ok()?;
    let (_, rest) = stat.rsplit_once(") ")?;
    let mut fields = rest.split_whitespace();
    if matches!(fields.next()?, "Z" | "X") {
        return None;
    }
    fields.nth(18)?.parse().ok()
}

/// The live shared-mount servers under `td`, as each server's record
/// names one: the server writes its own pid and start time, so a record
/// naming a running process is a server. A launch that joins the mount
/// writes no record, and neither does the guardian it runs under, so
/// this counts servers and never launches.
fn share_servers(td: &Path) -> Vec<(u32, u64)> {
    let mut found = Vec::new();
    let Ok(entries) = std::fs::read_dir(td.join("xdg-run")) else {
        return found;
    };
    for entry in entries.flatten() {
        let name = entry.file_name().into_string().unwrap_or_default();
        if !name.ends_with(".share") {
            continue;
        }
        let Ok(text) = std::fs::read_to_string(entry.path()) else {
            continue;
        };
        let mut fields = text.split_whitespace();
        if !matches!(fields.next(), Some("ns") | Some("host")) {
            continue;
        }
        let pid: u32 = fields.next().and_then(|f| f.parse().ok()).unwrap_or(0);
        let start: u64 = fields.next().and_then(|f| f.parse().ok()).unwrap_or(0);
        if pid > 0 && started_at(pid) == Some(start) {
            found.push((pid, start));
        }
    }
    found.sort();
    found
}

/// Wait for every shared server under `td` to leave. False when one is
/// still running after twice the time a server takes to notice it is
/// unused.
fn share_gone(td: &Path) -> bool {
    for _ in 0..300 {
        if share_servers(td).is_empty() {
            return true;
        }
        std::thread::sleep(std::time::Duration::from_millis(50));
    }
    false
}

/// What a mount leaves in the test's runtime directory: its mountpoint,
/// and the record and lease of a shared one. The mountpoints' claim locks
/// are reclaimed by a later sweep and are not counted.
fn mount_leftovers(td: &Path) -> Vec<String> {
    let mut names: Vec<String> = std::fs::read_dir(td.join("xdg-run"))
        .unwrap()
        .flatten()
        .filter_map(|e| e.file_name().into_string().ok())
        .filter(|n| n.starts_with("onelf-") || n.ends_with(".share") || n.ends_with(".lease"))
        .collect();
    names.sort();
    names
}

/// A second launch of a package that is already running runs from the
/// same mount, served by the same server, instead of mounting the package
/// again and decompressing all of it a second time. Through a namespace
/// that means joining the first launch's. The server leaves once both
/// are done, and takes its mount and files with it.
#[test]
fn concurrent_launches_share_one_mount_and_server() {
    if !fuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("share");
    let pkg = td.join("share.onelf");
    pack_share_app(&td, "one", &pkg);
    for helper in [false, true] {
        if helper && !helperfuse_available() {
            continue;
        }
        let envs: &[(&str, &str)] = if helper {
            &[("ONELF_FUSE_NO_NAMESPACE", "1")]
        } else {
            &[]
        };
        let _ = std::fs::remove_file(td.join("release"));
        let (a, a_line) = start_share_app(&pkg, &td, envs);
        let (b, b_line) = start_share_app(&pkg, &td, envs);
        let servers = share_servers(&td);
        let rest = release_share_apps(&td, vec![a, b]);

        assert!(a_line.contains("data=one"), "helper={helper}: {a_line}");
        assert_eq!(
            a_line, b_line,
            "helper={helper}: both launches run in one namespace from one mount"
        );
        assert_eq!(
            servers.len(),
            1,
            "helper={helper}: one server for both launches, found {servers:?}"
        );
        assert!(rest.iter().all(|r| r.contains("data=one")), "{rest:?}");
        assert!(share_gone(&td), "helper={helper}: the server stays");
        assert_eq!(
            mount_leftovers(&td),
            Vec::<String>::new(),
            "helper={helper}"
        );
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// The server leaves after the last launch, and the next launch starts a
/// server of its own rather than finding the old one's files.
#[test]
fn a_launch_after_the_last_has_left_starts_a_fresh_server() {
    if !fuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("share-again");
    let pkg = td.join("again.onelf");
    pack_share_app(&td, "one", &pkg);

    let (a, _) = start_share_app(&pkg, &td, &[]);
    let first = fuse_servers_of(&pkg);
    release_share_apps(&td, vec![a]);
    assert_eq!(first.len(), 1, "{first:?}");
    assert!(servers_gone(&pkg), "the server stays after its last launch");
    assert_eq!(mount_leftovers(&td), Vec::<String>::new());

    std::fs::remove_file(td.join("release")).unwrap();
    let (b, b_line) = start_share_app(&pkg, &td, &[]);
    let second = fuse_servers_of(&pkg);
    let rest = release_share_apps(&td, vec![b]);
    assert!(b_line.contains("data=one"), "{b_line}");
    assert!(rest[0].contains("data=one"), "{rest:?}");
    assert_eq!(second.len(), 1, "{second:?}");
    assert_ne!(first, second, "the old server was found again");
    assert!(servers_gone(&pkg));
    let _ = std::fs::remove_dir_all(&td);
}

/// A package file replaced while it runs, as a self-update does, is a new
/// package. A launch of the new file never runs from the mount serving the
/// old one, and the running instance keeps reading the old contents.
#[test]
fn a_replaced_package_is_not_served_from_the_old_mount() {
    if !fuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("share-replaced");
    let pkg = td.join("replaced.onelf");
    pack_share_app(&td, "one", &pkg);
    for helper in [false, true] {
        if helper && !helperfuse_available() {
            continue;
        }
        let envs: &[(&str, &str)] = if helper {
            &[("ONELF_FUSE_NO_NAMESPACE", "1")]
        } else {
            &[]
        };
        let _ = std::fs::remove_file(td.join("release"));
        let (old, old_line) = start_share_app(&pkg, &td, envs);

        let staged = td.join("replaced.onelf.new");
        pack_share_app(&td, "two", &staged);
        std::fs::rename(&staged, &pkg).unwrap();
        let (new, new_line) = start_share_app(&pkg, &td, envs);
        let servers = fuse_servers_of(&pkg);
        let rest = release_share_apps(&td, vec![old, new]);

        assert!(old_line.contains("data=one"), "helper={helper}: {old_line}");
        assert!(
            new_line.contains("data=two"),
            "helper={helper}: the new file was served from the old mount: {new_line}"
        );
        let dir = |line: &str| {
            line.split_whitespace()
                .find(|w| w.starts_with("dir="))
                .map(String::from)
        };
        assert_ne!(dir(&old_line), dir(&new_line), "helper={helper}");
        assert_eq!(servers.len(), 2, "helper={helper}: {servers:?}");
        assert!(rest[0].contains("data=one"), "helper={helper}: {rest:?}");
        assert!(rest[1].contains("data=two"), "helper={helper}: {rest:?}");
        assert!(servers_gone(&pkg), "helper={helper}");
        assert_eq!(
            mount_leftovers(&td),
            Vec::<String>::new(),
            "helper={helper}"
        );
        pack_share_app(&td, "one", &pkg);
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// `ONELF_FUSE_NO_SHARE` gives every launch a mount and a server of its
/// own, as before mounts were shared.
#[test]
fn the_share_opt_out_gives_each_launch_its_own_mount() {
    if !fuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("share-optout");
    let pkg = td.join("optout.onelf");
    pack_share_app(&td, "one", &pkg);
    for helper in [false, true] {
        if helper && !helperfuse_available() {
            continue;
        }
        let mut envs = vec![("ONELF_FUSE_NO_SHARE", "1")];
        if helper {
            envs.push(("ONELF_FUSE_NO_NAMESPACE", "1"));
        }
        let _ = std::fs::remove_file(td.join("release"));
        let (a, a_line) = start_share_app(&pkg, &td, &envs);
        let (b, b_line) = start_share_app(&pkg, &td, &envs);
        let servers = fuse_servers_of(&pkg);
        release_share_apps(&td, vec![a, b]);

        assert_ne!(a_line, b_line, "helper={helper}: the launches shared");
        assert_eq!(servers.len(), 2, "helper={helper}: {servers:?}");
        assert!(servers_gone(&pkg), "helper={helper}");
        assert_eq!(
            mount_leftovers(&td),
            Vec::<String>::new(),
            "helper={helper}"
        );
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// A shared server that is killed leaves its mountpoint, its record and
/// its lease, and through the helper a mount as well. The next launch of
/// any package reclaims all of it.
#[test]
fn a_killed_shared_server_is_reclaimed_by_the_next_launch() {
    if !fuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("share-killed");
    let pkg = td.join("killed.onelf");
    pack_share_app(&td, "one", &pkg);
    let other = pack_script(&td, "other", "#!/bin/sh\necho OTHER\n");
    for helper in [false, true] {
        if helper && !helperfuse_available() {
            continue;
        }
        let envs: &[(&str, &str)] = if helper {
            &[("ONELF_FUSE_NO_NAMESPACE", "1")]
        } else {
            &[]
        };
        let (mut app, _) = start_share_app(&pkg, &td, envs);
        for pid in servers_of(&pkg) {
            let st = Command::new("kill")
                .args(["-9", &pid.to_string()])
                .status()
                .unwrap();
            assert!(st.success());
        }
        app.kill().unwrap();
        app.wait().unwrap();
        assert!(servers_gone(&pkg));
        assert!(
            !mount_leftovers(&td).is_empty(),
            "helper={helper}: a killed server leaves its files"
        );

        let abandoned = helper_mounts_under(&td.join("xdg-run"));
        let mut run = Command::new(&other);
        run.env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap());
        isolate(&mut run, &td);
        // The killed app's last `sleep` outlives it for a moment and holds
        // the mount, so a launch that arrives first rightly leaves it to a
        // later one.
        let mut left = Vec::new();
        for _ in 0..20 {
            assert!(
                reclaimed_by(&mut run, &abandoned),
                "helper={helper}: the mount stays"
            );
            // The reclaiming launch shares a mount of its own, gone once its
            // server has noticed nothing uses it.
            assert!(servers_gone(&other), "helper={helper}");
            left = mount_leftovers(&td);
            if left.is_empty() {
                break;
            }
        }
        assert_eq!(left, Vec::<String>::new(), "helper={helper}");
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// A launch that joins a running instance's mount keeps the mount with a
/// lifetime guardian of its own, and the server it shares stays only a
/// transport.
///
/// Two launches of one package share a mount. The second one's app
/// daemonizes, drops every descriptor it inherited, and replaces itself
/// with a program that runs from outside the mount. From then on nothing
/// of that launch runs out of the mount and no descriptor of its claims
/// exists anywhere in it, so the only thing that still holds the mount is
/// its guardian's lease. The first launch then dies while that is true,
/// and the mount must stay: not because a process of the first launch
/// lives, and not because the server holds a claim of its own, but
/// because the second launch's guardian holds a lease of its own against
/// the mount they share. When the second launch's last process is gone,
/// the mount goes with it.
#[test]
fn a_join_launch_holds_the_mount_with_its_own_guardian() {
    if !fuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("share-guardian");
    let app = td.join("app");
    let src = td.join("role.c");
    let bin = app.join("bin/run");
    std::fs::create_dir_all(bin.parent().unwrap()).unwrap();
    write(&app.join("data.txt"), "payload\n");
    let pid_file = td.join("daemon.pid");
    write(
        &src,
        &format!(
            "#include <unistd.h>\n#include <stdio.h>\n#include <stdlib.h>\n\
             int main(void){{\n\
             \x20 printf(\"dir=%s\\n\", getenv(\"ONELF_DIR\") ? getenv(\"ONELF_DIR\") : \"unset\");\n\
             \x20 fflush(stdout);\n\
             \x20 if (getenv(\"HOLD\")) {{ sleep(30); return 0; }}\n\
             \x20 if (fork() != 0) {{ _exit(0); }}\n\
             \x20 setsid();\n\
             \x20 chdir(\"/\");\n\
             \x20 for (int fd = 0; fd < 256; fd++) close(fd);\n\
             \x20 FILE *out = fopen(\"{}\", \"w\");\n\
             \x20 if (out) {{ fprintf(out, \"%d\", getpid()); fclose(out); }}\n\
             \x20 execl(\"/bin/sleep\", \"sleep\", \"30\", (char *)0);\n\
             \x20 return 1;\n}}\n",
            pid_file.display()
        ),
    );
    if !cc(&src, &bin) {
        let _ = std::fs::remove_dir_all(&td);
        return;
    }
    let pkg = td.join("shared.onelf");
    let o = Command::new(onelf())
        .args(["pack", app.to_str().unwrap(), "-o", pkg.to_str().unwrap()])
        .args(["--command", "bin/run", "--mtime", "0", "--name", "shared"])
        .output()
        .expect("spawn onelf pack");
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));

    for helper in [false, true] {
        if helper && !helperfuse_available() {
            continue;
        }
        let envs: &[(&str, &str)] = if helper {
            &[("ONELF_FUSE_NO_NAMESPACE", "1")]
        } else {
            &[]
        };
        let _ = std::fs::remove_file(&pid_file);

        // The holder prints the mount it runs from and stays.
        let mut hold = Command::new(&pkg);
        hold.env("ONELF_MODE", "fuse")
            .env("HOLD", "1")
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::null());
        for (k, v) in envs {
            hold.env(k, v);
        }
        isolate(&mut hold, &td);
        let mut holding = spawn_package(&mut hold);
        use std::io::BufRead;
        let mut line = String::new();
        std::io::BufReader::new(holding.stdout.as_mut().unwrap())
            .read_line(&mut line)
            .unwrap();
        let mount_dir = PathBuf::from(line.trim().strip_prefix("dir=").unwrap_or(""));

        // The second launch of the same package finds the record and joins
        // the same mount. Its foreground returns at once; its daemon lives
        // on under the launch's guardian.
        let mut join = Command::new(&pkg);
        join.env("ONELF_MODE", "fuse")
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        for (k, v) in envs {
            join.env(k, v);
        }
        isolate(&mut join, &td);
        let mut joining = spawn_package(&mut join);
        let mut joined_line = String::new();
        std::io::BufReader::new(joining.stdout.as_mut().unwrap())
            .read_line(&mut joined_line)
            .unwrap();
        let status = joining.wait().unwrap();
        assert!(
            status.success(),
            "helper={helper}: the joining launch failed"
        );
        assert_eq!(
            joined_line.trim(),
            line.trim(),
            "helper={helper}: the launch did not join the running mount"
        );

        // The daemon writes its pid once every descriptor it inherited is
        // closed and its executable is outside the mount.
        let mut daemon = String::new();
        for _ in 0..200 {
            if let Ok(pid) = std::fs::read_to_string(&pid_file) {
                daemon = pid.trim().to_string();
                break;
            }
            assert!(
                holding.try_wait().unwrap().is_none(),
                "helper={helper}: the holder left early"
            );
            std::thread::sleep(std::time::Duration::from_millis(50));
        }
        assert!(
            !daemon.is_empty(),
            "helper={helper}: the daemon stayed silent"
        );

        // The holder dies: its launcher forwards the TERM, and its app and
        // guardian go with their claims. The server and the mount must
        // stay, held by the joining launch's guardian alone.
        let _ = Command::new("kill").arg(holding.id().to_string()).status();
        let _ = holding.wait();
        let servers = share_servers(&td);
        assert_eq!(
            servers.len(),
            1,
            "helper={helper}: exactly the one shared server, found {servers:?}"
        );
        let daemon_pid: u32 = daemon.parse().expect("the daemon's pid");
        // The server must stay up continuously: with the daemon running
        // from outside the mount, the lease is the only thing that can
        // hold it, so a window in which it is gone is a window in which
        // the mount was torn down under the joining launch.
        let mut stayed = true;
        for _ in 0..40 {
            if share_servers(&td) != servers || started_at(daemon_pid).is_none() {
                stayed = false;
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(50));
        }
        assert!(
            stayed,
            "helper={helper}: the shared mount did not outlive a launch \
             whose only claim was its guardian's lease"
        );

        // The joining launch's last process goes, its guardian lets the
        // lease go, and the server takes the mount down and its record
        // with it.
        Command::new("kill")
            .arg(daemon_pid.to_string())
            .status()
            .expect("kill the daemon");
        assert!(
            share_gone(&td),
            "helper={helper}: the server stays past its last launch"
        );
        assert_eq!(
            mount_leftovers(&td),
            Vec::<String>::new(),
            "helper={helper}"
        );
        assert!(
            !mount_dir.as_os_str().is_empty() && std::fs::symlink_metadata(&mount_dir).is_err(),
            "helper={helper}: the mountpoint directory is gone"
        );
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// `ONELF_TRACE` records the sysroot-space path of every file the run
/// opened, so a trace can be captured by running the packed app instead
/// of by hand. It works on the FUSE path, which sees every open.
#[test]
fn onelf_trace_records_what_the_run_opened() {
    if !fuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("trace-record");
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    std::fs::create_dir_all(app.join("share/data")).unwrap();
    write(&app.join("share/data/used.txt"), "read me\n");
    write(&app.join("share/data/unused.txt"), "never opened\n");
    write(
        &app.join("bin/run"),
        "#!/bin/sh\ncat \"$ONELF_DIR/share/data/used.txt\"\n",
    );
    std::fs::set_permissions(
        app.join("bin/run"),
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();
    let pkg = td.join("app.onelf");
    let o = Command::new(onelf())
        .args(["pack", app.to_str().unwrap(), "-o", pkg.to_str().unwrap()])
        .args(["--command", "bin/run", "--mtime", "0"])
        .output()
        .expect("spawn onelf pack");
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));

    let trace = td.join("trace.txt");
    let mut run = Command::new(&pkg);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", "fuse")
        .env("ONELF_TRACE", &trace);
    isolate(&mut run, &td);
    let out = run_package(&mut run);
    if !out.status.success() {
        skip("fuse", "FUSE cannot mount here");
        return;
    }

    let recorded = std::fs::read_to_string(&trace).unwrap_or_default();
    let lines: Vec<&str> = recorded.lines().collect();
    assert!(
        lines.contains(&"/usr/bin/run"),
        "the entrypoint is recorded in sysroot space:\n{recorded}"
    );
    assert!(
        lines.contains(&"/usr/share/data/used.txt"),
        "the opened data file is recorded:\n{recorded}"
    );
    assert!(
        !lines.iter().any(|l| l.contains("unused.txt")),
        "a file the run never opened is not recorded:\n{recorded}"
    );
    assert!(
        !lines.iter().any(|l| l.contains(".onelf")),
        "the runtime's own bookkeeping is not recorded:\n{recorded}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// The resolver lists and reads every bundled library before the app
/// starts. Those reads are the runtime's, so a trace leaves them out:
/// a library the run never loaded is not recorded.
#[test]
fn onelf_trace_leaves_out_what_the_runtime_read() {
    if !fuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("trace-runtime");
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    std::fs::create_dir_all(app.join("lib")).unwrap();
    let src = td.join("unused.c");
    write(&src, "int unused(void) { return 1; }\n");
    if !cc_with(
        &["-shared", "-fPIC", src.to_str().unwrap()],
        &app.join("lib/libunused.so.1"),
    ) {
        return;
    }
    write(&app.join("bin/run"), "#!/bin/sh\necho RAN\n");
    std::fs::set_permissions(
        app.join("bin/run"),
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();
    let pkg = td.join("app.onelf");
    let o = Command::new(onelf())
        .args(["pack", app.to_str().unwrap(), "-o", pkg.to_str().unwrap()])
        .args([
            "--command",
            "bin/run",
            "--mtime",
            "0",
            "--host-libs",
            "always",
        ])
        .output()
        .expect("spawn onelf pack");
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));

    let trace = td.join("trace.txt");
    let mut run = Command::new(&pkg);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", "fuse")
        .env("ONELF_TRACE", &trace);
    isolate(&mut run, &td);
    let out = run_package(&mut run);
    if !out.status.success() {
        skip("fuse", "FUSE cannot mount here");
        return;
    }

    let recorded = std::fs::read_to_string(&trace).unwrap_or_default();
    assert!(
        recorded.lines().any(|l| l == "/usr/bin/run"),
        "the entrypoint is recorded:\n{recorded}"
    );
    assert!(
        !recorded.contains("libunused"),
        "a library only the resolver read is not recorded:\n{recorded}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A tree with a script that checksums a data file several blocks long,
/// and that file's checksum as the host computes it.
fn checksum_app(app: &Path) -> String {
    std::fs::create_dir_all(app.join("bin")).unwrap();
    std::fs::create_dir_all(app.join("share")).unwrap();
    let data: Vec<u8> = (0..300_000u32)
        .map(|i| (i.wrapping_mul(2654435761) >> 13) as u8)
        .collect();
    std::fs::write(app.join("share/data.bin"), &data).unwrap();
    write(&app.join("share/unused.bin"), "never read\n");
    write(
        &app.join("bin/run"),
        "#!/bin/sh\ncksum < \"$ONELF_DIR/share/data.bin\"\n",
    );
    std::fs::set_permissions(
        app.join("bin/run"),
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();
    let out = Command::new("cksum")
        .stdin(std::fs::File::open(app.join("share/data.bin")).unwrap())
        .output()
        .expect("spawn cksum");
    String::from_utf8_lossy(&out.stdout).into_owned()
}

/// `ONELF_PROFILE` records the blocks a run read, and a package built with
/// that profile prefetches them. Prefetching only moves decompression
/// earlier: the run reads the same bytes either way.
#[test]
fn onelf_profile_records_blocks_and_prefetching_them_reads_the_same_bytes() {
    if !fuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("profile");
    let app = td.join("app");
    let expected = checksum_app(&app);

    let pack = |out: &Path, extra: &[&str]| {
        let o = Command::new(onelf())
            .args(["pack", app.to_str().unwrap(), "-o", out.to_str().unwrap()])
            .args([
                "--command",
                "bin/run",
                "--mtime",
                "0",
                "--block-size",
                "64K",
            ])
            .args(extra)
            .output()
            .expect("spawn onelf pack");
        assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
        String::from_utf8_lossy(&o.stderr).into_owned()
    };
    let run = |pkg: &Path, profile: Option<&Path>| {
        let mut run = Command::new(pkg);
        run.env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("ONELF_MODE", "fuse");
        if let Some(p) = profile {
            run.env("ONELF_PROFILE", p);
        }
        isolate(&mut run, &td);
        run_package(&mut run)
    };

    let plain = td.join("plain.onelf");
    pack(&plain, &[]);
    let profile = td.join("profile.txt");
    let out = run(&plain, Some(&profile));
    if !out.status.success() {
        skip("fuse", "FUSE cannot mount here");
        return;
    }
    assert_eq!(String::from_utf8_lossy(&out.stdout), expected);

    let recorded = std::fs::read_to_string(&profile).unwrap_or_default();
    let lines: Vec<&str> = recorded.lines().collect();
    for want in ["bin/run\t0", "share/data.bin\t0", "share/data.bin\t262144"] {
        assert!(lines.contains(&want), "{want:?} is recorded:\n{recorded}");
    }
    assert!(
        !recorded.contains("unused.bin"),
        "a file the run never read is not recorded:\n{recorded}"
    );
    let unique: std::collections::HashSet<&str> = lines.iter().copied().collect();
    assert_eq!(unique.len(), lines.len(), "each block once:\n{recorded}");

    // A profile from another build of the tree may name what this one
    // lacks. The packer leaves that out rather than failing.
    let mut stale = recorded.clone();
    stale.push_str("share/gone.bin\t0\nshare/data.bin\t999999999\n");
    std::fs::write(&profile, stale).unwrap();

    let prefetched = td.join("prefetched.onelf");
    let log = pack(&prefetched, &["--prefetch", profile.to_str().unwrap()]);
    assert!(
        log.contains(&format!("Prefetch: {} blocks", lines.len())),
        "every recorded block and nothing else is prefetched:\n{log}"
    );
    let out = run(&prefetched, None);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert_eq!(
        String::from_utf8_lossy(&out.stdout),
        expected,
        "a prefetched run reads the same bytes"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// The profile is part of the package's bytes, so the same tree and the
/// same profile pack to the same package, and leaving the profile out packs
/// what packed before. A recipe names it relative to itself.
#[test]
fn packing_with_a_profile_is_deterministic() {
    let td = workdir("profile-repro");
    let app = td.join("app");
    checksum_app(&app);
    let profile = td.join("profile.txt");
    write(
        &profile,
        "share/data.bin\t65536\nbin/run\t0\nshare/data.bin\t0\n",
    );

    let pack = |name: &str, extra: &[&str]| {
        let out = td.join(name);
        let o = Command::new(onelf())
            .args(["pack", app.to_str().unwrap(), "-o", out.to_str().unwrap()])
            .args([
                "--command",
                "bin/run",
                "--mtime",
                "0",
                "--block-size",
                "64K",
            ])
            .args(extra)
            .output()
            .expect("spawn onelf pack");
        assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
        std::fs::read(out).unwrap()
    };
    let with = ["--prefetch", profile.to_str().unwrap()];
    let plain = pack("a.onelf", &[]);
    assert_eq!(plain, pack("b.onelf", &[]), "no profile: reproducible");
    let profiled = pack("c.onelf", &with);
    assert_eq!(profiled, pack("d.onelf", &with), "a profile: reproducible");
    assert_ne!(plain, profiled, "the profile is packed");

    let listed = Command::new(onelf())
        .args(["list", td.join("c.onelf").to_str().unwrap()])
        .output()
        .expect("spawn onelf list");
    let listed = String::from_utf8_lossy(&listed.stdout);
    assert!(listed.contains(".onelf/prefetch"), "{listed}");

    write(
        &app.join("onelf.toml"),
        "[package]\ncommand = \"bin/run\"\n\n\
         [compression]\nblock-size = 65536\nprefetch = \"../profile.txt\"\n",
    );
    let o = Command::new(onelf())
        .arg("build")
        .arg(&app)
        .arg("-o")
        .arg(td.join("recipe.onelf"))
        .output()
        .expect("spawn onelf build");
    let log = String::from_utf8_lossy(&o.stderr);
    assert!(o.status.success(), "{log}");
    assert!(log.contains("Prefetch: 3 blocks"), "{log}");

    let _ = std::fs::remove_dir_all(&td);
}

/// The runtime directory mode runs the package from the private per-user/// The runtime directory mode runs the package from the private per-user
/// directory and leaves nothing behind when it exits.
#[test]
fn rundir_mode_runs_and_leaves_nothing_behind() {
    let td = workdir("rundir");
    let pkg = pack_script(
        &td,
        "app",
        "#!/bin/sh\necho mode=$ONELF_ACTIVE_MODE\necho dir=$ONELF_DIR\n",
    );

    let mut run = Command::new(&pkg);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", "rundir");
    isolate(&mut run, &td);
    let out = run_package(&mut run);
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        out.status.success() && stdout.contains("mode=rundir"),
        "rundir mode runs:\n{stdout}{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let dir = stdout
        .lines()
        .find_map(|l| l.strip_prefix("dir="))
        .expect("the app reports its directory");
    assert!(
        Path::new(dir).starts_with(td.join("xdg-run")),
        "the tree lives in the private runtime directory: {dir}"
    );
    // The detached guardian removes the tree once its subtree is empty,
    // which can be just after the launcher has returned.
    assert!(
        until(|| std::fs::symlink_metadata(dir).is_err()),
        "the tree is removed after exit"
    );
    assert_eq!(
        std::fs::read_dir(td.join("xdg-cache")).unwrap().count(),
        0,
        "the persistent cache is untouched"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A rundir tree whose every process was killed is removed by the next
/// launch of any package.
#[test]
fn an_abandoned_rundir_tree_is_reclaimed_by_the_next_launch() {
    use std::os::unix::process::CommandExt;

    let td = workdir("rundirkill");
    let sleeper = pack_script(&td, "sleeper", "#!/bin/sh\nsleep 4\n");
    let other = pack_script(&td, "other", "#!/bin/sh\necho OTHER\n");
    let run_dir = td.join("xdg-run");

    let mut cmd = Command::new(&sleeper);
    cmd.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", "rundir")
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .process_group(0);
    isolate(&mut cmd, &td);
    let mut child = cmd.spawn().expect("spawn package");

    let tree_of = |prefix: &str| {
        std::fs::read_dir(&run_dir)
            .ok()?
            .flatten()
            .map(|e| e.path())
            .find(|p| {
                p.file_name()
                    .is_some_and(|n| n.to_string_lossy().starts_with(prefix))
                    && p.join("bin/run").is_file()
            })
    };
    let mut tree = None;
    for _ in 0..200 {
        tree = tree_of("onelf-sleepe");
        if tree.is_some() {
            break;
        }
        assert!(
            child.try_wait().unwrap().is_none(),
            "the sleeper exited early"
        );
        std::thread::sleep(std::time::Duration::from_millis(25));
    }
    let tree = tree.expect("the tree appears");

    kill_group(&mut child);
    child.wait().unwrap();
    assert!(tree.is_dir(), "the tree outlives its killed processes");

    let mut run = Command::new(&other);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", "rundir");
    isolate(&mut run, &td);
    let out = run_package(&mut run);
    assert!(out.status.success());
    assert!(
        std::fs::symlink_metadata(&tree).is_err(),
        "the abandoned tree is removed"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A block whose bytes no longer match the manifest is refused before
/// anything runs, and the file it belonged to is named.
#[test]
fn rundir_refuses_a_tampered_block() {
    let td = workdir("rundirtamper");
    let pkg = pack_script(&td, "app", "#!/bin/sh\necho SHOULD NOT RUN\n");

    let mut data = std::fs::read(&pkg).unwrap();
    let footer_at = data.len() - 76;
    let payload_offset =
        u64::from_le_bytes(data[footer_at + 36..footer_at + 44].try_into().unwrap()) as usize;
    let payload_size =
        u64::from_le_bytes(data[footer_at + 44..footer_at + 52].try_into().unwrap()) as usize;
    data[payload_offset + payload_size / 2] ^= 0xff;
    let tampered = td.join("tampered.onelf");
    std::fs::write(&tampered, data).unwrap();
    std::fs::set_permissions(
        &tampered,
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();

    let mut run = Command::new(&tampered);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", "rundir");
    isolate(&mut run, &td);
    let out = run_package(&mut run);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success());
    assert!(
        !String::from_utf8_lossy(&out.stdout).contains("SHOULD NOT RUN"),
        "nothing runs from a tampered package"
    );
    // Which entry the flipped byte lands in depends on the layout; the
    // refusal names whichever it was.
    assert!(
        stderr.contains("extract failed: ")
            && (stderr.contains("bin/run") || stderr.contains(".onelf/")),
        "the refusal names the file:\n{stderr}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// The persistent cache is the one mode that leaves something behind, so
/// it runs only when the publisher, the user, or a forced mode asks.
#[test]
fn the_cache_is_used_only_on_request() {
    let td = workdir("cacheoptin");
    let pkg = pack_script(&td, "app", "#!/bin/sh\necho mode=$ONELF_ACTIVE_MODE\n");
    let cache_root = td.join("xdg-cache");
    let cache_entries = || std::fs::read_dir(&cache_root).unwrap().count();

    // With every other mode refusing, and nothing asking for the cache,
    // the launch fails and the cache root stays empty. The private
    // directory is owned by this user and closed to others, so it is
    // accepted, but nothing can be created inside it.
    let mut run = Command::new(&pkg);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap());
    isolate(&mut run, &td);
    run.env("XDG_RUNTIME_DIR", "/proc/self/fd");
    let out = run_package(&mut run);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "no mode is available:\n{stderr}");
    assert!(
        stderr.contains("ONELF_CACHE"),
        "the failure says how to allow the cache:\n{stderr}"
    );
    assert_eq!(cache_entries(), 0, "an unrequested cache is never written");

    // The user asks for it.
    run.env("ONELF_CACHE", "1");
    let out = run_package(&mut run);
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        out.status.success() && stdout.contains("mode=cache"),
        "the requested cache runs the package:\n{stdout}{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(cache_entries() > 0);

    // The publisher asks for it.
    let requested = td.join("requested.onelf");
    let o = Command::new(onelf())
        .args(["pack", td.join("app").to_str().unwrap()])
        .args(["-o", requested.to_str().unwrap()])
        .args(["--command", "bin/run", "--mtime", "0", "--cache"])
        .output()
        .expect("spawn onelf pack");
    assert!(o.status.success());
    let mut run = Command::new(&requested);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap());
    isolate(&mut run, &td);
    run.env("XDG_RUNTIME_DIR", "/proc/self/fd");
    let out = run_package(&mut run);
    assert!(
        out.status.success() && String::from_utf8_lossy(&out.stdout).contains("mode=cache"),
        "a package packed with the cache requested falls back to it: {}",
        String::from_utf8_lossy(&out.stderr)
    );

    // A forced cache mode still bypasses everything else.
    let mut run = Command::new(&pkg);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", "cache");
    isolate(&mut run, &td);
    let out = run_package(&mut run);
    assert!(out.status.success() && String::from_utf8_lossy(&out.stdout).contains("mode=cache"));

    let _ = std::fs::remove_dir_all(&td);
}

/// Root that needs a pin another user has already mounted serves its own
/// view from its own verified acquisition, and the user's mount, its
/// server, and its runtime directory are left exactly as they were. The
/// app reports the store root's launch exports, which is root's own
/// store, never the hint naming the user's.
///
/// Skips when the suite can reach neither real root nor a user-namespace
/// root, and when no user FUSE mount can exist here to be left alone.
/// When the suite itself runs as root there is no other user to hold a
/// mount, so the root-side assertions run without the holder.
#[test]
fn root_serves_its_own_set_view_not_a_users_mount() {
    if !root_available() {
        return;
    }
    if !fuse_available() || !helperfuse_available() {
        return; // documented soft-skip
    }
    let td = workdir("rootsetview");
    let Some(base) = root_base(&td) else {
        return;
    };
    let (build, hash, pkg) = pack_pinned_set(&td);
    let store = plant_user_store(&td, &build, &hash);
    let run_dir = td.join("xdg-run");
    // Without a user launch to make it, the user's runtime directory is
    // still the place root must leave alone, so it exists to compare.
    std::fs::create_dir_all(&run_dir).unwrap();

    // A user launch holds a mount of the user's stored copy while root
    // runs. The first line arrives only after the set is acquired and
    // mounted, so the mount is live from here on.
    let held_and_mount = if root_flavor() == Some(RootFlavor::UserNamespace) {
        use std::io::BufRead;
        use std::os::unix::process::CommandExt;

        let mut held_cmd = Command::new(&pkg);
        held_cmd
            .env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("ONELF_MODE", "cache")
            .env("ONELF_PLATFORM_STORE", &store)
            .env("RELEASE", td.join("release"))
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .process_group(0);
        isolate(&mut held_cmd, &td);
        let mut held = spawn_package(&mut held_cmd);
        let mut line = String::new();
        let read = std::io::BufReader::new(held.stdout.as_mut().unwrap())
            .read_line(&mut line)
            .unwrap();
        if read == 0 {
            let out = held.wait_with_output().unwrap();
            panic!(
                "the user launch died before running:\n{}",
                String::from_utf8_lossy(&out.stderr)
            );
        }
        let mut mount = None;
        for _ in 0..200 {
            mount = helper_mount_under(&run_dir);
            if mount.is_some() {
                break;
            }
            assert!(
                held.try_wait().unwrap().is_none(),
                "the user launch died before its mount appeared"
            );
            std::thread::sleep(std::time::Duration::from_millis(25));
        }
        let mount = mount.expect("the user mount of the pinned build never appeared");
        Some((held, mount))
    } else {
        None
    };

    let xdg_before = entries_of(&run_dir);
    let store_before = state_of(&store);

    let mut run = root_command(&base, &pkg);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("ONELF_MODE", "cache")
        .env("ONELF_PLATFORM_STORE", &store);
    let out = run_package(&mut run);
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(
        out.status.success() && stdout.contains("uid=0"),
        "the root launch did not run as root:\n{stdout}{stderr}"
    );
    assert!(
        stdout.contains(&format!(
            "store={}",
            root_base_path().join("platform").display()
        )),
        "root's launch exports its own store, not the user's hint:\n{stdout}"
    );
    assert_eq!(
        files_under(&base.view.join("platform")),
        [format!("fixture/{hash}.onelf")],
        "root acquired its own verified copy:\n{stdout}{stderr}"
    );
    let set_mountpoint = base.view.join(format!("onelf-set-{}", &hash[..16]));
    assert!(
        set_mountpoint.is_dir()
            || files_under(&base.view.join("onelf").join("pkg"))
                .iter()
                .any(|p| p.contains("lib/libfixture.so.1")),
        "root's set view lives neither at its own mountpoint nor in its own cache:\n{stdout}{stderr}"
    );

    if let Some((mut held, mount)) = held_and_mount {
        assert!(
            held.try_wait().unwrap().is_none(),
            "the user launch died while root ran"
        );
        assert_eq!(
            helper_mount_under(&run_dir),
            Some(mount),
            "the user mount was replaced while root ran"
        );
        assert_eq!(
            entries_of(&run_dir),
            xdg_before,
            "root changed the user's runtime directory"
        );
        assert_eq!(
            state_of(&store),
            store_before,
            "root changed the user's store while taking its own view"
        );

        std::fs::write(td.join("release"), "").unwrap();
        let out = held.wait_with_output().unwrap();
        assert!(
            out.status.success(),
            "{}",
            String::from_utf8_lossy(&out.stderr)
        );
        for _ in 0..400 {
            if helper_mount_under(&run_dir).is_none() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(25));
        }
        assert_eq!(
            helper_mount_under(&run_dir),
            None,
            "the user mount outlived its last claim"
        );
    }

    drop(base);
    let _ = std::fs::remove_dir_all(&td);
}

/// Root's private base, its store directories, its published artifact,
/// and its rundir tree keep the privacy they were created with through a
/// failed acquisition, a successful one, and a held launch, and a failed
/// acquisition leaves no staging scratch behind. The app inside reports
/// the base's owner and mode as the runtime's own uid sees them.
///
/// Skips when the suite can reach neither real root nor a
/// user-namespace root.
#[test]
fn root_neither_widens_private_state_nor_leaves_acquisition_scratch() {
    if !root_available() {
        return;
    }
    let td = workdir("rootprivate");
    let Some(base) = root_base(&td) else {
        return;
    };
    let (build, hash, pkg) = pack_pinned_set(&td);
    let store = plant_user_store(&td, &build, &hash);

    let root_run = |envs: &[(&str, &str)]| {
        let mut run = root_command(&base, &pkg);
        run.env_clear().env("PATH", "/usr/bin:/bin");
        for (name, value) in envs {
            run.env(name, value);
        }
        run_package(&mut run)
    };

    // The failed acquisition is tried first, while root's own store is
    // still empty and the launch has to stage the pinned build itself.
    // Both copies root may take are replaced: the import copies what the
    // hinted store holds, the fetch whatever the pin's URL serves.
    let original = std::fs::read(&build).unwrap();
    let mut bytes = original.clone();
    let middle = bytes.len() / 2;
    bytes[middle] ^= 1;
    let user_copy = store.join("fixture").join(format!("{hash}.onelf"));
    std::fs::write(&build, &bytes).unwrap();
    std::fs::write(&user_copy, &bytes).unwrap();
    let out = root_run(&[
        ("ONELF_MODE", "cache"),
        ("ONELF_SET_MODE", "extract"),
        ("ONELF_PLATFORM_STORE", store.to_str().unwrap()),
    ]);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "a tampered source ran:\n{stderr}");
    assert!(
        stderr.contains("dependency set") && stderr.contains("hash mismatch"),
        "the failure names the set and the reason:\n{stderr}"
    );
    std::fs::write(&build, &original).unwrap();
    std::fs::write(&user_copy, &original).unwrap();
    let view = base.view.clone();
    assert_eq!(
        mode_of(&view),
        Some(0o700),
        "root's private base did not stay 0700"
    );
    assert_eq!(
        files_under(&view.join("platform")),
        Vec::<String>::new(),
        "the failed acquisition published nothing"
    );
    assert_eq!(
        entries_of(&view.join("platform")),
        ["444 .fixture.lock", "700 fixture"],
        "the failed acquisition left something besides the publication lock"
    );
    assert_eq!(
        entries_of(&view.join("platform").join("fixture")),
        Vec::<String>::new(),
        "the failed acquisition left staging scratch"
    );
    assert_eq!(
        first_group_or_other_writable(&view),
        None,
        "the failed acquisition left something under root's base writable by group or other"
    );

    // With the tampered source out of the way, the same launch succeeds
    // and publishes a private artifact in a private store.
    let out = root_run(&[
        ("ONELF_MODE", "cache"),
        ("ONELF_SET_MODE", "extract"),
        ("ONELF_PLATFORM_STORE", store.to_str().unwrap()),
    ]);
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(
        out.status.success() && stdout.contains("uid=0"),
        "the successful root launch failed:\n{stdout}{stderr}"
    );
    assert_eq!(
        files_under(&view.join("platform")),
        [format!("fixture/{hash}.onelf")],
        "{stdout}{stderr}"
    );
    assert_eq!(
        mode_of(&view),
        Some(0o700),
        "root's private base did not stay 0700"
    );
    assert_eq!(
        mode_of(&view.join("platform")),
        Some(0o700),
        "root's store directory did not stay 0700"
    );
    assert_eq!(
        mode_of(&view.join("platform").join("fixture")),
        Some(0o700),
        "the label directory did not stay 0700"
    );
    assert_eq!(
        mode_of(
            &view
                .join("platform")
                .join("fixture")
                .join(format!("{hash}.onelf"))
        ),
        Some(0o600),
        "the published artifact did not stay 0600"
    );
    assert_eq!(
        first_group_or_other_writable(&view),
        None,
        "the successful acquisition left something under root's base writable by group or other"
    );

    // A held rundir launch keeps its tree private while it runs, and the
    // tree reports its owner as uid 0 from the inside.
    let probe = pack_script(
        &td,
        "probe",
        r#"#!/bin/sh
echo uid=$(id -u)
echo basemode=$(stat -c %a "$(dirname "$ONELF_DIR")")
echo baseowner=$(stat -c %u "$(dirname "$ONELF_DIR")")
echo treemode=$(stat -c %a "$ONELF_DIR")
sleep 12
"#,
    );
    let mut held_cmd = root_command(&base, &probe);
    use std::os::unix::process::CommandExt;

    held_cmd
        .env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("ONELF_MODE", "rundir")
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .process_group(0);
    let mut held = spawn_package(&mut held_cmd);
    let mut tree = None;
    for _ in 0..200 {
        tree = held_tree(&view);
        if tree.is_some() {
            break;
        }
        assert!(
            held.try_wait().unwrap().is_none(),
            "the rundir launch died before its tree appeared"
        );
        std::thread::sleep(std::time::Duration::from_millis(25));
    }
    let Some(tree) = tree else {
        kill_group(&mut held);
        let out = held.wait_with_output().unwrap();
        panic!(
            "the root rundir tree never appeared:\n{}",
            String::from_utf8_lossy(&out.stderr)
        );
    };
    use std::io::BufRead;
    let mut report = String::new();
    let mut lines = std::io::BufReader::new(held.stdout.as_mut().unwrap());
    for _ in 0..4 {
        let mut line = String::new();
        lines.read_line(&mut line).unwrap();
        report.push_str(&line);
    }
    let line_of = |key: &str| {
        report
            .lines()
            .find_map(|l| l.strip_prefix(key))
            .unwrap_or_else(|| panic!("no {key} in {report}"))
            .to_string()
    };
    assert_eq!(
        line_of("uid="),
        "0",
        "the app did not run as root: {report}"
    );
    let basemode = u32::from_str_radix(&line_of("basemode="), 8).expect("base mode");
    assert!(
        basemode & 0o077 == 0,
        "root's base is not owner-private from the inside: {report}"
    );
    assert_eq!(
        line_of("baseowner="),
        "0",
        "root's base is not owned by uid 0 from the inside: {report}"
    );
    let treemode = u32::from_str_radix(&line_of("treemode="), 8).expect("tree mode");
    assert!(
        treemode & 0o022 == 0,
        "the rundir tree is writable by group or other: {report}"
    );
    assert_eq!(
        mode_of(&tree).map(|m| m & 0o022),
        Some(0),
        "the rundir tree's mode was widened"
    );
    assert_eq!(
        mode_of(&view),
        Some(0o700),
        "root's private base was widened while the launch held it"
    );
    kill_group(&mut held);
    held.wait().unwrap();

    // The next root launch's sweep takes the abandoned tree away.
    let sweeper = pack_script(&td, "sweep", "#!/bin/sh\necho swept\n");
    let mut run = root_command(&base, &sweeper);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("ONELF_MODE", "rundir");
    let out = run_package(&mut run);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    // The sweeper's own tree may still be on its way out when its launch
    // returns, so the check names the abandoned tree itself.
    assert!(
        std::fs::symlink_metadata(&tree).is_err(),
        "the abandoned tree was not reclaimed"
    );
    assert_eq!(mode_of(&view), Some(0o700));
    assert_eq!(
        first_group_or_other_writable(&view),
        None,
        "the sweep left something under root's base writable by group or other"
    );

    drop(base);
    let _ = std::fs::remove_dir_all(&td);
}

/// With fetching disabled and the pin's source gone, root imports the
/// pinned build from the hinted user store into its own store and runs
/// from that private copy. A tampered user copy is refused on its digest
/// with nothing published. Both outcomes leave the hinted store
/// byte-for-byte identical: contents, modes, owners, sizes, and
/// modification times, verified against a snapshot of the whole tree.
/// Once imported, root's own copy serves even with the user store gone.
///
/// Skips when the suite can reach neither real root nor a
/// user-namespace root. When the suite already runs as root the planted
/// store's owner is uid 0 as well, so the owner comparison is weaker
/// there than the content, mode, and time comparisons.
#[test]
fn root_leaves_a_hinted_user_store_byte_identical() {
    if !root_available() {
        return;
    }
    let td = workdir("rootuserstore");
    let Some(base) = root_base(&td) else {
        return;
    };
    let (build, hash, pkg) = pack_pinned_set(&td);
    let store = plant_user_store(&td, &build, &hash);
    let user_copy = store.join("fixture").join(format!("{hash}.onelf"));
    // The pin's own source is taken away, so whatever root runs can only
    // have come from the hinted store.
    std::fs::rename(&build, td.join("set.onelf.away")).unwrap();

    let root_run = || {
        let mut run = root_command(&base, &pkg);
        run.env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("ONELF_MODE", "cache")
            .env("ONELF_SET_MODE", "extract")
            .env("ONELF_NO_PLATFORM_FETCH", "1")
            .env("ONELF_PLATFORM_STORE", &store);
        run_package(&mut run)
    };

    let original = std::fs::read(&user_copy).unwrap();
    let mut bytes = original.clone();
    let middle = bytes.len() / 2;
    bytes[middle] ^= 1;
    std::fs::write(&user_copy, &bytes).unwrap();
    let tampered = state_of(&store);
    let out = root_run();
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "a tampered import ran:\n{stderr}");
    assert!(
        stderr.contains("hash mismatch") && stderr.contains("fetching is disabled"),
        "the failure names the refusal and the prohibition:\n{stderr}"
    );
    assert_eq!(
        state_of(&store),
        tampered,
        "a failed privileged import changed the user's store"
    );
    assert_eq!(
        files_under(&base.view.join("platform")),
        Vec::<String>::new(),
        "the refused import published something"
    );

    std::fs::write(&user_copy, &original).unwrap();
    let before = state_of(&store);
    let out = root_run();
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(
        out.status.success() && stdout.contains("uid=0"),
        "root did not import the hinted artifact:\n{stdout}{stderr}"
    );
    assert_eq!(
        state_of(&store),
        before,
        "a successful privileged import changed the user's store"
    );
    let published = base
        .view
        .join("platform")
        .join("fixture")
        .join(format!("{hash}.onelf"));
    assert_eq!(
        files_under(&base.view.join("platform")),
        [format!("fixture/{hash}.onelf")],
        "root did not import into its own store:\n{stdout}{stderr}"
    );
    assert_eq!(mode_of(&published), Some(0o600));
    assert_eq!(std::fs::read(&published).unwrap(), original);

    std::fs::remove_dir_all(&store).unwrap();
    let out = root_run();
    assert!(
        out.status.success(),
        "root's imported copy did not serve on its own:\n{}",
        String::from_utf8_lossy(&out.stderr)
    );

    drop(base);
    let _ = std::fs::remove_dir_all(&td);
}

/// Root's cache and execution views never derive from an inherited
/// `HOME` or `XDG_CACHE_HOME`, the way `sudo -E` keeps them: a cache
/// launch extracts under root's own private base, and the user's cache
/// directory and home stay empty.
///
/// Skips when the suite can reach neither real root nor a
/// user-namespace root.
#[test]
fn root_leaves_inherited_home_and_xdg_cache_alone() {
    if !root_available() {
        return;
    }
    let td = workdir("rootxdg");
    let Some(base) = root_base(&td) else {
        return;
    };
    let pkg = pack_script(&td, "app", "#!/bin/sh\necho uid=$(id -u)\n");
    let home = td.join("home");
    let xdg = td.join("xdg-cache");
    for dir in [&home, &xdg] {
        std::fs::create_dir_all(dir).unwrap();
        std::fs::set_permissions(
            dir,
            <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o700),
        )
        .unwrap();
    }

    for preserved in [
        vec![("HOME", &home), ("XDG_CACHE_HOME", &xdg)],
        vec![("HOME", &home)],
    ] {
        let mut run = root_command(&base, &pkg);
        run.env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("ONELF_MODE", "cache");
        for (name, value) in &preserved {
            run.env(name, value);
        }
        let out = run_package(&mut run);
        let stdout = String::from_utf8_lossy(&out.stdout);
        assert!(
            out.status.success() && stdout.contains("uid=0"),
            "the root cache launch failed:\n{stdout}{}",
            String::from_utf8_lossy(&out.stderr)
        );
        assert_eq!(
            entries_of(&xdg),
            Vec::<String>::new(),
            "root wrote the user's cache"
        );
        assert_eq!(
            entries_of(&home),
            Vec::<String>::new(),
            "root wrote the user's home"
        );
        assert!(
            !files_under(&base.view.join("onelf").join("pkg")).is_empty(),
            "root's cache is not under its own private base"
        );
    }

    drop(base);
    let _ = std::fs::remove_dir_all(&td);
}

/// `onelf run` makes the same host-library decision as the packed runtime:
/// a host driver reaches its newer dependency through the link farm, and no
/// host directory is placed on the library path.
#[test]
fn onelf_run_resolves_host_libraries_like_the_runtime() {
    let td = workdir("runresolver");
    let app = td.join("app");
    let host = td.join("host");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    std::fs::create_dir_all(app.join("lib")).unwrap();
    std::fs::create_dir_all(&host).unwrap();

    let fixture_c = td.join("fixture.c");
    write(
        &fixture_c,
        "int fix_value(void){return 1;}\nint fix_extra(void){return 2;}\n",
    );
    let old_map = td.join("old.map");
    write(&old_map, "FIX_1.0 { global: fix_value; local: *; };\n");
    let new_map = td.join("new.map");
    write(
        &new_map,
        "FIX_1.0 { global: fix_value; local: *; };\nFIX_2.0 { global: fix_extra; } FIX_1.0;\n",
    );
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libfixture.so.1",
            &format!("-Wl,--version-script={}", old_map.display()),
            fixture_c.to_str().unwrap(),
        ],
        &app.join("lib/libfixture.so.1"),
    ) {
        return; // no compiler: documented soft-skip
    }
    let host_fixture = host.join("libfixture.so.1");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libfixture.so.1",
            &format!("-Wl,--version-script={}", new_map.display()),
            fixture_c.to_str().unwrap(),
        ],
        &host_fixture,
    ));
    let gl_c = td.join("gl.c");
    write(
        &gl_c,
        "int fix_extra(void);\nint gl_probe(void){return fix_extra();}\n",
    );
    let host_gl = host.join("libGL.so.1");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libGL.so.1",
            gl_c.to_str().unwrap(),
            &format!("-L{}", host.display()),
            "-l:libfixture.so.1",
        ],
        &host_gl,
    ));
    let app_c = td.join("app.c");
    write(
        &app_c,
        r#"#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
int main(void) {
    const char *lp = getenv("LD_LIBRARY_PATH");
    printf("LD_LIBRARY_PATH=%s\n", lp ? lp : "");
    void *h = dlopen("libGL.so.1", RTLD_NOW);
    if (!h) { printf("dlopen: %s\n", dlerror()); return 1; }
    int (*probe)(void) = dlsym(h, "gl_probe");
    if (!probe) { printf("dlsym: %s\n", dlerror()); return 1; }
    printf("probe=%d\n", probe());
    return 0;
}
"#,
    );
    assert!(cc_with(
        &[app_c.to_str().unwrap(), "-ldl"],
        &app.join("bin/app")
    ));

    let cache = td.join("ld.so.cache");
    std::fs::write(&cache, ld_so_cache(&[&host_gl, &host_fixture])).unwrap();

    let launch = |no_resolver: bool| {
        let mut run = Command::new(onelf());
        run.args(["run", app.to_str().unwrap(), "--command", "bin/app"])
            .env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("ONELF_LD_CACHE", &cache);
        if no_resolver {
            run.env("ONELF_NO_RESOLVER", "1");
        }
        isolate(&mut run, &td);
        run.output().expect("spawn onelf run")
    };

    let without = launch(true);
    assert!(
        !without.status.success(),
        "without the resolver the driver must fail to bind: {}",
        String::from_utf8_lossy(&without.stdout)
    );

    let with = launch(false);
    let stdout = String::from_utf8_lossy(&with.stdout);
    assert!(
        with.status.success() && stdout.contains("probe=2"),
        "with the resolver the host driver binds against the host copy:\n{stdout}{}",
        String::from_utf8_lossy(&with.stderr)
    );
    let lp = stdout
        .lines()
        .find_map(|l| l.strip_prefix("LD_LIBRARY_PATH="))
        .expect("the app reports its library path");
    for dir in lp.split(':').filter(|d| !d.is_empty()) {
        assert!(
            Path::new(dir).starts_with(&td),
            "a host directory reached the library path: {dir}"
        );
    }

    let _ = std::fs::remove_dir_all(&td);
}

/// A synthetic Arch-style sysroot: a rootfs with a pacman database and
/// compiled fixtures, archived with the host's `tar`.
struct SysrootFixture {
    rootfs: PathBuf,
    archive: PathBuf,
    platform_line: PathBuf,
    policy: PathBuf,
    /// A "host" holding the platform-line driver, for running the result.
    ld_cache: PathBuf,
    /// The GL build the sysroot pins, made with `onelf sysroot pack-gl`.
    gl_build: PathBuf,
    gl_hash: String,
}

/// Pack a GL build holding `libGL.so.1` from the rootfs and return its
/// path and hash, as `pack-gl` prints it.
fn pack_gl_build(td: &Path, rootfs: &Path) -> (PathBuf, String) {
    let tree = td.join("gl-tree");
    std::fs::create_dir_all(tree.join("lib")).unwrap();
    std::fs::copy(
        rootfs.join("usr/lib/libGL.so.1"),
        tree.join("lib/libGL.so.1"),
    )
    .unwrap();
    let build = td.join("gl.onelf");
    let out = Command::new(onelf())
        .args(["sysroot", "pack-gl"])
        .arg(&tree)
        .arg("-o")
        .arg(&build)
        .output()
        .expect("spawn onelf sysroot pack-gl");
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let stdout = String::from_utf8_lossy(&out.stdout);
    let hash = stdout
        .lines()
        .find_map(|l| l.strip_prefix("blake3 = \""))
        .and_then(|l| l.strip_suffix('"'))
        .unwrap_or_else(|| panic!("no hash line in:\n{stdout}"))
        .to_string();
    assert_eq!(hash.len(), 64);
    (build, hash)
}

/// Write a package's `desc` and `files` into the database under `rootfs`.
fn write_pacman_entry(
    rootfs: &Path,
    name: &str,
    version: &str,
    depends: &[&str],
    optdepends: &[&str],
    files: &[&str],
) {
    let dir = rootfs
        .join("var/lib/pacman/local")
        .join(format!("{name}-{version}"));
    std::fs::create_dir_all(&dir).unwrap();
    let mut desc = format!("%NAME%\n{name}\n\n%VERSION%\n{version}\n\n");
    if !depends.is_empty() {
        desc.push_str(&format!("%DEPENDS%\n{}\n\n", depends.join("\n")));
    }
    if !optdepends.is_empty() {
        desc.push_str(&format!("%OPTDEPENDS%\n{}\n\n", optdepends.join("\n")));
    }
    std::fs::write(dir.join("desc"), desc).unwrap();
    let mut listing = String::from("%FILES%\n");
    for f in files {
        let mut prefix = String::new();
        for part in f.split('/').take(f.split('/').count() - 1) {
            prefix.push_str(part);
            prefix.push('/');
            listing.push_str(&prefix);
            listing.push('\n');
        }
        listing.push_str(f);
        listing.push('\n');
    }
    std::fs::write(dir.join("files"), listing).unwrap();
}

fn synthetic_sysroot(td: &Path) -> Option<SysrootFixture> {
    let rootfs = td.join("rootfs");
    for d in [
        "usr/bin",
        "usr/lib/fixture/plugins",
        "usr/lib/fixture/backends",
        "usr/lib/qt6/plugins/platforms",
        "usr/lib/extra",
        "usr/lib/x86_64-linux-gnu",
        "usr/share/doc/libfixture",
        "usr/share/fixture",
    ] {
        std::fs::create_dir_all(rootfs.join(d)).unwrap();
    }
    let src = td.join("src");
    std::fs::create_dir_all(&src).unwrap();

    // A backend reached only through the library's own run path, in a
    // subdirectory, the way libproxy loads its backends.
    write(
        &src.join("backend.c"),
        "int backend_value(void){return 1;}\n",
    );
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libbackend.so.1",
            src.join("backend.c").to_str().unwrap(),
        ],
        &rootfs.join("usr/lib/fixture/backends/libbackend.so.1"),
    ) {
        return None; // no compiler: documented soft-skip
    }
    write(
        &src.join("fixture.c"),
        "int backend_value(void);\nint fix_value(void){return 40 + backend_value();}\n",
    );
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libfixture.so.1",
            src.join("fixture.c").to_str().unwrap(),
            &format!("-L{}", rootfs.join("usr/lib/fixture/backends").display()),
            "-l:libbackend.so.1",
            "-Wl,-rpath,/usr/lib/fixture/backends",
        ],
        &rootfs.join("usr/lib/libfixture.so.1.0.0"),
    ));
    // A toolkit plugin directory, so the launch can name it to Qt.
    write(&src.join("qfake.c"), "int qfake(void){return 1;}\n");
    assert!(cc_with(
        &["-shared", "-fPIC", src.join("qfake.c").to_str().unwrap(),],
        &rootfs.join("usr/lib/qt6/plugins/platforms/libqfake.so"),
    ));
    // The soname is a link to the versioned file, as a distribution
    // installs it.
    std::os::unix::fs::symlink(
        "libfixture.so.1.0.0",
        rootfs.join("usr/lib/libfixture.so.1"),
    )
    .unwrap();
    for (name, out) in [
        ("plugin_a", "usr/lib/fixture/plugins/a.so"),
        ("plugin_b", "usr/lib/fixture/plugins/b.so"),
        ("extra", "usr/lib/extra/libextra.so"),
    ] {
        write(
            &src.join(format!("{name}.c")),
            &format!("int {name}(void){{return 1;}}\n"),
        );
        assert!(cc_with(
            &[
                "-shared",
                "-fPIC",
                src.join(format!("{name}.c")).to_str().unwrap()
            ],
            &rootfs.join(out),
        ));
    }
    // Plugins for a stack the sysroot does not hold: one needs a missing
    // library directly, one through a library of its own package.
    write(&src.join("missing.c"), "int missing(void){return 0;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libmissing.so.9",
            src.join("missing.c").to_str().unwrap(),
        ],
        &src.join("libmissing.so.9"),
    ));
    for (name, out, needs) in [
        (
            "plugin_c",
            "usr/lib/fixture/plugins/c.so",
            "libmissing.so.9",
        ),
        (
            "chainlib",
            "usr/lib/libchainlib.so.1.0.0",
            "libmissing.so.9",
        ),
        (
            "plugin_d",
            "usr/lib/fixture/plugins/d.so",
            // Linked against the file; the need recorded is its soname.
            "libchainlib.so.1.0.0",
        ),
    ] {
        write(
            &src.join(format!("{name}.c")),
            &format!("int {name}(void){{return 1;}}\n"),
        );
        assert!(cc_with(
            &[
                "-shared",
                "-fPIC",
                &format!(
                    "-Wl,-soname,{}",
                    // The soname is the name dependants use, which for a
                    // versioned file is not the file's own name.
                    Path::new(out)
                        .file_name()
                        .unwrap()
                        .to_str()
                        .unwrap()
                        .trim_end_matches(".0.0")
                ),
                src.join(format!("{name}.c")).to_str().unwrap(),
                &format!("-L{}", src.display()),
                &format!("-L{}", rootfs.join("usr/lib").display()),
                &format!("-l:{needs}"),
            ],
            &rootfs.join(out),
        ));
    }
    // A library only the GL package depends on. The platform line hands
    // GL to the host, so a set's build never carries this, and a bundle
    // that thinks otherwise ships without it.
    write(&src.join("helper.c"), "int helper(void){return 0;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libhelper.so.1",
            src.join("helper.c").to_str().unwrap(),
        ],
        &rootfs.join("usr/lib/libhelper.so.1"),
    ));
    write(&src.join("gl.c"), "int gl_probe(void){return 1;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libGL.so.1",
            src.join("gl.c").to_str().unwrap(),
        ],
        &rootfs.join("usr/lib/libGL.so.1"),
    ));
    // A Debian multiarch library: its package is the host's by a
    // top-level .so in a directory the flat four-dir list used to miss.
    write(&src.join("egl.c"), "int egl_probe(void){return 0;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libEGL.so.1",
            src.join("egl.c").to_str().unwrap(),
        ],
        &rootfs.join("usr/lib/x86_64-linux-gnu/libEGL.so.1"),
    ));
    write(
        &src.join("app.c"),
        "#include <spawn.h>\n#include <stdio.h>\n#include <stdlib.h>\n#include <sys/wait.h>\n#include <unistd.h>\nextern char **environ;\nint fix_value(void);\nint gl_probe(void);\nint helper(void);\nint main(void){printf(\"value=%d\\n\", fix_value() + gl_probe() + helper());const char *q = getenv(\"QT_PLUGIN_PATH\");if (q && getenv(\"SHOW_QT\")) printf(\"qt=%s\\n\", q);if (getenv(\"SHOW_DATA\")) {FILE *f = fopen(\"/usr/share/fixture/data.txt\", \"r\");char buf[64] = {0};if (f && fgets(buf, sizeof buf, f)) printf(\"data=%s\", buf);else printf(\"data=missing\\n\");if (f) fclose(f);}if (getenv(\"SHOW_LP\")) {const char *l = getenv(\"LD_LIBRARY_PATH\");printf(\"app_lp=%s\\n\", l ? l : \"(unset)\");}if (getenv(\"SHOW_CHILD\")) {fflush(stdout);if (system(\"echo \\\"child_lp=${LD_LIBRARY_PATH-(unset)}\\\"\") != 0) return 1;}if (getenv(\"SPAWN_CHILD\")) {fflush(stdout);pid_t pid;int st;char *sh[] = {\"sh\", \"-c\", \"echo \\\"spawn_lp=${LD_LIBRARY_PATH-(unset)}\\\"\", 0};if (posix_spawnp(&pid, \"sh\", 0, 0, sh, environ) != 0 || waitpid(pid, &st, 0) < 0) return 1;}if (getenv(\"AGAIN\")) printf(\"again\\n\");if (getenv(\"REEXEC\")) {char *argv[] = {\"app\", 0};char *envp[] = {\"AGAIN=1\", 0};fflush(stdout);execve(\"/proc/self/exe\", argv, envp);return 1;}if (getenv(\"HOLD\")) sleep(atoi(getenv(\"HOLD\")));return 0;}\n",
    );
    assert!(cc_with(
        &[
            src.join("app.c").to_str().unwrap(),
            &format!("-L{}", rootfs.join("usr/lib").display()),
            &format!(
                "-Wl,-rpath-link,{}",
                rootfs.join("usr/lib/fixture/backends").display()
            ),
            "-l:libfixture.so.1",
            "-l:libGL.so.1",
            "-l:libhelper.so.1",
        ],
        &rootfs.join("usr/bin/app"),
    ));
    write(&rootfs.join("usr/share/doc/libfixture/README"), "docs\n");
    write(&rootfs.join("usr/share/fixture/data.txt"), "data\n");
    write(&rootfs.join("usr/share/fixture/icons/a.svg"), "<svg/>\n");
    write(&rootfs.join("usr/share/fixture/icons/b.svg"), "<svg/>\n");
    // Absolute, the way Arch links `X11/xkb` to `xkeyboard-config-2`.
    std::os::unix::fs::symlink(
        "/usr/share/fixture/icons",
        rootfs.join("usr/share/fixture/theme"),
    )
    .unwrap();
    write(
        &rootfs.join("usr/lib/fixture/py/pkg/__init__.py"),
        "import pkg.sub\n",
    );
    write(&rootfs.join("usr/lib/fixture/py/pkg/sub/__init__.py"), "\n");
    write(
        &rootfs.join("usr/lib/fixture/py/pkg/sub/lazy.py"),
        "x = 1\n",
    );
    // A plugin whose name collides with the platform line, under a
    // subdirectory: it goes to the host, its package does not.
    write(
        &rootfs.join("usr/lib/fixture/plugins/libGL.so.helper"),
        "not a library\n",
    );

    // A vendor install under opt/, reached the way a distribution does
    // it: a drop-in under etc/ld.so.conf.d and an RPATH in the tool.
    std::fs::create_dir_all(rootfs.join("opt/vendor/lib")).unwrap();
    std::fs::create_dir_all(rootfs.join("etc/ld.so.conf.d")).unwrap();
    write(
        &rootfs.join("etc/ld.so.conf"),
        "include /etc/ld.so.conf.d/*.conf\n",
    );
    write(
        &rootfs.join("etc/ld.so.conf.d/vendor.conf"),
        "/opt/vendor/lib\n",
    );
    write(&src.join("vendor.c"), "int vendor_value(void){return 7;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libvendor.so.1",
            src.join("vendor.c").to_str().unwrap(),
        ],
        &rootfs.join("opt/vendor/lib/libvendor.so.1"),
    ));
    write(
        &src.join("vtool.c"),
        "#include <stdio.h>\nint vendor_value(void);\nint main(void){printf(\"vendor=%d\\n\", vendor_value());return 0;}\n",
    );
    assert!(cc_with(
        &[
            src.join("vtool.c").to_str().unwrap(),
            &format!("-L{}", rootfs.join("opt/vendor/lib").display()),
            "-l:libvendor.so.1",
            "-Wl,--disable-new-dtags,-rpath,/opt/vendor/lib",
        ],
        &rootfs.join("usr/bin/vtool"),
    ));

    let (gl_build, gl_hash) = pack_gl_build(td, &rootfs);
    std::fs::create_dir_all(rootfs.join("etc/onelf")).unwrap();
    write(
        &rootfs.join("etc/onelf/platform.toml"),
        &format!(
            "label = \"platform-test\"\n\n[gl]\nurl = \"file://{}\"\nblake3 = \"{gl_hash}\"\n",
            gl_build.display()
        ),
    );

    // The sysroot's glibc is this machine's, copied in under the package
    // name, so the closure has a libc to bundle.
    let host_libc = ldd_path(&rootfs.join("usr/bin/app"), "libc.so.6")?;
    let host_ld = ldd_path(&rootfs.join("usr/bin/app"), "ld-linux")?;
    std::fs::copy(&host_libc, rootfs.join("usr/lib/libc.so.6")).unwrap();
    std::fs::copy(&host_ld, rootfs.join("usr/lib/ld-linux-x86-64.so.2")).unwrap();

    write_pacman_entry(
        &rootfs,
        "glibc",
        "2.99-1",
        &[],
        &[],
        &["usr/lib/libc.so.6", "usr/lib/ld-linux-x86-64.so.2"],
    );
    write_pacman_entry(
        &rootfs,
        "libfixture",
        "1.0-1",
        &["glibc>=2.30", "mesa-fake", "egl-multi-fake"],
        &[],
        &[
            "usr/lib/libfixture.so.1",
            "usr/lib/libfixture.so.1.0.0",
            "usr/lib/fixture/backends/libbackend.so.1",
            "usr/lib/qt6/plugins/platforms/libqfake.so",
            "usr/lib/libchainlib.so.1.0.0",
            "usr/lib/fixture/plugins/a.so",
            "usr/lib/fixture/plugins/b.so",
            "usr/lib/fixture/plugins/c.so",
            "usr/lib/fixture/plugins/d.so",
            "usr/share/doc/libfixture/README",
            "usr/share/fixture/data.txt",
            "usr/share/fixture/icons/a.svg",
            "usr/share/fixture/icons/b.svg",
            "usr/share/fixture/theme",
            "usr/lib/fixture/py/pkg/__init__.py",
            "usr/lib/fixture/py/pkg/sub/__init__.py",
            "usr/lib/fixture/py/pkg/sub/lazy.py",
            "usr/lib/fixture/plugins/libGL.so.helper",
        ],
    );
    write_pacman_entry(
        &rootfs,
        "extra",
        "1.0-1",
        &[],
        &[],
        &["usr/lib/extra/libextra.so"],
    );
    write_pacman_entry(
        &rootfs,
        "helper",
        "1.0-1",
        &["glibc"],
        &[],
        &["usr/lib/libhelper.so.1"],
    );
    write_pacman_entry(
        &rootfs,
        "egl-multi-fake",
        "1.0-1",
        &["glibc"],
        &[],
        &["usr/lib/x86_64-linux-gnu/libEGL.so.1"],
    );
    write_pacman_entry(
        &rootfs,
        "mesa-fake",
        "1.0-1",
        &["glibc", "helper"],
        &[],
        &["usr/lib/libGL.so.1"],
    );
    write_pacman_entry(
        &rootfs,
        "app",
        "1.0-1",
        &["libfixture", "mesa-fake", "glibc>=2.30"],
        &["extra: more features"],
        &["usr/bin/app"],
    );
    write_pacman_entry(
        &rootfs,
        "vendor",
        "1.0-1",
        &["glibc"],
        &[],
        &[
            "opt/vendor/lib/libvendor.so.1",
            "usr/bin/vtool",
            "etc/ld.so.conf.d/vendor.conf",
        ],
    );

    let archive = td.join("root.tar");
    let st = Command::new("tar")
        .args(["--create", "--file"])
        .arg(&archive)
        .args(["--sort=name", "--owner=0", "--group=0", "-C"])
        .arg(&rootfs)
        .arg(".")
        .status()
        .expect("spawn tar");
    assert!(st.success());

    let platform_line = td.join("platform-line.txt");
    write(
        &platform_line,
        "# the host's GL stack\nlibGL.so\nlibEGL.so\n",
    );
    let policy = td.join("policy.txt");
    write(&policy, "usr/share/doc/**\n");

    let host = td.join("host");
    std::fs::create_dir_all(&host).unwrap();
    std::fs::copy(rootfs.join("usr/lib/libGL.so.1"), host.join("libGL.so.1")).unwrap();
    let ld_cache = td.join("ld.so.cache");
    std::fs::write(&ld_cache, ld_so_cache(&[&host.join("libGL.so.1")])).unwrap();

    Some(SysrootFixture {
        rootfs,
        archive,
        platform_line,
        policy,
        ld_cache,
        gl_build,
        gl_hash,
    })
}

fn sysroot_recipe(dir: &Path, fixture: &SysrootFixture, extra: &str) {
    write(
        &dir.join("onelf.toml"),
        &format!(
            "[package]\ncommand = \"bin/app\"\nmtime = 0\n\n[sysroot]\npath = \"../sysroot\"\narchive = \"{}\"\nplatform-line = \"{}\"\npolicy = \"{}\"\n{extra}",
            fixture.archive.display(),
            fixture.platform_line.display(),
            fixture.policy.display(),
        ),
    );
}

fn onelf_build(dir: &Path) -> std::process::Output {
    Command::new(onelf())
        .arg("build")
        .current_dir(dir)
        .output()
        .expect("spawn onelf build")
}

/// Every file under the AppDir's `bin/` and `lib/` has a counterpart in
/// the sysroot, so nothing came from the packer's machine.
fn assert_bundle_is_from_sysroot(appdir: &Path, rootfs: &Path) {
    for entry in jwalk::WalkDir::new(appdir).sort(true) {
        let entry = entry.unwrap();
        if !entry.file_type().is_file() {
            continue;
        }
        let rel = entry.path().strip_prefix(appdir).unwrap().to_path_buf();
        let rel_s = rel.to_string_lossy();
        if !(rel_s.starts_with("bin/") || rel_s.starts_with("lib/")) {
            continue;
        }
        if rel_s.contains("libonelf-env") {
            continue; // written by the packer itself
        }
        // A dependency the bundler flattened into the library directory
        // sits elsewhere in the sysroot, so the name is what to match.
        let named_in_sysroot = || {
            let name = rel.file_name().unwrap_or_default();
            jwalk::WalkDir::new(rootfs)
                .into_iter()
                .flatten()
                .any(|e| e.file_name() == name)
        };
        assert!(
            rootfs.join("usr").join(&rel).exists() || named_in_sysroot(),
            "{} has no counterpart in the sysroot",
            rel.display()
        );
    }
}

/// The closure of the entrypoint's package comes out of the sysroot with
/// its plugins and data, pruned by the platform line and the policy, and
/// with nothing from the packer's own machine.
#[test]
fn a_sysroot_closure_is_bundled_and_pruned() {
    let td = workdir("sysroot");
    let Some(fixture) = synthetic_sysroot(&td) else {
        return;
    };
    let dir = td.join("app");
    std::fs::create_dir_all(&dir).unwrap();
    sysroot_recipe(&dir, &fixture, "");

    let out = onelf_build(&dir);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "build failed:\n{stderr}");
    assert!(dir.join("bin/app").is_file());
    assert!(dir.join("lib/libfixture.so.1").is_file());
    assert!(
        dir.join("lib/fixture/plugins/a.so").is_file(),
        "a plugin directory no ELF names still arrives"
    );
    assert!(dir.join("share/fixture/data.txt").is_file());
    assert!(
        !dir.join("lib/extra").exists(),
        "an unnamed optional dependency stays out"
    );
    assert!(
        !dir.join("lib/libGL.so.1").exists(),
        "the platform line keeps the driver out"
    );
    assert!(
        !dir.join("lib/x86_64-linux-gnu/libEGL.so.1").exists(),
        "the platform line keeps the multiarch library out"
    );
    assert!(
        stderr.contains("Host packages: egl-multi-fake, mesa-fake")
            && !stderr.contains("libfixture,"),
        "a package is the host's by its top-level libraries only:\n{stderr}"
    );
    assert!(
        stderr.contains("Host-provided:") && stderr.contains("libGL.so.1"),
        "the host-provided library is reported:\n{stderr}"
    );
    assert!(
        !dir.join("share/doc").exists(),
        "the policy removes documentation"
    );
    assert!(
        td.join("sysroot/var/lib/pacman/local").is_dir(),
        "the archive was materialized"
    );
    assert_bundle_is_from_sysroot(&dir, &fixture.rootfs);

    // Naming the optional dependency brings it in.
    sysroot_recipe(&dir, &fixture, "optional = [\"extra\"]\n");
    let out = onelf_build(&dir);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(dir.join("lib/extra/libextra.so").is_file());

    // The package runs, with the driver coming from the host through the
    // resolver as the platform line promised.
    let pkg = dir.join("app.onelf");
    let mut run = Command::new(&pkg);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_LD_CACHE", &fixture.ld_cache);
    isolate(&mut run, &td);
    let out = run_package(&mut run);
    assert!(
        out.status.success() && String::from_utf8_lossy(&out.stdout).contains("value=42"),
        "the packed app runs: {}{}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    );

    // The same closure from the command line, and the sysroot commands.
    let cli_dir = td.join("cli");
    std::fs::create_dir_all(&cli_dir).unwrap();
    let out = Command::new(onelf())
        .args([
            "bundle-libs",
            cli_dir.to_str().unwrap(),
            "--target",
            "bin/app",
        ])
        .args(["--sysroot", td.join("sysroot").to_str().unwrap()])
        .args(["--platform-line", fixture.platform_line.to_str().unwrap()])
        .args(["--policy", fixture.policy.to_str().unwrap()])
        .args(["--sysroot-optional", "extra"])
        .output()
        .expect("spawn onelf bundle-libs");
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(cli_dir.join("bin/app").is_file() && cli_dir.join("lib/extra/libextra.so").is_file());

    let out = Command::new(onelf())
        .args(["sysroot", "info", td.join("sysroot").to_str().unwrap()])
        .output()
        .expect("spawn onelf sysroot info");
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        out.status.success()
            && stdout.contains("packages: 8")
            && stdout.contains("glibc:    2.99-1"),
        "{stdout}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A dependency the sysroot cannot supply fails the build in sysroot mode
/// and only warns in host-scan mode.
#[test]
fn an_unresolved_soname_fails_the_sysroot_build_and_warns_the_host_scan() {
    let td = workdir("sysrootfail");
    let Some(fixture) = synthetic_sysroot(&td) else {
        return;
    };
    let dir = td.join("app");
    std::fs::create_dir_all(&dir).unwrap();
    let out = Command::new(onelf())
        .args(["sysroot", "fetch"])
        .arg(&fixture.archive)
        .arg(td.join("sysroot"))
        .output()
        .expect("spawn onelf sysroot fetch");
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    // The file and every name for it: a soname link alone comes back,
    // since the copy makes the ones a distribution leaves to ldconfig.
    for name in ["libfixture.so.1", "libfixture.so.1.0.0"] {
        let _ = std::fs::remove_file(td.join("sysroot/usr/lib").join(name));
    }
    sysroot_recipe(&dir, &fixture, "");

    let out = onelf_build(&dir);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "sysroot mode must fail:\n{stderr}");
    assert!(
        stderr.contains("libfixture.so.1") && stderr.contains("bin/app"),
        "the failure names the soname and the object:\n{stderr}"
    );

    let out = Command::new(onelf())
        .args(["bundle-libs", dir.to_str().unwrap(), "--target", "bin/app"])
        .env("ONELF_LD_CACHE", &fixture.ld_cache)
        .output()
        .expect("spawn onelf bundle-libs");
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "host-scan mode only warns:\n{stderr}");
    assert!(
        stderr.contains("libfixture.so.1"),
        "the warning names it:\n{stderr}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A trace removes what the test run never opened, keeps the siblings of
/// what it did, and keeps what some bundled object needs.
#[test]
fn a_trace_prunes_unopened_files_but_keeps_siblings_and_needs() {
    let td = workdir("sysroottrace");
    let Some(fixture) = synthetic_sysroot(&td) else {
        return;
    };
    let dir = td.join("app");
    std::fs::create_dir_all(&dir).unwrap();
    let trace = td.join("trace.txt");
    write(
        &trace,
        "/usr/bin/app\n/usr/lib/fixture/plugins/a.so\n/usr/lib/fixture/py/pkg/__init__.py\n",
    );
    let keep = td.join("keep.txt");
    write(&keep, "usr/share/fixture/icons/**\n");
    sysroot_recipe(
        &dir,
        &fixture,
        &format!(
            "trace = \"{}\"\nkeep = \"{}\"\n",
            trace.display(),
            keep.display()
        ),
    );

    let out = onelf_build(&dir);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(
        !dir.join("share/fixture/data.txt").exists(),
        "unopened data is removed"
    );
    assert!(
        dir.join("lib/fixture/plugins/b.so").is_file(),
        "an opened plugin's sibling stays"
    );
    assert!(
        dir.join("lib/libfixture.so.1").is_file(),
        "a needed soname stays"
    );
    assert!(dir.join("lib/libc.so.6").is_file());
    assert!(
        dir.join("lib/fixture/py/pkg/sub/lazy.py").is_file(),
        "a Python package the run touched is kept whole"
    );
    assert!(
        dir.join("share/fixture/icons/b.svg").is_file(),
        "a keep glob protects data the run never opened"
    );
    assert!(
        dir.join("share/fixture/theme/b.svg").is_file(),
        "a link to a directory holding kept files stays, pointing inside"
    );

    let plain = td.join("plain");
    std::fs::create_dir_all(&plain).unwrap();
    sysroot_recipe(&plain, &fixture, "");
    let out = onelf_build(&plain);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(
        plain.join("share/fixture/data.txt").is_file(),
        "no trace, nothing pruned"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A raw ustar header for one small file, for archives `tar` itself
/// refuses to write.
fn raw_tar_entry(name: &str, data: &[u8]) -> Vec<u8> {
    let mut header = [0u8; 512];
    header[..name.len()].copy_from_slice(name.as_bytes());
    header[100..107].copy_from_slice(b"0000644");
    header[108..115].copy_from_slice(b"0000000");
    header[116..123].copy_from_slice(b"0000000");
    header[124..135].copy_from_slice(format!("{:011o}", data.len()).as_bytes());
    header[136..147].copy_from_slice(b"00000000000");
    header[156] = b'0';
    header[257..262].copy_from_slice(b"ustar");
    header[263..265].copy_from_slice(b"00");
    header[148..156].copy_from_slice(b"        ");
    let sum: u32 = header.iter().map(|&b| b as u32).sum();
    header[148..155].copy_from_slice(format!("{sum:06o}\0").as_bytes());
    let mut out = header.to_vec();
    out.extend_from_slice(data);
    out.resize(out.len().div_ceil(512) * 512, 0);
    out.extend_from_slice(&[0u8; 1024]);
    out
}

/// The same archive and recipe give the same bytes, and an archive that
/// reaches outside its directory is refused.
#[test]
fn sysroot_builds_are_reproducible_and_traversal_is_refused() {
    let td = workdir("sysrootrepro");
    let Some(fixture) = synthetic_sysroot(&td) else {
        return;
    };
    let mut outputs = Vec::new();
    for name in ["one", "two"] {
        let dir = td.join(name);
        std::fs::create_dir_all(&dir).unwrap();
        sysroot_recipe(&dir, &fixture, "");
        let out = onelf_build(&dir);
        assert!(
            out.status.success(),
            "{}",
            String::from_utf8_lossy(&out.stderr)
        );
        outputs.push(std::fs::read(dir.join("app.onelf")).unwrap());
    }
    assert!(outputs[0] == outputs[1], "two builds differ");

    // The recipe need not pin a time: the AppDirs written a second
    // apart still pack to the same bytes.
    let mut outputs = Vec::new();
    for name in ["three", "four"] {
        let dir = td.join(name);
        std::fs::create_dir_all(&dir).unwrap();
        sysroot_recipe(&dir, &fixture, "");
        let recipe = std::fs::read_to_string(dir.join("onelf.toml")).unwrap();
        write(&dir.join("onelf.toml"), &recipe.replace("mtime = 0\n", ""));
        let out = Command::new(onelf())
            .arg("build")
            .current_dir(&dir)
            .env_remove("SOURCE_DATE_EPOCH")
            .output()
            .expect("spawn onelf build");
        assert!(
            out.status.success(),
            "{}",
            String::from_utf8_lossy(&out.stderr)
        );
        outputs.push(std::fs::read(dir.join("app.onelf")).unwrap());
        std::thread::sleep(std::time::Duration::from_millis(1100));
    }
    assert!(
        outputs[0] == outputs[1],
        "two builds without a pinned time differ"
    );

    let bad = td.join("bad.tar");
    std::fs::write(&bad, raw_tar_entry("../escape", b"x")).unwrap();
    let out = Command::new(onelf())
        .args(["sysroot", "fetch"])
        .arg(&bad)
        .arg(td.join("badroot"))
        .output()
        .expect("spawn onelf sysroot fetch");
    assert!(!out.status.success());
    assert!(
        String::from_utf8_lossy(&out.stderr).contains("escape"),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(!td.join("escape").exists());

    let _ = std::fs::remove_dir_all(&td);
}

/// A bundle built from a sysroot records what it came from, and `onelf
/// info` reports it; a host-scan bundle reports that nothing is recorded.
#[test]
fn a_sysroot_build_records_its_provenance() {
    let td = workdir("provenance");
    let Some(fixture) = synthetic_sysroot(&td) else {
        return;
    };
    let dir = td.join("app");
    std::fs::create_dir_all(&dir).unwrap();
    sysroot_recipe(&dir, &fixture, "platform = \"platform-test\"\n");
    let out = onelf_build(&dir);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let pkg = dir.join("app.onelf");

    let list = Command::new(onelf())
        .args(["list", pkg.to_str().unwrap()])
        .output()
        .expect("spawn onelf list");
    assert!(String::from_utf8_lossy(&list.stdout).contains(".onelf/provenance.toml"));

    let info = Command::new(onelf())
        .args(["info", pkg.to_str().unwrap()])
        .output()
        .expect("spawn onelf info");
    let stdout = String::from_utf8_lossy(&info.stdout);
    assert!(info.status.success());
    assert!(stdout.contains("Platform:     platform-test"), "{stdout}");
    for line in ["app 1.0-1", "glibc 2.99-1", "libfixture 1.0-1"] {
        assert!(stdout.contains(line), "{line} missing:\n{stdout}");
    }
    assert!(
        !stdout.contains("mesa-fake 1.0-1"),
        "a package whose library the host supplies contributes nothing:\n{stdout}"
    );
    assert!(
        !stdout.contains("extra 1.0-1"),
        "an unnamed optional package is not listed"
    );

    let plain = pack_script(&td, "plain", "#!/bin/sh\necho hi\n");
    let info = Command::new(onelf())
        .args(["info", plain.to_str().unwrap()])
        .output()
        .expect("spawn onelf info");
    assert!(String::from_utf8_lossy(&info.stdout).contains("none recorded"));

    let _ = std::fs::remove_dir_all(&td);
}

/// `pack-gl` builds its tree from the sysroot: the named packages'
/// closure, shared objects and driver description directories only,
/// with glibc left to the package that uses the build.
#[test]
fn pack_gl_builds_its_tree_from_the_sysroot() {
    let td = workdir("packglsysroot");
    let Some(fixture) = synthetic_sysroot(&td) else {
        return;
    };
    let tree = td.join("gl-from-sysroot");
    let build = td.join("gl-from-sysroot.onelf");
    let out = Command::new(onelf())
        .args(["sysroot", "pack-gl"])
        .arg(&tree)
        .arg("-o")
        .arg(&build)
        .arg("--sysroot")
        .arg(&fixture.rootfs)
        .args(["--package", "mesa-fake"])
        .output()
        .expect("spawn onelf sysroot pack-gl");
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{stderr}");
    assert!(
        stderr.contains("3 packages (mesa-fake 1.0-1 and their dependencies)"),
        "{stderr}"
    );
    assert!(tree.join("lib/libGL.so.1").is_file());
    assert!(
        !tree.join("lib/libc.so.6").exists(),
        "glibc's files are left out"
    );
    assert!(String::from_utf8_lossy(&out.stdout).contains("blake3 = \""));

    let out = Command::new(onelf())
        .args(["sysroot", "pack-gl"])
        .arg(td.join("gl-none"))
        .arg("-o")
        .arg(td.join("gl-none.onelf"))
        .arg("--sysroot")
        .arg(&fixture.rootfs)
        .args(["--package", "no-such-package"])
        .output()
        .expect("spawn onelf sysroot pack-gl");
    assert!(!out.status.success());
    assert!(String::from_utf8_lossy(&out.stderr).contains("no package provides no-such-package"));

    let _ = std::fs::remove_dir_all(&td);
}

/// A bundled object whose need no package in the sysroot provides can
/// never load, so the build drops it and everything that needed it, and
/// says so, instead of failing on each in turn.
/// A library a build carries in `lib/` that needs one the sysroot holds
/// outside the closure stops the build: dropping it would ship a GL
/// build without the driver it exists for.
#[test]
fn pack_gl_stops_on_a_library_needing_one_it_does_not_carry() {
    let td = workdir("packglshort");
    let Some(fixture) = synthetic_sysroot(&td) else {
        return;
    };
    let sysroot = td.join("sysroot");
    let st = Command::new("cp")
        .arg("-a")
        .arg(&fixture.rootfs)
        .arg(&sysroot)
        .status()
        .unwrap();
    assert!(st.success());
    let src = td.join("needer.c");
    write(
        &src,
        "int helper(void);\nint driver(void){return helper();}\n",
    );
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libdriver.so.1",
            src.to_str().unwrap(),
            &format!("-L{}", sysroot.join("usr/lib").display()),
            "-l:libhelper.so.1",
        ],
        &sysroot.join("usr/lib/libdriver.so.1"),
    ));
    // The package forgets to depend on what provides libhelper.
    write_pacman_entry(
        &sysroot,
        "driver",
        "1.0-1",
        &["glibc"],
        &[],
        &["usr/lib/libdriver.so.1"],
    );
    let out = Command::new(onelf())
        .args(["sysroot", "pack-gl"])
        .arg(td.join("gl-tree-short"))
        .arg("-o")
        .arg(td.join("gl-short.onelf"))
        .arg("--sysroot")
        .arg(&sysroot)
        .args(["--package", "driver"])
        .output()
        .expect("spawn onelf sysroot pack-gl");
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "{stderr}");
    assert!(
        stderr.contains("lib/libdriver.so.1 needs libhelper.so.1"),
        "{stderr}"
    );
    assert!(!td.join("gl-short.onelf").exists());
    let _ = std::fs::remove_dir_all(&td);
}

#[test]
fn objects_the_sysroot_cannot_satisfy_are_dropped_not_fatal() {
    let td = workdir("unloadable");
    let Some(fixture) = synthetic_sysroot(&td) else {
        return;
    };
    let dir = td.join("app");
    std::fs::create_dir_all(&dir).unwrap();
    sysroot_recipe(&dir, &fixture, "");
    let out = onelf_build(&dir);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{stderr}");
    assert!(drop_lines(&stderr).len() == 3, "{stderr}");
    for gone in [
        "lib/fixture/plugins/c.so",
        "lib/libchainlib.so.1.0.0",
        "lib/fixture/plugins/d.so",
    ] {
        assert!(!dir.join(gone).exists(), "{gone} stays");
        assert!(stderr.contains(gone), "{gone} is named:\n{stderr}");
    }
    // chainlib installs as a versioned file and is needed by its soname,
    // the way a distribution ships one. Dropping it has to take the
    // plugin that needs that soname with it, and the link the copy made
    // for it has to go too.
    assert!(
        !dir.join("lib/libchainlib.so.1").exists(),
        "the soname link goes with the file it named"
    );
    assert!(dir.join("lib/fixture/plugins/a.so").is_file());
    assert!(dir.join("lib/libfixture.so.1").is_file());

    let _ = std::fs::remove_dir_all(&td);
}

/// Only what the sysroot build generated is dropped for an unmet need. A
/// file the publisher placed by hand stays, and the verifier names it:
/// deleting their work under an informational line would hide it.
#[test]
fn a_publisher_file_with_an_unmet_need_is_a_finding_not_dropped() {
    let td = workdir("unloadable-own");
    let Some(fixture) = synthetic_sysroot(&td) else {
        return;
    };
    let dir = td.join("app");
    std::fs::create_dir_all(&dir).unwrap();
    sysroot_recipe(&dir, &fixture, "");
    let mine = dir.join("lib/fixture/plugins/mine.so");
    std::fs::create_dir_all(mine.parent().unwrap()).unwrap();
    std::fs::copy(fixture.rootfs.join("usr/lib/fixture/plugins/c.so"), &mine).unwrap();

    let out = onelf_build(&dir);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "the unmet need is fatal:\n{stderr}");
    assert!(mine.is_file(), "the publisher's file was dropped");
    assert!(
        stderr.contains("lib/fixture/plugins/mine.so") && stderr.contains("libmissing.so.9"),
        "the finding names the file and the soname:\n{stderr}"
    );
    assert!(
        !dir.join("lib/fixture/plugins/c.so").exists(),
        "the generated copy still goes"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// A small sysroot for the outcome-classification tests: the core
/// library the app links, a carried library whose own dependency is
/// absent, two plugin files of its package whose dependencies are
/// absent or sit in an unselected optional package, a library a policy
/// can name, and an optional package the recipe never selects.
/// Returns the rootfs and its archive, or None without a compiler.
fn classification_sysroot(td: &Path) -> Option<(PathBuf, PathBuf)> {
    let rootfs = td.join("rootfs");
    for d in [
        "usr/bin",
        "usr/lib",
        "usr/lib/core/plugins",
        "usr/lib/optprov",
    ] {
        std::fs::create_dir_all(rootfs.join(d)).unwrap();
    }
    let src = td.join("src");
    std::fs::create_dir_all(&src).unwrap();

    write(&src.join("absent.c"), "int absent(void){return 0;}\n");
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libabsent.so.7",
            src.join("absent.c").to_str().unwrap(),
        ],
        &src.join("libabsent.so.7"),
    ) {
        return None;
    }
    write(&src.join("opt.c"), "int opt(void){return 4;}\n");
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libopt.so.1",
            src.join("opt.c").to_str().unwrap(),
        ],
        &src.join("libopt.so.1"),
    ) {
        return None;
    }

    write(&src.join("core.c"), "int core(void){return 1;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libcore.so.2",
            src.join("core.c").to_str().unwrap(),
        ],
        &rootfs.join("usr/lib/libcore.so.2"),
    ));
    // A carried library whose own need the source never had: only the
    // link-time copy exists, in the scratch directory.
    write(
        &src.join("carry.c"),
        "int absent(void);\nint carry(void){return absent();}\n",
    );
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libcarry.so.1",
            src.join("carry.c").to_str().unwrap(),
            &format!("-L{}", src.display()),
            "-l:libabsent.so.7",
        ],
        &rootfs.join("usr/lib/libcarry.so.1"),
    ));
    // A library a policy line can name.
    write(&src.join("pinned.c"), "int pinned(void){return 3;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libpinned.so.1",
            src.join("pinned.c").to_str().unwrap(),
        ],
        &rootfs.join("usr/lib/libpinned.so.1"),
    ));
    // The core package's plugins: one needs a library only an unselected
    // optional package holds, one needs one nothing holds at all.
    write(
        &src.join("backend.c"),
        "int opt(void);\nint backend(void){return opt();}\n",
    );
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libcore-backend.so",
            src.join("backend.c").to_str().unwrap(),
            &format!("-L{}", src.display()),
            "-l:libopt.so.1",
        ],
        &rootfs.join("usr/lib/core/plugins/libcore-backend.so"),
    ));
    write(
        &src.join("broken.c"),
        "int absent(void);\nint broken(void){return absent();}\n",
    );
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libcore-broken.so",
            src.join("broken.c").to_str().unwrap(),
            &format!("-L{}", src.display()),
            "-l:libabsent.so.7",
        ],
        &rootfs.join("usr/lib/core/plugins/libcore-broken.so"),
    ));
    std::fs::copy(
        src.join("libopt.so.1"),
        rootfs.join("usr/lib/optprov/libopt.so.1"),
    )
    .unwrap();

    write(
        &src.join("app.c"),
        "int core(void);\nint pinned(void);\nint main(void){return core() + pinned();}\n",
    );
    assert!(cc_with(
        &[
            src.join("app.c").to_str().unwrap(),
            &format!("-L{}", rootfs.join("usr/lib").display()),
            "-l:libcore.so.2",
            "-l:libpinned.so.1",
        ],
        &rootfs.join("usr/bin/app"),
    ));

    // This machine's glibc, so the closure holds a libc and a loader.
    let host_libc = ldd_path(&rootfs.join("usr/bin/app"), "libc.so.6")?;
    let host_ld = ldd_path(&rootfs.join("usr/bin/app"), "ld-linux")?;
    std::fs::copy(&host_libc, rootfs.join("usr/lib/libc.so.6")).unwrap();
    std::fs::copy(&host_ld, rootfs.join("usr/lib/ld-linux-x86-64.so.2")).unwrap();

    write_pacman_entry(
        &rootfs,
        "glibc",
        "2.99-1",
        &[],
        &[],
        &["usr/lib/libc.so.6", "usr/lib/ld-linux-x86-64.so.2"],
    );
    write_pacman_entry(
        &rootfs,
        "core",
        "1.0-1",
        &["glibc"],
        &[],
        &[
            "usr/lib/libcore.so.2",
            "usr/lib/libcarry.so.1",
            "usr/lib/libpinned.so.1",
            "usr/lib/core/plugins/libcore-backend.so",
            "usr/lib/core/plugins/libcore-broken.so",
        ],
    );
    write_pacman_entry(
        &rootfs,
        "optprov",
        "1.0-1",
        &["glibc"],
        &[],
        &["usr/lib/optprov/libopt.so.1"],
    );
    write_pacman_entry(
        &rootfs,
        "app",
        "1.0-1",
        &["core", "glibc"],
        &["optprov: extra features"],
        &["usr/bin/app"],
    );

    let archive = td.join("root.tar");
    let st = Command::new("tar")
        .args(["--create", "--file"])
        .arg(&archive)
        .args(["--sort=name", "--owner=0", "--group=0", "-C"])
        .arg(&rootfs)
        .arg(".")
        .status()
        .expect("spawn tar");
    assert!(st.success());
    Some((rootfs, archive))
}

/// Build the classification fixture's recipe: `extra` goes into the
/// `[sysroot]` section, `policy` and `trace` name a policy or trace
/// file's contents.
fn classification_build(
    td: &Path,
    recipe_dir: &str,
    policy: Option<&str>,
    trace: Option<&str>,
    extra: &str,
) -> std::process::Output {
    let dir = td.join(recipe_dir);
    std::fs::create_dir_all(&dir).unwrap();
    let mut sysroot = format!(
        "[sysroot]\npath = \"../sysroot-{recipe_dir}\"\narchive = \"{}\"\n",
        td.join("root.tar").display()
    );
    if let Some(policy) = policy {
        let path = td.join(recipe_dir).join("policy.txt");
        write(&path, policy);
        sysroot.push_str(&format!("policy = \"{}\"\n", path.display()));
    }
    if let Some(trace) = trace {
        let path = td.join(recipe_dir).join("trace.txt");
        write(&path, trace);
        sysroot.push_str(&format!("trace = \"{}\"\n", path.display()));
    }
    write(
        &dir.join("onelf.toml"),
        &format!("[package]\ncommand = \"bin/app\"\nmtime = 0\n\n{sysroot}{extra}"),
    );
    let mut c = Command::new(onelf());
    c.arg("build").current_dir(&dir);
    if let Some(pe) = patchelf() {
        c.env("ONELF_PATCHELF", pe);
    }
    c.output().expect("spawn onelf build")
}

/// The omitted auto-selected backends say which class took them out: a
/// dependency nothing holds reads one way, a dependency only an
/// unselected optional package holds reads the other, and neither
/// fails the build or pulls the unselected provider in.
#[test]
fn omitted_backends_name_an_absent_need_and_an_unselected_provider_apart() {
    let td = workdir("verdicts");
    if classification_sysroot(&td).is_none() {
        return;
    }
    let out = classification_build(&td, "app", None, None, "");
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(
        out.status.success(),
        "the omissions are not failures:\n{stderr}"
    );
    let dir = td.join("app");
    assert!(
        drop_lines(&stderr).len() == 3,
        "the plugins and the carried library are omitted:\n{stderr}"
    );
    assert_eq!(
        drop_lines(&stderr),
        vec![
            "  - lib/core/plugins/libcore-backend.so: optional omission: omitted, needs \
             libopt.so.1 (provided only by the unselected optional package optprov)",
            "  - lib/core/plugins/libcore-broken.so: optional omission: omitted, needs \
             libabsent.so.7 (no selected source provides it)",
            "  - lib/libcarry.so.1: optional omission: omitted, needs libabsent.so.7 (no \
             selected source provides it)",
        ],
        "the omission block renders the same bytes every build:\n{stderr}"
    );
    assert!(
        stderr.contains("libcore-broken.so") && stderr.contains("no selected source provides it"),
        "the absent dependency is named as absent:\n{stderr}"
    );
    assert!(
        stderr.contains("libcore-backend.so")
            && stderr.contains("provided only by the unselected optional package optprov"),
        "the unselected provider is named with its package:\n{stderr}"
    );
    assert!(
        !dir.join("lib/core/plugins/libcore-backend.so").exists()
            && !dir.join("lib/core/plugins/libcore-broken.so").exists(),
        "both omissions took their objects out:\n{stderr}"
    );
    assert!(
        !dir.join("lib/optprov").exists() && !dir.join("lib/libopt.so.1").exists(),
        "the unselected package was never selected to fill the gap:\n{stderr}"
    );
    assert!(
        dir.join("lib/libcore.so.2").is_file(),
        "the framework library itself is bundled:\n{stderr}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// Without an include, a carried library whose dependency the source
/// never had is omitted like any other auto-selected object. The same
/// library asked for by name is required: then the omission is refused
/// and the build stops naming the include, rather than quietly shipping
/// without what the author asked for.
#[test]
fn an_explicitly_included_library_is_not_omitted_for_an_absent_need() {
    let td = workdir("include-absent");
    if classification_sysroot(&td).is_none() {
        return;
    }
    let plain = classification_build(&td, "plain", None, None, "");
    let plain_err = String::from_utf8_lossy(&plain.stderr);
    assert!(
        plain.status.success(),
        "the omission is not a failure:\n{plain_err}"
    );
    assert!(
        drop_lines(&plain_err).len() == 3 && !td.join("plain/lib/libcarry.so.1").exists(),
        "without the include the library is omitted like the rest:\n{plain_err}"
    );

    let out = classification_build(
        &td,
        "asked",
        None,
        None,
        "[bundle]\ninclude = [\"libcarry.so.1\"]\n",
    );
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "the include is required:\n{stderr}");
    assert!(
        stderr.contains("lib/libcarry.so.1 is explicitly included")
            && stderr.contains("libabsent.so.7")
            && stderr.contains("an explicit include cannot be dropped"),
        "the failure names the include, its need and the rule:\n{stderr}"
    );
    let error = stderr
        .lines()
        .find(|l| l.starts_with("error: "))
        .expect("the attributed error line");
    assert_eq!(
        error,
        "error: lib/libcarry.so.1 is explicitly included and needs \
         libabsent.so.7: no selected source provides it; an explicit include \
         cannot be dropped",
        "{stderr}"
    );
    assert!(
        td.join("asked/lib/libcarry.so.1").is_file(),
        "the included library is not deleted to make the finding go away:\n{stderr}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// An explicit include a policy would remove fails the build: the
/// classification treats the include as required, the policy is not
/// undone to carry it, and nothing is restored behind the policy's
/// back.
#[test]
fn an_explicit_include_the_policy_prunes_fails_and_is_not_restored() {
    let td = workdir("include-policy");
    if classification_sysroot(&td).is_none() {
        return;
    }
    let out = classification_build(
        &td,
        "app",
        Some("usr/lib/libpinned*"),
        None,
        "[bundle]\ninclude = [\"libpinned.so.1\"]\n",
    );
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(
        !out.status.success(),
        "the removal is a conflict:\n{stderr}"
    );
    assert!(
        stderr.contains("explicitly included libpinned.so.1")
            && stderr.contains("the policy or a trace removed it"),
        "the conflict names the include and the removal:\n{stderr}"
    );
    assert!(
        !td.join("app/lib/libpinned.so.1").exists(),
        "the pruned file is not restored to satisfy the include"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// A retained object's dependency that only the policy removed stops
/// the build with the removal named: the object is not dropped as an
/// omission, the package is not re-selected, and the file stays pruned.
#[test]
fn a_policy_removed_need_of_a_retained_object_names_the_removal() {
    let td = workdir("policy-conflict");
    if classification_sysroot(&td).is_none() {
        return;
    }
    let out = classification_build(&td, "app", Some("usr/lib/libpinned*"), None, "");
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "the conflict is fatal:\n{stderr}");
    assert!(
        stderr.contains("bin/app needs libpinned.so.1")
            && stderr.contains("core holds but the policy or a trace removed"),
        "the failure attributes the dependency to the removal:\n{stderr}"
    );
    let error = stderr
        .lines()
        .find(|l| l.starts_with("error: "))
        .expect("the attributed error line");
    assert_eq!(
        error,
        "error: bin/app needs libpinned.so.1, which core holds but the policy \
         or a trace removed; the conflict stops the build rather than dropping \
         the object or restoring the file (entrypoint 'app')",
        "{stderr}"
    );
    assert_eq!(
        stderr
            .lines()
            .filter(|l| l.starts_with("  - ") && l.contains(": removed: "))
            .collect::<Vec<_>>(),
        vec![
            "  - libpinned.so.1: removed: core holds it, but the policy or a trace \
             removed it (needed by bin/app)",
        ],
        "{stderr}"
    );
    assert!(
        !td.join("app/lib/libpinned.so.1").exists(),
        "the file stays pruned"
    );
    let _ = std::fs::remove_dir_all(&td);
}

