/// A `SOURCE_DATE_EPOCH` that is not a whole number of seconds is unset
/// for the whole build: the sysroot pin to 0 still holds, so two builds a
/// second apart agree, and the value is reported once.
#[test]
fn an_unparsable_source_date_epoch_is_ignored_with_one_warning() {
    let td = workdir("sysroot-bad-epoch");
    let Some(fixture) = synthetic_sysroot(&td) else {
        return;
    };
    let mut outputs = Vec::new();
    for name in ["one", "two"] {
        let dir = td.join(name);
        std::fs::create_dir_all(&dir).unwrap();
        sysroot_recipe(&dir, &fixture, "");
        let recipe = std::fs::read_to_string(dir.join("onelf.toml")).unwrap();
        write(&dir.join("onelf.toml"), &recipe.replace("mtime = 0\n", ""));
        let out = Command::new(onelf())
            .arg("build")
            .current_dir(&dir)
            .env("SOURCE_DATE_EPOCH", "2024-01-01T00:00:00Z")
            .output()
            .expect("spawn onelf build");
        let stderr = String::from_utf8_lossy(&out.stderr);
        assert!(out.status.success(), "{stderr}");
        assert_eq!(stderr.matches("SOURCE_DATE_EPOCH").count(), 1, "{stderr}");
        outputs.push(std::fs::read(dir.join("app.onelf")).unwrap());
        std::thread::sleep(std::time::Duration::from_millis(1100));
    }
    assert!(outputs[0] == outputs[1], "two builds differ");
    let _ = std::fs::remove_dir_all(&td);
}

/// Memfd mode applies the recipe's `[env]`, except a value naming the
/// package tree it does not have, the default `PATH` prefix among them.
#[test]
fn memfd_mode_applies_the_recipe_env_it_can() {
    let td = workdir("memfd-env");
    let app = td.join("app");
    let src = td.join("show.c");
    write(
        &src,
        "#include <stdio.h>\n#include <stdlib.h>\nint main(){\
         const char *v=getenv(\"MEMFD_T_VALUE\");\
         printf(\"value=%s\\npath=%s\\n\",v?v:\"unset\",getenv(\"PATH\"));return 0;}\n",
    );
    let bin = app.join("bin/show");
    std::fs::create_dir_all(bin.parent().unwrap()).unwrap();
    let compiler = if have("cc") {
        "cc"
    } else if have("gcc") {
        "gcc"
    } else {
        skip("cc", "no C compiler available");
        return;
    };
    let built = Command::new(compiler)
        .args(["-O0", "-static", "-o"])
        .arg(&bin)
        .arg(&src)
        .status()
        .map(|s| s.success())
        .unwrap_or(false);
    if !built {
        skip("staticlibc", "no static libc available to link against");
        let _ = std::fs::remove_dir_all(&td);
        return;
    }
    write(
        &app.join("onelf.toml"),
        "[package]\ncommand = \"bin/show\"\noutput = \"../show.onelf\"\n\n\
         [bundle]\nskip = true\n\n[env]\nMEMFD_T_VALUE = \"from-recipe\"\n",
    );
    let out = onelf_build(&app);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );

    let mut c = Command::new(td.join("show.onelf"));
    c.env("ONELF_MODE", "memfd").env("PATH", "/usr/bin:/bin");
    isolate(&mut c, &td);
    let run = run_package(&mut c);
    let stdout = String::from_utf8_lossy(&run.stdout);
    assert!(
        run.status.success(),
        "{}",
        String::from_utf8_lossy(&run.stderr)
    );
    assert!(stdout.contains("value=from-recipe\n"), "{stdout}");
    assert!(stdout.contains("path=/usr/bin:/bin\n"), "{stdout}");
    let _ = std::fs::remove_dir_all(&td);
}

/// A file spanning several verification slices, a copy of it the image
/// stores once, an empty file and a symlink.
fn stipple_app(app: &Path) -> Vec<u8> {
    let data: Vec<u8> = (0..300_000u32)
        .map(|i| (i.wrapping_mul(2654435761) >> 13) as u8)
        .collect();
    std::fs::create_dir_all(app.join("share")).unwrap();
    std::fs::write(app.join("share/data.bin"), &data).unwrap();
    std::fs::write(app.join("share/copy.bin"), &data).unwrap();
    std::fs::write(app.join("share/empty"), b"").unwrap();
    std::os::unix::fs::symlink("data.bin", app.join("share/link.bin")).unwrap();
    write(
        &app.join("bin/run"),
        "#!/bin/sh\ncd \"$ONELF_DIR/share\" && cksum data.bin copy.bin link.bin empty\n",
    );
    std::fs::set_permissions(
        app.join("bin/run"),
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();
    data
}

#[test]
fn a_stipple_payload_runs_in_every_mode_and_extracts() {
    let td = workdir("stipple");
    let app = td.join("app");
    let data = stipple_app(&app);
    let pkg = td.join("s.onelf");
    let o = run_onelf(
        &[
            "pack",
            app.to_str().unwrap(),
            "-o",
            pkg.to_str().unwrap(),
            "--command",
            "bin/run",
            "--payload",
            "stipple",
            "--block-size",
            "128K",
        ],
        None,
    );
    assert!(
        o.status.success(),
        "pack: {}",
        String::from_utf8_lossy(&o.stderr)
    );
    assert!(
        has_footer_flag(&pkg, 1 << 9),
        "the footer must mark the payload"
    );

    let expected = Command::new("sh")
        .arg("-c")
        .arg("cksum data.bin copy.bin link.bin empty")
        .current_dir(app.join("share"))
        .output()
        .unwrap()
        .stdout;
    let mut modes = vec!["rundir", "cache"];
    if fuse_available() {
        modes.push("fuse");
    }
    for mode in modes {
        let mut run = Command::new(&pkg);
        run.env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("ONELF_MODE", mode);
        isolate(&mut run, &td);
        let out = run_package(&mut run);
        assert!(
            out.status.success(),
            "{mode}: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        assert_eq!(
            String::from_utf8_lossy(&out.stdout),
            String::from_utf8_lossy(&expected),
            "{mode} served different bytes"
        );
    }

    let outdir = td.join("out");
    let o = run_onelf(
        &[
            "extract",
            pkg.to_str().unwrap(),
            "-o",
            outdir.to_str().unwrap(),
        ],
        None,
    );
    assert!(
        o.status.success(),
        "extract: {}",
        String::from_utf8_lossy(&o.stderr)
    );
    assert_eq!(std::fs::read(outdir.join("share/copy.bin")).unwrap(), data);
    assert_eq!(
        std::fs::read_link(outdir.join("share/link.bin")).unwrap(),
        Path::new("data.bin")
    );

    let o = run_onelf(&["verify", pkg.to_str().unwrap()], None);
    assert!(
        o.status.success(),
        "verify: {}",
        String::from_utf8_lossy(&o.stderr)
    );

    let _ = std::fs::remove_dir_all(&td);
}

#[test]
fn a_tampered_stipple_image_fails_the_fuse_read() {
    if !fuse_available() {
        return;
    }
    let td = workdir("stippletamper");
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    write(&app.join("bin/run"), "#!/bin/sh\ncat \"$ONELF_DIR/data\"\n");
    std::fs::set_permissions(
        app.join("bin/run"),
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();
    let data: Vec<u8> = (0..200_000u32)
        .map(|i| (i.wrapping_mul(2654435761) >> 13) as u8)
        .collect();
    std::fs::write(app.join("data"), &data).unwrap();

    let pkg = td.join("pkg.onelf");
    let o = run_onelf(
        &[
            "pack",
            app.to_str().unwrap(),
            "-o",
            pkg.to_str().unwrap(),
            "--command",
            "bin/run",
            "--payload",
            "stipple",
            "--no-compress",
        ],
        None,
    );
    assert!(
        o.status.success(),
        "pack: {}",
        String::from_utf8_lossy(&o.stderr)
    );

    // Stored, so the file's bytes sit in the image verbatim. The image's
    // block checksum or the manifest's slice hash catches the change;
    // neither may let the bytes through.
    let mut bytes = std::fs::read(&pkg).unwrap();
    let needle = &data[100_000..100_064];
    let at = bytes
        .windows(needle.len())
        .position(|w| w == needle)
        .expect("stored content must be present verbatim");
    bytes[at] ^= 0xff;
    let tampered = td.join("tampered.onelf");
    std::fs::write(&tampered, &bytes).unwrap();
    std::fs::set_permissions(
        &tampered,
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();

    let mut run = Command::new(&tampered);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", "fuse");
    isolate(&mut run, &td);
    let out = run_package(&mut run);
    assert!(out.stdout != data, "FUSE must not serve the tampered bytes");
    assert!(
        !out.status.success(),
        "a read that lost bytes must fail the app"
    );

    let _ = std::fs::remove_dir_all(&td);
}

#[test]
fn a_stipple_payload_refuses_what_it_cannot_honour() {
    let td = workdir("stipplerefuse");
    let app = td.join("app");
    stipple_app(&app);
    let pkg = td.join("s.onelf");
    for (extra, why) in [
        (&["--dict"][..], "a stipplefs payload uses none"),
        (&["--block-size", "96K"][..], "power-of-two block size"),
    ] {
        let mut args = vec![
            "pack",
            app.to_str().unwrap(),
            "-o",
            pkg.to_str().unwrap(),
            "--command",
            "bin/run",
            "--payload",
            "stipple",
        ];
        args.extend_from_slice(extra);
        let o = run_onelf(&args, None);
        assert!(!o.status.success(), "{extra:?} must be refused");
        assert!(
            String::from_utf8_lossy(&o.stderr).contains(why),
            "{extra:?}: {}",
            String::from_utf8_lossy(&o.stderr)
        );
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// A bare executable for `[input] binary` to import, plus the recipe
/// directory beside it. The recipe imports `../upstream/app` to
/// `bin/app`, the path the design example spells.
fn import_fixture(td: &Path, tag: &str) -> (PathBuf, PathBuf) {
    let upstream = td.join("upstream");
    std::fs::create_dir_all(&upstream).unwrap();
    let source = upstream.join("app");
    write(&source, "#!/bin/sh\necho IMPORT_OK\n");
    std::fs::set_permissions(
        &source,
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();
    let pkg = td.join(tag);
    std::fs::create_dir_all(&pkg).unwrap();
    write(
        &pkg.join("onelf.toml"),
        "[package]\nname = \"imported\"\ncommand = \"bin/app\"\n\n\
         [input]\nbinary = \"../upstream/app\"\n",
    );
    (pkg, source)
}

/// A minimal dynamically linked ELF for the end-to-end import build.
fn elf_source(td: &Path, marker: &str) -> PathBuf {
    let escaped = marker.replace('\\', "\\\\").replace('"', "\\\"");
    write(
        &td.join("app.c"),
        &format!("#include <stdio.h>\nint main(){{printf(\"{escaped}\\n\");return 0;}}\n"),
    );
    td.join("app.c")
}

/// Run the package a test built, isolated to the test's scratch.
fn run_import_package(pkg: &Path, td: &Path) -> std::process::Output {
    let mut c = Command::new(pkg);
    c.env_clear().env("PATH", "/usr/bin:/bin").env("HOME", td);
    isolate(&mut c, td);
    run_package(&mut c)
}

/// Scaffolding and building work from any working directory: the
/// imported binary resolves against the recipe's directory, not the
/// caller's, so `onelf build <recipe>` from elsewhere finds the same
/// upstream source and leaves it untouched.
#[test]
fn init_and_build_work_from_a_different_working_directory() {
    let td = workdir("import-init-cwd");
    let src = elf_source(&td, "ELF_IMPORT_CWD_OK");
    let upstream = td.join("upstream");
    std::fs::create_dir_all(&upstream).unwrap();
    let source = upstream.join("app");
    if !cc(&src, &source) {
        let _ = std::fs::remove_dir_all(&td);
        return;
    }
    let before = std::fs::read(&source).unwrap();
    let pkg = td.join("pkg");
    std::fs::create_dir_all(&pkg).unwrap();
    let out = run_onelf(&["init", "--binary", "../upstream/app"], Some(&pkg));
    assert!(
        out.status.success(),
        "init failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    let recipe = pkg.join("onelf.toml");
    let out = run_onelf(&["build", &format!("{}", recipe.display())], Some(&td));
    assert!(
        out.status.success(),
        "build from {} failed: {}",
        td.display(),
        String::from_utf8_lossy(&out.stderr)
    );
    assert_eq!(
        std::fs::read(&source).unwrap(),
        before,
        "the import must not modify the upstream file"
    );
    assert!(pkg.join("bin/app").is_file());
    let run = run_import_package(&pkg.join("app.onelf"), &td);
    let stdout = String::from_utf8_lossy(&run.stdout);
    assert!(
        run.status.success(),
        "{}",
        String::from_utf8_lossy(&run.stderr)
    );
    assert!(stdout.contains("ELF_IMPORT_CWD_OK"), "{stdout}");
    let _ = std::fs::remove_dir_all(&td);
}

/// A recipe that imports a bare binary builds the binary into an
/// executable without a pre-existing AppDir. The upstream file itself
/// is never modified, the package carries the command, and a rebuild
/// after the bundler's own ELF rewriting still refreshes instead of
/// reporting a conflict.
#[test]
fn a_bare_binary_import_builds_and_runs() {
    let td = workdir("import-e2e");
    let src = elf_source(&td, "ELF_IMPORT_OK");
    let upstream = td.join("upstream");
    std::fs::create_dir_all(&upstream).unwrap();
    let source = upstream.join("app");
    if !cc(&src, &source) {
        let _ = std::fs::remove_dir_all(&td);
        return;
    }
    let before = std::fs::read(&source).unwrap();
    let pkg = td.join("pkg");
    std::fs::create_dir_all(&pkg).unwrap();
    write(
        &pkg.join("onelf.toml"),
        "[package]\nname = \"imported\"\ncommand = \"bin/app\"\n\n\
         [input]\nbinary = \"../upstream/app\"\n",
    );
    let out = onelf_build(&pkg);
    assert!(
        out.status.success(),
        "bare-binary build failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert_eq!(
        std::fs::read(&source).unwrap(),
        before,
        "the import must not modify the upstream file"
    );
    assert!(pkg.join("bin/app").is_file());
    assert!(pkg.join(".onelf/generated").is_file());

    let run = run_import_package(&pkg.join("imported.onelf"), &td);
    let stdout = String::from_utf8_lossy(&run.stdout);
    assert!(
        run.status.success(),
        "{}",
        String::from_utf8_lossy(&run.stderr)
    );
    assert!(stdout.contains("ELF_IMPORT_OK"), "{stdout}");

    let out = onelf_build(&pkg);
    assert!(
        out.status.success(),
        "a rebuild after bundling rewrote the import must refresh: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    let run = run_import_package(&pkg.join("imported.onelf"), &td);
    let stdout = String::from_utf8_lossy(&run.stdout);
    assert!(
        run.status.success(),
        "{}",
        String::from_utf8_lossy(&run.stderr)
    );
    assert!(stdout.contains("ELF_IMPORT_OK"), "{stdout}");
    let _ = std::fs::remove_dir_all(&td);
}

/// The `DT_NEEDED` sonames `readelf -d` reports for one ELF.
fn needed_sonames(path: &Path) -> Vec<String> {
    let out = Command::new("readelf")
        .args(["-d", path.to_str().unwrap()])
        .output()
        .expect("spawn readelf");
    String::from_utf8_lossy(&out.stdout)
        .lines()
        .filter_map(|l| {
            l.split("Shared library: [")
                .nth(1)
                .map(|rest| rest.trim_end_matches(']').to_string())
        })
        .collect()
}

/// A source inside the recipe's directory is the author's file, not
/// AppDir content: the build leaves it byte for byte as it stands,
/// carrying no onelf-env NEED of its own, while the copy at the
/// command's path takes the bundling walk's rewriting. The packed
/// package runs, every rebuild leaves the source pristine again, and
/// once the tree has converged the rebuilds are byte-identical.
#[test]
fn an_in_tree_import_source_keeps_its_bytes() {
    let td = workdir("import-intree");
    let src = elf_source(&td, "ELF_IMPORT_INTREE_OK");
    let pkg = td.join("pkg");
    std::fs::create_dir_all(pkg.join("upstream")).unwrap();
    let source = pkg.join("upstream/app");
    if !cc(&src, &source) {
        let _ = std::fs::remove_dir_all(&td);
        return;
    }
    let before = std::fs::read(&source).unwrap();
    write(
        &pkg.join("onelf.toml"),
        "[package]\nname = \"imported\"\ncommand = \"bin/app\"\n\n\
         [input]\nbinary = \"upstream/app\"\n",
    );
    // A fixed epoch pins the fresh ledger's mtime, so two builds of the
    // same tree compare byte for byte.
    let build = || {
        let mut c = Command::new(onelf());
        c.arg("build")
            .current_dir(&pkg)
            .env("SOURCE_DATE_EPOCH", "1700000000");
        if let Some(pe) = patchelf() {
            c.env("ONELF_PATCHELF", pe);
        }
        c.output().expect("spawn onelf build")
    };
    let out = build();
    assert!(
        out.status.success(),
        "in-tree import build failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert_eq!(
        std::fs::read(&source).unwrap(),
        before,
        "the build must leave an in-tree source byte-identical"
    );
    let staged = std::fs::read(pkg.join("bin/app")).unwrap();
    assert_ne!(
        staged, before,
        "the command's copy is the walk's to rewrite, the source is not"
    );
    let package = pkg.join("imported.onelf");
    let run = run_import_package(&package, &td);
    let stdout = String::from_utf8_lossy(&run.stdout);
    assert!(
        run.status.success(),
        "{}",
        String::from_utf8_lossy(&run.stderr)
    );
    assert!(stdout.contains("ELF_IMPORT_INTREE_OK"), "{stdout}");

    if !have("readelf") || !have("patchelf") {
        skip(
            "patchelf",
            "readelf or patchelf is not available to check the added NEED",
        );
    }
    assert!(
        !needed_sonames(&source).contains(&"libonelf-env.so".to_string()),
        "the source must carry no added onelf-env NEED"
    );
    assert!(
        needed_sonames(&pkg.join("bin/app")).contains(&"libonelf-env.so".to_string()),
        "the command's copy must carry the onelf-env NEED"
    );

    let rebuild = || {
        let out = build();
        assert!(
            out.status.success(),
            "a rebuild over an untouched source must refresh: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        assert_eq!(
            std::fs::read(&source).unwrap(),
            before,
            "every rebuild must leave the source byte-identical"
        );
    };
    // The first rebuild converges the tree (the bundler resolves needs it
    // could not see on the first pass), so idempotence is the second
    // rebuild producing the same package bytes as the first.
    rebuild();
    let rebuilt = blake3::hash(&std::fs::read(&package).unwrap()).to_hex();
    rebuild();
    assert_eq!(
        blake3::hash(&std::fs::read(&package).unwrap()).to_hex(),
        rebuilt,
        "an idempotent rebuild must produce the same package bytes"
    );
    let run = run_import_package(&package, &td);
    let stdout = String::from_utf8_lossy(&run.stdout);
    assert!(
        run.status.success(),
        "{}",
        String::from_utf8_lossy(&run.stderr)
    );
    assert!(stdout.contains("ELF_IMPORT_INTREE_OK"), "{stdout}");
    let _ = std::fs::remove_dir_all(&td);
}

/// A source that is the package command itself, by the same path, by a
/// symlink inside the AppDir or by a hardlink, would be rewritten in
/// place by the import. The build refuses it before anything is written,
/// names the way out, and leaves the file as it was.
#[test]
fn an_import_whose_source_is_the_command_is_refused() {
    let td = workdir("import-self");
    let pkg = td.join("pkg");
    let app = pkg.join("bin/app");
    write(&app, "#!/bin/sh\necho SELF\n");
    std::os::unix::fs::symlink("app", pkg.join("bin/alias")).unwrap();
    std::fs::hard_link(&app, pkg.join("hard")).unwrap();
    for source in ["bin/app", "bin/alias", "hard"] {
        write(
            &pkg.join("onelf.toml"),
            &format!(
                "[package]\nname = \"imported\"\ncommand = \"bin/app\"\n\n\
                 [input]\nbinary = \"{source}\"\n"
            ),
        );
        let out = onelf_build(&pkg);
        let stderr = String::from_utf8_lossy(&out.stderr);
        assert!(!out.status.success(), "{source}: the build ran");
        assert!(
            stderr.contains("same file as the package command"),
            "{source}: {stderr}"
        );
        assert!(stderr.contains("drop [input]"), "{source}: {stderr}");
        assert_eq!(
            std::fs::read_to_string(&app).unwrap(),
            "#!/bin/sh\necho SELF\n",
            "{source}: the command was rewritten"
        );
        assert!(
            !pkg.join(".onelf").exists(),
            "{source}: the build wrote records"
        );
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// A build that fails after importing leaves the plain copy its record
/// attests, so the rebuild that follows a fix refreshes it, while an edit
/// made to the staged command after the failure is publisher content
/// that stops the next build instead of being silently overwritten.
#[test]
fn a_failed_import_build_refreshes_but_protects_later_edits() {
    let td = workdir("import-failed");
    let gone = td.join("gone");
    std::fs::create_dir_all(&gone).unwrap();
    write(&td.join("gone.c"), "int gone_value(void){return 7;}\n");
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libgone.so.1",
            td.join("gone.c").to_str().unwrap(),
        ],
        &gone.join("libgone.so.1"),
    ) {
        let _ = std::fs::remove_dir_all(&td);
        return;
    }
    write(
        &td.join("app.c"),
        "int gone_value(void);\nint main(void){return gone_value() == 7 ? 0 : 1;}\n",
    );
    let upstream = td.join("upstream");
    std::fs::create_dir_all(&upstream).unwrap();
    let source = upstream.join("app");
    assert!(cc_with(
        &[
            td.join("app.c").to_str().unwrap(),
            "-L",
            gone.to_str().unwrap(),
            "-l:libgone.so.1",
        ],
        &source
    ));
    let source_bytes = std::fs::read(&source).unwrap();
    let pkg = td.join("pkg");
    std::fs::create_dir_all(&pkg).unwrap();
    let recipe = |search: &str| {
        write(
            &pkg.join("onelf.toml"),
            &format!(
                "[package]\nname = \"imported\"\ncommand = \"bin/app\"\n\n\
                 [input]\nbinary = \"../upstream/app\"\n{search}"
            ),
        );
    };

    // Nothing supplies libgone, so the strict host scan stops the build.
    recipe("");
    let out = onelf_build(&pkg);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "the build must fail: {stderr}");
    assert!(stderr.contains("libgone.so.1"), "{stderr}");
    assert_eq!(
        std::fs::read(pkg.join("bin/app")).unwrap(),
        source_bytes,
        "the failed build left a copy its record does not attest"
    );

    // The fix: the library is reachable. The rebuild refreshes.
    let fixed = format!("\n[bundle]\nsearch-paths = [\"{}\"]\n", gone.display());
    recipe(&fixed);
    let out = onelf_build(&pkg);
    assert!(
        out.status.success(),
        "the rebuild after a failure must refresh the import: {}",
        String::from_utf8_lossy(&out.stderr)
    );

    // A failure, then an edit: the next build stops on the edit. The
    // bundled copy goes too, so nothing in the tree supplies libgone.
    let _ = std::fs::remove_dir_all(pkg.join("lib"));
    recipe("");
    assert!(!onelf_build(&pkg).status.success());
    write(&pkg.join("bin/app"), "#!/bin/sh\necho EDITED\n");
    recipe(&fixed);
    let out = onelf_build(&pkg);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "the edit was overwritten");
    assert!(stderr.contains("did not import"), "{stderr}");
    assert_eq!(
        std::fs::read_to_string(pkg.join("bin/app")).unwrap(),
        "#!/bin/sh\necho EDITED\n"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// A rebuild refreshes the staged copy: a vanished one is restored, and
/// an untouched one is rewritten in place from the same source.
#[test]
fn an_import_refreshes_its_staged_copy() {
    let td = workdir("import-refresh");
    let (pkg, source) = import_fixture(&td, "pkg");
    let staged = pkg.join("bin/app");
    let out = onelf_build(&pkg);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(staged.is_file());
    let out = onelf_build(&pkg);
    assert!(
        out.status.success(),
        "an unchanged rebuild must refresh, not conflict: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    std::fs::remove_file(&staged).unwrap();
    let out = onelf_build(&pkg);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert_eq!(
        std::fs::read(&staged).unwrap(),
        std::fs::read(&source).unwrap()
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// A source that changed upstream refreshes a staged copy the record
/// still attests, and the new bytes are what the next package carries.
#[test]
fn a_changed_source_refreshes_a_recorded_import() {
    let td = workdir("import-changed");
    let (pkg, source) = import_fixture(&td, "pkg");
    let out = onelf_build(&pkg);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    write(&source, "#!/bin/sh\necho IMPORT_V2\n");
    std::fs::set_permissions(
        &source,
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();
    let out = onelf_build(&pkg);
    assert!(
        out.status.success(),
        "a changed upstream must refresh the recorded copy: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert_eq!(
        std::fs::read_to_string(pkg.join("bin/app")).unwrap(),
        "#!/bin/sh\necho IMPORT_V2\n"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// Staged bytes nobody recorded are publisher content: the build keeps
/// them and stops instead of packing an edit or overwriting it.
#[test]
fn an_edited_import_conflicts_instead_of_building() {
    let td = workdir("import-edited");
    let (pkg, _source) = import_fixture(&td, "pkg");
    let staged = pkg.join("bin/app");
    let out = onelf_build(&pkg);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    write(&staged, "#!/bin/sh\necho EDITED\n");
    let out = onelf_build(&pkg);
    assert!(
        !out.status.success(),
        "an edited import must stop the build"
    );
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(stderr.contains("did not import"), "{stderr}");
    assert_eq!(
        std::fs::read_to_string(&staged).unwrap(),
        "#!/bin/sh\necho EDITED\n",
        "the edit must survive the failed build"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// An import reads through a source alias and a hardlink without
/// changing either: the link keeps its target and the hardlink keeps
/// its inode, so the source binary is never the build's to rewrite.
#[test]
fn an_import_follows_a_source_alias_or_hardlink() {
    let td = workdir("import-alias");
    let (pkg, source) = import_fixture(&td, "pkg");
    let alias = td.join("upstream/link");
    std::os::unix::fs::symlink("app", &alias).unwrap();
    let hard = td.join("upstream/hard");
    std::fs::hard_link(&source, &hard).unwrap();
    let inode = |p: &Path| {
        use std::os::unix::fs::MetadataExt;
        let m = std::fs::metadata(p).unwrap();
        (m.dev(), m.ino())
    };
    let hard_before = inode(&hard);

    for (name, rel) in [("alias", "../upstream/link"), ("hard", "../upstream/hard")] {
        write(
            &pkg.join("onelf.toml"),
            &format!(
                "[package]\nname = \"imported\"\ncommand = \"bin/app\"\n\n\
                 [input]\nbinary = \"{rel}\"\n"
            ),
        );
        let out = onelf_build(&pkg);
        assert!(
            out.status.success(),
            "{name}: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        assert_eq!(
            std::fs::read(pkg.join("bin/app")).unwrap(),
            std::fs::read(&source).unwrap(),
            "{name}: the staged copy holds the source bytes"
        );
        assert!(
            std::fs::symlink_metadata(pkg.join("bin/app"))
                .unwrap()
                .file_type()
                .is_file(),
            "{name}: the staged copy is its own file, not a link"
        );
    }
    assert_eq!(
        std::fs::read_link(&alias).unwrap().as_os_str(),
        "app",
        "the alias must keep pointing at the source"
    );
    assert_eq!(inode(&hard), hard_before, "the hardlink keeps its inode");
    assert_eq!(
        std::fs::read(&hard).unwrap(),
        std::fs::read(&source).unwrap()
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// A symlink sitting on the import's destination path stops the build
/// before anything is written, and the link's target is untouched.
#[test]
fn an_import_refuses_to_write_through_a_destination_symlink() {
    let td = workdir("import-attack");
    let (pkg, _source) = import_fixture(&td, "pkg");
    let victim = td.join("victim");
    write(&victim, "do not touch\n");
    std::fs::create_dir_all(pkg.join("bin")).unwrap();
    std::os::unix::fs::symlink(&victim, pkg.join("bin/app")).unwrap();
    let out = onelf_build(&pkg);
    assert!(
        !out.status.success(),
        "an import must not write through a destination symlink"
    );
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(stderr.contains("symbolic link"), "{stderr}");
    assert_eq!(
        std::fs::read_to_string(&victim).unwrap(),
        "do not touch\n",
        "the linked file must be untouched"
    );
    assert!(
        std::fs::symlink_metadata(pkg.join("bin/app"))
            .unwrap()
            .file_type()
            .is_symlink()
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// Two authoritative sources are refused, naming both fields, before
/// either source is materialized.
