/// A shared app source for the lifetime tests: one launch's foreground
/// daemonizes, drops every descriptor it inherited including the standard
/// streams, waits, then reads a package file through the tree it still
/// runs from and writes what it saw. It prints its tree first, so the
/// test can watch that tree. After the read it waits for the gate file,
/// so the test decides when the launch's descendants end; then it marks
/// that and exits.
fn daemon_reader(gate: &Path, result: &Path, done: &Path) -> String {
    format!(
        "#include <unistd.h>\n#include <stdio.h>\n#include <stdlib.h>\n\
         int main(void){{\n\
         \x20 printf(\"dir=%s\\n\", getenv(\"ONELF_DIR\") ? getenv(\"ONELF_DIR\") : \"unset\");\n\
         \x20 fflush(stdout);\n\
         \x20 if (fork() != 0) {{ _exit(0); }}\n\
         \x20 setsid();\n\
         \x20 for (int fd = 0; fd < 256; fd++) close(fd);\n\
         \x20 sleep(1);\n\
         \x20 const char *d = getenv(\"ONELF_DIR\");\n\
         \x20 char p[512];\n\
         \x20 snprintf(p, sizeof p, \"%s/data.txt\", d ? d : \"/nonexistent\");\n\
         \x20 FILE *in = fopen(p, \"r\");\n\
         \x20 FILE *out = fopen(\"{}\", \"w\");\n\
         \x20 if (out) {{ fprintf(out, in ? \"READ-OK\" : \"READ-FAILED\"); fclose(out); }}\n\
         \x20 for (int i = 0; i < 600; i++) {{\n\
         \x20  FILE *g = fopen(\"{}\", \"r\");\n\
         \x20  if (g) {{ fclose(g); break; }}\n\
         \x20  usleep(100000);\n\
         \x20 }}\n\
         \x20 FILE *bye = fopen(\"{}\", \"w\");\n\
         \x20 if (bye) {{ fputs(\"gone\", bye); fclose(bye); }}\n\
         \x20 return 0;\n}}\n",
        result.display(),
        gate.display(),
        done.display()
    )
}

/// Wait until `probe` succeeds, for a bounded time.
fn until(mut probe: impl FnMut() -> bool) -> bool {
    for _ in 0..200 {
        if probe() {
            return true;
        }
        std::thread::sleep(std::time::Duration::from_millis(50));
    }
    false
}

/// Pack the daemon-reader app and return its package, or an empty path
/// when no compiler is available.
fn pack_daemon_reader(td: &Path, name: &str, gate: &Path, result: &Path, done: &Path) -> PathBuf {
    let app = td.join(name);
    let src = td.join(format!("{name}.c"));
    let bin = app.join("bin/run");
    std::fs::create_dir_all(bin.parent().unwrap()).unwrap();
    write(&app.join("data.txt"), "payload\n");
    write(&src, &daemon_reader(gate, result, done));
    if !cc(&src, &bin) {
        return PathBuf::new();
    }
    let pkg = td.join(format!("{name}.onelf"));
    let o = Command::new(onelf())
        .args(["pack", app.to_str().unwrap(), "-o", pkg.to_str().unwrap()])
        .args(["--command", "bin/run", "--mtime", "0", "--name", name])
        .output()
        .expect("spawn onelf pack");
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    pkg
}

/// Start the daemon-reader package in `mode` and return the child with its
/// first output line, which names the tree the launch runs from.
fn start_daemon_reader(pkg: &Path, td: &Path, mode: &str) -> (std::process::Child, PathBuf) {
    let mut run = Command::new(pkg);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", mode)
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    isolate(&mut run, td);
    let mut child = spawn_package(&mut run);
    use std::io::BufRead;
    let mut line = String::new();
    std::io::BufReader::new(child.stdout.as_mut().unwrap())
        .read_line(&mut line)
        .unwrap();
    let tree = PathBuf::from(line.trim().strip_prefix("dir=").unwrap_or(""));
    (child, tree)
}

/// A runtime-directory launch whose app daemonizes keeps its own view
/// under its own guardian: the tree stays past the launcher, past the app
/// dropping every descriptor it inherited, and goes when the launch's
/// last process is gone, not before and not after.
#[test]
fn a_rundir_descendant_keeps_its_view_past_the_launcher() {
    let td = workdir("rundirdaemon");
    let gate = td.join("gate");
    let result = td.join("result");
    let done = td.join("done");
    let pkg = pack_daemon_reader(&td, "rd", &gate, &result, &done);
    if !pkg.as_os_str().is_empty() {
        let (mut child, tree) = start_daemon_reader(&pkg, &td, "rundir");
        let status = child.wait().unwrap();
        assert!(status.success(), "the launcher failed: {status}");
        assert!(
            tree.starts_with(td.join("xdg-run")),
            "the view lives in the private runtime directory: {}",
            tree.display()
        );
        assert!(
            tree.is_dir(),
            "the view stays past the launcher: {}",
            tree.display()
        );

        // The daemon reads its own view with nothing inherited, which no
        // unclaimed tree would survive.
        assert!(
            until(|| std::fs::read_to_string(&result).is_ok_and(|s| s == "READ-OK")),
            "the daemon could not read its view after dropping everything"
        );
        assert!(tree.is_dir(), "the view stays while its launch lives");

        // The launch's last process goes; the guardian lets the claim go
        // and takes the view with it.
        std::fs::write(&gate, "").unwrap();
        assert!(until(|| done.is_file()), "the daemon never finished");
        assert!(
            until(|| std::fs::symlink_metadata(&tree).is_err()),
            "the view is taken down after its launch's last process"
        );
        assert_eq!(
            std::fs::read_dir(td.join("xdg-cache")).unwrap().count(),
            0,
            "the persistent cache is untouched"
        );
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// The same contract in the tmpfs mode: the launcher returns when the
/// foreground is gone, the daemonized descendant still reads its view,
/// the launch's guardian holds the mountpoint's claim for as long as the
/// launch lives, another launch's sweep leaves that claim alone, and it
/// is released once the launch's last process is gone.
#[test]
fn a_tmpfs_descendant_keeps_its_view_past_the_launcher() {
    if !tmpfs_available() {
        return; // documented soft-skip
    }
    let td = workdir("tmpfsdaemon");
    let gate = td.join("gate");
    let result = td.join("result");
    let done = td.join("done");
    let pkg = pack_daemon_reader(&td, "tmpd", &gate, &result, &done);
    if !pkg.as_os_str().is_empty() {
        let (mut child, tree) = start_daemon_reader(&pkg, &td, "tmpfs");
        let status = child.wait().unwrap();
        assert!(status.success(), "the launcher failed: {status}");
        assert!(
            tree.starts_with(td.join("xdg-run")),
            "the mountpoint lives in the private runtime directory: {}",
            tree.display()
        );

        // The daemon reads the tmpfs view with nothing inherited, so the
        // namespace outlived the launcher.
        assert!(
            until(|| std::fs::read_to_string(&result).is_ok_and(|s| s == "READ-OK")),
            "the daemon could not read its view after dropping everything"
        );
        use rustix::fs::FlockOperation;
        let claim = td.join("xdg-run").join(format!(
            ".{}.lock",
            tree.file_name().unwrap().to_string_lossy()
        ));
        let claim_taken = || {
            std::fs::File::open(&claim)
                .map(|f| rustix::fs::flock(&f, FlockOperation::NonBlockingLockExclusive).is_err())
                .unwrap_or(false)
        };
        assert!(
            claim_taken(),
            "the launch's guardian holds the mountpoint's claim while the \
             launch lives"
        );

        // A second launch of the package runs meanwhile, and the first
        // launch's claim is not something its sweep may touch. The path is
        // per package; the mount on it is per launch, made inside each
        // launch's own namespace.
        let second_ok = {
            let mut run = Command::new(&pkg);
            run.env_clear()
                .env("PATH", "/usr/bin:/bin")
                .env("HOME", td.to_str().unwrap())
                .env("ONELF_MODE", "tmpfs")
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::piped());
            isolate(&mut run, &td);
            run_package(&mut run).status.success()
        };
        assert!(second_ok, "the second launch runs");
        assert!(
            claim_taken(),
            "another launch's sweep leaves a claimed mountpoint alone"
        );

        // The first launch's descendants end, its guardian lets the claim
        // go, and nothing of the launch holds the mountpoint any more.
        std::fs::write(&gate, "").unwrap();
        assert!(until(|| done.is_file()), "the daemon never finished");
        assert!(
            until(|| {
                std::fs::File::open(&claim)
                    .map(|f| {
                        rustix::fs::flock(&f, FlockOperation::NonBlockingLockExclusive).is_ok()
                    })
                    .unwrap_or(false)
            }),
            "the drained launch's claim is released"
        );
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// A cache launch publishes an execution view of its own identity beside
/// the shared base extraction, runs from it under its guardian, and the
/// view's lease outlives the foreground process: another launch's
/// collection must leave a leased view alone and may reclaim it once its
/// launch is truly gone.
#[test]
fn a_cache_view_is_leased_by_its_guardian_and_reclaimed_when_idle() {
    let td = workdir("cacheview");
    let gate = td.join("gate");
    let result = td.join("result");
    let done = td.join("done");
    let holder = pack_daemon_reader(&td, "holder", &gate, &result, &done);
    if !holder.as_os_str().is_empty() {
        let other = pack_script(&td, "other", "#!/bin/sh\necho dir=$ONELF_DIR\n");
        let views = td.join("xdg-cache/onelf/views");

        // The holder's launch publishes its view and daemonizes; the
        // launcher returns while the view's lease stays with the launch's
        // guardian.
        let (mut child, view) = start_daemon_reader(&holder, &td, "cache");
        let status = child.wait().unwrap();
        assert!(status.success(), "the launcher failed: {status}");
        assert!(
            view.starts_with(&views),
            "the launch runs from its published view: {}",
            view.display()
        );
        assert!(
            view.is_dir(),
            "the view stays past the launcher: {}",
            view.display()
        );

        // Another launch of another package collects what is idle, and the
        // holder's view is not idle: its guardian still holds its lease.
        let mut second = Command::new(&other);
        second
            .env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("ONELF_MODE", "cache")
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        isolate(&mut second, &td);
        let out = run_package(&mut second);
        let stdout = String::from_utf8_lossy(&out.stdout);
        assert!(
            out.status.success(),
            "{}",
            String::from_utf8_lossy(&out.stderr)
        );
        let second_view = PathBuf::from(
            stdout
                .trim()
                .strip_prefix("dir=")
                .unwrap_or_default()
                .to_owned(),
        );
        assert_ne!(view, second_view, "two identities get two views");
        assert!(
            view.is_dir(),
            "a leased view survives another launch's collection"
        );

        // The holder's last process goes, its guardian lets the lease go,
        // and once the view has gone unused past the age limit the next
        // launch's collection reclaims it.
        std::fs::write(&gate, "").unwrap();
        assert!(until(|| done.is_file()), "the daemon never finished");
        let lease = views.join(format!(
            "{}.lease",
            view.file_name().unwrap().to_string_lossy()
        ));
        assert!(
            until(|| {
                std::fs::File::open(&lease).is_ok_and(|f| {
                    rustix::fs::flock(&f, rustix::fs::FlockOperation::NonBlockingLockExclusive)
                        .is_ok()
                })
            }),
            "the guardian never let the lease go"
        );
        std::fs::File::open(&lease)
            .unwrap()
            .set_modified(std::time::SystemTime::now() - std::time::Duration::from_secs(31 * 86400))
            .unwrap();
        let mut third = Command::new(&other);
        third
            .env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("ONELF_MODE", "cache")
            .stderr(std::process::Stdio::piped());
        isolate(&mut third, &td);
        let out = run_package(&mut third);
        assert!(
            out.status.success(),
            "{}",
            String::from_utf8_lossy(&out.stderr)
        );
        let mut left: Vec<String> = std::fs::read_dir(&views)
            .unwrap()
            .flatten()
            .filter(|e| e.file_type().map(|t| t.is_dir()).unwrap_or(false))
            .map(|e| e.file_name().into_string().unwrap_or_default())
            .collect();
        left.sort();
        assert_eq!(
            left,
            vec![
                second_view
                    .file_name()
                    .unwrap()
                    .to_string_lossy()
                    .into_owned()
            ],
            "the idle view is reclaimed, the live one stays: {left:?}"
        );
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// When the mode the launch prefers is unavailable, the launch falls back
/// and the fallback keeps every bit of the isolation it must: its own
/// tree in the private runtime directory, no shared mount record, and
/// nothing in the persistent cache. Two fallback launches of the same
/// package run side by side without running from one another's state, and
/// neither leaves anything behind.
#[test]
fn a_fallback_launch_keeps_its_isolation() {
    let td = workdir("fallback");
    let pkg = pack_script(
        &td,
        "fb",
        "#!/bin/sh\necho mode=$ONELF_ACTIVE_MODE\necho dir=$ONELF_DIR\n",
    );

    // FUSE cannot be established here: the helper is named away and the
    // namespace path is turned off, so the launch falls through to the
    // modes that isolate in other ways.
    let degraded = |cmd: &mut Command| {
        cmd.env("ONELF_FUSE_NO_NAMESPACE", "1")
            .env("FUSERMOUNT_PROG", "/nonexistent/fusermount3");
    };

    let mut run = Command::new(&pkg);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    isolate(&mut run, &td);
    degraded(&mut run);
    let out = run_package(&mut run);
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        out.status.success(),
        "the fallback launch runs:\n{stdout}{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let mode = stdout
        .lines()
        .find_map(|l| l.strip_prefix("mode="))
        .expect("the app reports its mode");
    assert!(
        matches!(mode, "tmpfs" | "rundir"),
        "the launch fell back to an isolating mode, got {mode}:\n{stdout}"
    );
    let tree = PathBuf::from(
        stdout
            .lines()
            .find_map(|l| l.strip_prefix("dir="))
            .expect("the app reports its directory"),
    );
    assert!(
        tree.starts_with(td.join("xdg-run")),
        "the fallback launch runs from its own tree in the private \
         runtime directory: {}",
        tree.display()
    );
    assert_eq!(
        std::fs::read_dir(td.join("xdg-cache")).unwrap().count(),
        0,
        "a fallback launch never writes the persistent cache"
    );
    assert!(
        std::fs::read_dir(td.join("xdg-run"))
            .unwrap()
            .flatten()
            .all(|e| !e.file_name().to_string_lossy().ends_with(".share")),
        "a fallback launch never finds or leaves a shared mount record"
    );

    // The launch's hold on its tree goes once it is done: a rundir tree is
    // taken down by its own guardian, and a tmpfs mountpoint's claim is
    // released, so nothing runs from either any more.
    let mut again = Command::new(&pkg);
    again
        .env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .stderr(std::process::Stdio::piped());
    isolate(&mut again, &td);
    degraded(&mut again);
    let out = run_package(&mut again);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    if mode == "rundir" {
        assert!(
            until(|| std::fs::symlink_metadata(&tree).is_err()),
            "the fallback launch's tree is taken down after it exits"
        );
    } else {
        use rustix::fs::FlockOperation;
        let claim = td.join("xdg-run").join(format!(
            ".{}.lock",
            tree.file_name().unwrap().to_string_lossy()
        ));
        assert!(
            until(|| {
                std::fs::File::open(&claim)
                    .map(|f| {
                        rustix::fs::flock(&f, FlockOperation::NonBlockingLockExclusive).is_ok()
                    })
                    .unwrap_or(false)
            }),
            "the drained tmpfs launch's claim on its mountpoint is released"
        );
    }

    // Two fallback launches side by side: neither runs from the other's
    // state. A rundir fallback names a tree of its own; a tmpfs fallback
    // mounts its own filesystem at the per-package path inside its own
    // namespace, which is where the isolation lives.
    let launch = || {
        let mut cmd = Command::new(&pkg);
        cmd.env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .stderr(std::process::Stdio::null());
        isolate(&mut cmd, &td);
        degraded(&mut cmd);
        let out = run_package(&mut cmd);
        let stdout = String::from_utf8_lossy(&out.stdout).into_owned();
        assert!(out.status.success(), "{stdout}");
        let mode = stdout
            .lines()
            .find_map(|l| l.strip_prefix("mode="))
            .unwrap_or_default()
            .to_owned();
        let tree = PathBuf::from(
            stdout
                .lines()
                .find_map(|l| l.strip_prefix("dir="))
                .unwrap_or_default()
                .to_owned(),
        );
        (mode, tree)
    };
    let (first_mode, first_tree) = launch();
    let (second_mode, second_tree) = launch();
    assert_eq!(
        (
            matches!(first_mode.as_str(), "tmpfs" | "rundir"),
            matches!(second_mode.as_str(), "tmpfs" | "rundir"),
            first_mode == second_mode
        ),
        (true, true, true),
        "both launches fall back the same way: {first_mode} and {second_mode}"
    );
    assert!(first_tree.starts_with(td.join("xdg-run")));
    assert!(second_tree.starts_with(td.join("xdg-run")));
    if first_mode == "rundir" {
        assert_ne!(
            first_tree, second_tree,
            "two rundir fallbacks never run from one tree"
        );
    }
    if first_mode == "rundir" {
        assert!(
            until(|| std::fs::symlink_metadata(&first_tree).is_err())
                && until(|| std::fs::symlink_metadata(&second_tree).is_err()),
            "both fallback trees go when their launches do"
        );
    } else {
        use rustix::fs::FlockOperation;
        let claim = td.join("xdg-run").join(format!(
            ".{}.lock",
            first_tree.file_name().unwrap().to_string_lossy()
        ));
        assert!(
            until(|| {
                std::fs::File::open(&claim)
                    .map(|f| {
                        rustix::fs::flock(&f, FlockOperation::NonBlockingLockExclusive).is_ok()
                    })
                    .unwrap_or(false)
            }),
            "the launches' hold on their mountpoint is released once they are done"
        );
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// The late-loader fixture's C source. One app covers every scenario
/// through its environment: it reports the tree it runs from on stdout,
/// optionally double-forks into a helper that drops every inherited
/// descriptor (`$DAEMON`; `$READY` marks the moment and names the
/// ancestor that adopted the helper), waits for `$GATE`,
/// loads every soname named in `$PLUGIN`, defaulting to its own bundled
/// plugin and a host driver by name, and writes one
/// `late=<soname>:<value>` line per load to `$RESULT`, then waits for
/// `$HOLD` and marks `$DONE` on its way out. The bundled plugin answers
/// 42 and a fixture host driver answers its own value, so the report
/// names which copy each load reached. The soname defaults stay in the
/// binary, which is how a driver-reaching package tells the packer it
/// needs the launch resolver.
const LATE_LOADER_SRC: &str = r#"#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/syscall.h>
#include <unistd.h>

static void wait_for_file(const char *path) {
    if (!path || !*path) {
        return;
    }
    for (int i = 0; i < 600; i++) {
        FILE *g = fopen(path, "r");
        if (g) {
            fclose(g);
            return;
        }
        usleep(50000);
    }
}

int main(void) {
    const char *daemon = getenv("DAEMON");
    const char *ready = getenv("READY");
    const char *gate = getenv("GATE");
    const char *plugin = getenv("PLUGIN");
    const char *result = getenv("RESULT");
    const char *hold = getenv("HOLD");
    const char *done = getenv("DONE");
    const char *dir = getenv("ONELF_DIR");
    if (!plugin || !*plugin) {
        plugin = "libplugin.so.1:libGL.so.1";
    }
    printf("dir=%s\n", dir ? dir : "unset");
    fflush(stdout);
    if (daemon && *daemon) {
        pid_t foreground = getpid();
        if (fork() != 0) {
            _exit(0);
        }
        setsid();
#ifdef SYS_close_range
        if (syscall(SYS_close_range, 0u, 0xffffffffu, 0u) != 0)
#endif
        {
            for (int fd = 0; fd < 1024; fd++) {
                close(fd);
            }
        }
        for (int i = 0; i < 200 && getppid() == foreground; i++) {
            usleep(10000);
        }
        if (ready && *ready) {
            FILE *r = fopen(ready, "w");
            if (r) {
                fprintf(r, "closed %d", (int)getppid());
                fclose(r);
            }
        }
    }
    wait_for_file(gate);
    if (result && *result) {
        FILE *out = fopen(result, "w");
        if (out) {
            const char *rest = plugin ? plugin : "";
            while (*rest) {
                const char *end = rest;
                while (*end && *end != ':') {
                    end++;
                }
                char name[256];
                size_t len = (size_t)(end - rest);
                if (len >= sizeof(name)) {
                    len = sizeof(name) - 1;
                }
                memcpy(name, rest, len);
                name[len] = 0;
                void *h = dlopen(name, RTLD_NOW);
                if (!h) {
                    fprintf(out, "late=%s:failed\n", name);
                } else {
                    int (*value)(void) = (int (*)(void))dlsym(h, "plugin_value");
                    if (value) {
                        fprintf(out, "late=%s:%d\n", name, value());
                    } else {
                        fprintf(out, "late=%s:nosym\n", name);
                    }
                }
                rest = *end ? end + 1 : end;
            }
            fclose(out);
        }
    }
    wait_for_file(hold);
    if (done && *done) {
        FILE *b = fopen(done, "w");
        if (b) {
            fputs("gone", b);
            fclose(b);
        }
    }
    return 0;
}
"#;

/// Pack the late-loader fixture: the compiled app as `bin/run` beside
/// the bundled plugin `lib/libplugin.so.1`, and nothing else, so the
/// package carries no sets of any kind and every late load resolves the
/// ordinary way. Returns an empty path when no compiler is available,
/// the fixture's only soft-skip condition.
fn pack_late_loader(td: &Path, name: &str) -> PathBuf {
    let app = td.join(name);
    let src = td.join(format!("{name}.c"));
    let bin = app.join("bin/run");
    std::fs::create_dir_all(bin.parent().unwrap()).unwrap();
    write(&src, LATE_LOADER_SRC);
    if !cc_with(&[src.to_str().unwrap(), "-ldl"], &bin) {
        return PathBuf::new();
    }
    let plugin_src = td.join(format!("{name}-plugin.c"));
    write(&plugin_src, "int plugin_value(void){return 42;}\n");
    std::fs::create_dir_all(app.join("lib")).unwrap();
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libplugin.so.1",
            plugin_src.to_str().unwrap(),
        ],
        &app.join("lib/libplugin.so.1"),
    ) {
        return PathBuf::new();
    }
    let pkg = td.join(format!("{name}.onelf"));
    let o = Command::new(onelf())
        .args(["pack", app.to_str().unwrap(), "-o", pkg.to_str().unwrap()])
        .args(["--command", "bin/run", "--mtime", "0", "--name", name])
        .output()
        .expect("spawn onelf pack");
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    pkg
}

/// Start the late-loader package in `mode` with `envs` laid on, and
/// return the child with its first output line, which names the tree or
/// view the launch runs from.
fn start_late_loader(
    pkg: &Path,
    td: &Path,
    mode: &str,
    envs: &[(&str, &str)],
) -> (std::process::Child, PathBuf) {
    let mut run = Command::new(pkg);
    run.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_MODE", mode)
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    isolate(&mut run, td);
    for (name, value) in envs {
        run.env(name, value);
    }
    let mut child = spawn_package(&mut run);
    use std::io::BufRead;
    let mut line = String::new();
    std::io::BufReader::new(child.stdout.as_mut().unwrap())
        .read_line(&mut line)
        .unwrap();
    let tree = PathBuf::from(line.trim().strip_prefix("dir=").unwrap_or(""));
    (child, tree)
}

/// Compile a host driver pair into `dir`: `libGL.so.1` whose
/// `plugin_value` calls through `libfixture.so.1`. A package carrying
/// neither library reaches them only through the resolver's farm, so a
/// late load of `libGL.so.1` proves both the farm link and its
/// dependency resolved from the same host state. Returns false when no
/// compiler is available.
fn host_driver_pair(td: &Path, tag: &str, dir: &Path, value: i32) -> bool {
    std::fs::create_dir_all(dir).unwrap();
    let fixture_src = td.join(format!("{tag}-fixture.c"));
    write(
        &fixture_src,
        &format!("int fix_extra(void){{return {value};}}\n"),
    );
    let fixture = dir.join("libfixture.so.1");
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libfixture.so.1",
            fixture_src.to_str().unwrap(),
        ],
        &fixture,
    ) {
        return false;
    }
    let gl_src = td.join(format!("{tag}-gl.c"));
    write(
        &gl_src,
        "extern int fix_extra(void);\nint plugin_value(void){return fix_extra();}\n",
    );
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libGL.so.1",
            gl_src.to_str().unwrap(),
            &format!("-L{}", dir.display()),
            "-l:libfixture.so.1",
        ],
        &dir.join("libGL.so.1"),
    ));
    true
}

/// The resolver's per-selection decision records under the private
/// runtime directory, one `sel-<key>/decision` per selection identity.
fn selection_records_of(td: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    for store in std::fs::read_dir(td.join("xdg-run"))
        .into_iter()
        .flatten()
        .flatten()
        .filter(|e| e.file_name().to_string_lossy().starts_with("resolve-"))
    {
        for entry in std::fs::read_dir(store.path())
            .into_iter()
            .flatten()
            .flatten()
            .filter(|e| e.file_name().to_string_lossy().starts_with("sel-"))
        {
            out.push(entry.path().join("decision"));
        }
    }
    out.sort();
    out
}

/// Resolver decisions belong to the selection that made them. A toolkit
/// entrypoint and a `sets = []` entrypoint of one package on one host
/// keep separate records, so the empty selection never reuses the
/// toolkit's decision, while an entrypoint naming the same sets in
/// another order reuses the toolkit's record untouched.
#[test]
fn each_selection_keeps_its_own_resolver_decision() {
    let td = workdir("resolver-selection");
    for (tag, soname) in [
        ("alpha", "libalpha.so.7fixture"),
        ("beta", "libbeta.so.7fixture"),
    ] {
        if set_library(&td, tag, soname, "int set_value(void){return 1;}\n").is_none() {
            return;
        }
    }
    let (alpha, alpha_pkg) = pack_set(&td, "alpha", "alpha");
    let (beta, beta_pkg) = pack_set(&td, "beta", "beta");

    // A host whose loader cache names one driver, so every launch has a
    // decision to record.
    let host = td.join("host");
    std::fs::create_dir_all(&host).unwrap();
    write(&td.join("gl.c"), "int gl_value(void){return 1;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libGL.so.1",
            td.join("gl.c").to_str().unwrap(),
        ],
        &host.join("libGL.so.1")
    ));
    let cache = td.join("ld.so.cache");
    std::fs::write(&cache, ld_so_cache(&[&host.join("libGL.so.1")])).unwrap();

    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("lib")).unwrap();
    write(&td.join("plain.c"), "int plain_value(void){return 1;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libplain.so.1",
            td.join("plain.c").to_str().unwrap(),
        ],
        &dir.join("lib/libplain.so.1")
    ));
    for name in ["cli", "gui", "gui2"] {
        let script = dir.join("bin").join(name);
        write(&script, &format!("#!/bin/sh\necho ran={name}\n"));
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&script, std::fs::Permissions::from_mode(0o755)).unwrap();
    }
    write(
        &dir.join("onelf.toml"),
        &format!(
            "[package]\ncommand = \"bin/cli\"\nmtime = 0\n\n[bundle]\nskip = true\n\n\
             [sysroot.sets.alpha]\npackages = [\"alpha\"]\nurl = \"file://{}\"\nblake3 = \"{alpha}\"\n\n\
             [sysroot.sets.beta]\npackages = [\"beta\"]\nurl = \"file://{}\"\nblake3 = \"{beta}\"\n\n\
             [[entrypoint]]\nname = \"cli\"\npath = \"bin/cli\"\nsets = []\ndefault = true\n\n\
             [[entrypoint]]\nname = \"gui\"\npath = \"bin/gui\"\nsets = [\"alpha\", \"beta\"]\n\n\
             [[entrypoint]]\nname = \"gui2\"\npath = \"bin/gui2\"\nsets = [\"beta\", \"alpha\"]\n",
            alpha_pkg.display(),
            beta_pkg.display()
        ),
    );
    let pkg = td.join("app.onelf");
    let out = Command::new(onelf())
        .args([
            "build",
            dir.to_str().unwrap(),
            "--output",
            pkg.to_str().unwrap(),
        ])
        .output()
        .expect("spawn onelf build");
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );

    let launch = |entrypoint: &str| {
        let mut cmd = Command::new(&pkg);
        cmd.env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("ONELF_ENTRYPOINT", entrypoint)
            .env("ONELF_MODE", "rundir")
            .env("ONELF_SET_MODE", "extract")
            .env("ONELF_LD_CACHE", &cache)
            .env("ONELF_PLATFORM_STORE", td.join("store"));
        isolate(&mut cmd, &td);
        let out = run_package(&mut cmd);
        let report = format!(
            "{}{}",
            String::from_utf8_lossy(&out.stdout),
            String::from_utf8_lossy(&out.stderr)
        );
        assert!(out.status.success(), "{entrypoint}: {report}");
        assert!(report.contains(&format!("ran={entrypoint}")), "{report}");
    };

    launch("gui");
    let toolkit = selection_records_of(&td);
    assert_eq!(toolkit.len(), 1, "{toolkit:?}");
    let record = std::fs::read_to_string(&toolkit[0]).unwrap();
    assert!(
        record.contains(&alpha) && record.contains(&beta),
        "the toolkit record names its pins:\n{record}"
    );

    launch("cli");
    let both = selection_records_of(&td);
    assert_eq!(
        both.len(),
        2,
        "the empty selection reused the toolkit's: {both:?}"
    );
    let empty = both.iter().find(|p| **p != toolkit[0]).unwrap();
    let empty_record = std::fs::read_to_string(empty).unwrap();
    assert!(
        !empty_record.contains(&alpha) && !empty_record.contains(&beta),
        "the empty selection's record names a toolkit pin:\n{empty_record}"
    );

    let stamp = |p: &Path| std::fs::metadata(p).unwrap().modified().unwrap();
    let before = stamp(&toolkit[0]);
    launch("gui2");
    assert_eq!(selection_records_of(&td), both);
    assert_eq!(
        stamp(&toolkit[0]),
        before,
        "an equivalent selection rewrote the record instead of reusing it"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// The resolver's link farms under the private runtime directory: one
/// per host state, named by its fingerprint and its winners.
fn farms_of(td: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    let run_dir = td.join("xdg-run");
    for store in std::fs::read_dir(&run_dir)
        .into_iter()
        .flatten()
        .flatten()
        .filter(|e| e.file_name().to_string_lossy().starts_with("resolve-"))
    {
        for entry in std::fs::read_dir(store.path())
            .into_iter()
            .flatten()
            .flatten()
            .filter(|e| e.file_name().to_string_lossy().starts_with("farm-"))
            .filter(|e| e.file_type().is_ok_and(|t| t.is_dir()))
        {
            out.push(entry.path());
        }
    }
    out.sort();
    out
}

/// How many view directories the cache view store holds.
fn view_count(views: &Path) -> usize {
    std::fs::read_dir(views)
        .map(|entries| {
            entries
                .flatten()
                .filter(|e| e.file_type().is_ok_and(|t| t.is_dir()))
                .count()
        })
        .unwrap_or(0)
}

/// Run `onelf cache gc --max-age 0` against `cache` and return its
/// report.
fn cache_gc(cache: &Path, home: &Path) -> String {
    let o = Command::new(onelf())
        .args(["cache", "gc", "--max-age", "0"])
        .env("XDG_CACHE_HOME", cache)
        .env("HOME", home.to_str().unwrap())
        .output()
        .expect("spawn onelf cache gc");
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    String::from_utf8_lossy(&o.stdout).into_owned()
}

/// A package with no sets loads its plugins late, once the launch
/// machinery is fully up: one from its own tree or view, and one that
/// only the host supplies, reached through the resolver's farm. Every
/// execution mode that can hold the launch open shows the same outcome,
/// and nothing in the view or the leases stands in the load's way.
#[test]
fn a_late_plugin_load_survives_a_launch_without_sets() {
    let td = workdir("latenosets");
    let host = td.join("host/lib");
    if !host_driver_pair(&td, "host", &host, 2) {
        return; // no compiler: documented soft-skip
    }
    let cache = td.join("ld.so.cache");
    std::fs::write(
        &cache,
        ld_so_cache(&[&host.join("libGL.so.1"), &host.join("libfixture.so.1")]),
    )
    .unwrap();
    let pkg = pack_late_loader(&td, "late");
    if pkg.as_os_str().is_empty() {
        return; // no compiler: documented soft-skip
    }
    let gate = td.join("gate");
    let result = td.join("result");
    let private_run = td.join("xdg-run");
    let views = td.join("xdg-cache/onelf/views");

    let mut modes: Vec<(&str, PathBuf)> =
        vec![("rundir", private_run.clone()), ("cache", views.clone())];
    if tmpfs_available() {
        modes.push(("tmpfs", private_run.clone()));
    }
    if fuse_available() {
        modes.push(("fuse", private_run.clone()));
    }
    for (mode, base) in modes {
        let _ = std::fs::remove_file(&gate);
        let _ = std::fs::remove_file(&result);
        let (mut child, view) = start_late_loader(
            &pkg,
            &td,
            mode,
            &[
                ("PLUGIN", "libplugin.so.1:libGL.so.1"),
                ("GATE", gate.to_str().unwrap()),
                ("RESULT", result.to_str().unwrap()),
                ("ONELF_LD_CACHE", cache.to_str().unwrap()),
            ],
        );
        assert!(
            view.starts_with(&base),
            "{mode}: the launch runs from its own tree: {}",
            view.display()
        );
        assert!(
            view.is_dir(),
            "{mode}: the tree is up while the load is held: {}",
            view.display()
        );
        std::fs::write(&gate, "").unwrap();
        let status = child.wait().unwrap();
        assert!(status.success(), "{mode}: the launcher failed: {status}");
        let report = std::fs::read_to_string(&result).unwrap_or_default();
        assert!(
            report.contains("late=libplugin.so.1:42"),
            "{mode}: the bundled plugin did not load: {report}"
        );
        assert!(
            report.contains("late=libGL.so.1:2"),
            "{mode}: the host driver did not load: {report}"
        );
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// The host's loader cache is rewritten to name a different driver copy
/// while a launch sits held before its late load. The next launch
/// resolves the changed host state into its own farm beside the old one
/// and answers with the new value, and the held launch still answers
/// with the copy it resolved, from a tree or view nothing edited.
#[test]
fn a_late_plugin_load_survives_a_changed_host_view() {
    let td = workdir("latehostview");
    let host_a = td.join("host-a/lib");
    let host_b = td.join("host-b/lib");
    if !host_driver_pair(&td, "host-a", &host_a, 2) {
        return; // no compiler: documented soft-skip
    }
    assert!(host_driver_pair(&td, "host-b", &host_b, 3));
    let cache = td.join("ld.so.cache");
    let pkg = pack_late_loader(&td, "viewkeep");
    if pkg.as_os_str().is_empty() {
        return; // no compiler: documented soft-skip
    }
    let gate = td.join("gate");
    let result = td.join("result");
    let result_b = td.join("result-b");
    let views = td.join("xdg-cache/onelf/views");

    for mode in ["rundir", "cache"] {
        for file in [&gate, &result, &result_b] {
            let _ = std::fs::remove_file(file);
        }
        std::fs::write(
            &cache,
            ld_so_cache(&[&host_a.join("libGL.so.1"), &host_a.join("libfixture.so.1")]),
        )
        .unwrap();
        // A launch on a mode that can take the host's libc describes a
        // different host state than one that cannot, so the farms count
        // from where this mode starts.
        let farms_before = farms_of(&td).len();
        let (mut held, view) = start_late_loader(
            &pkg,
            &td,
            mode,
            &[
                ("PLUGIN", "libGL.so.1"),
                ("GATE", gate.to_str().unwrap()),
                ("RESULT", result.to_str().unwrap()),
                ("ONELF_LD_CACHE", cache.to_str().unwrap()),
            ],
        );
        assert_eq!(
            farms_of(&td).len(),
            farms_before + 1,
            "{mode}: the first host state built one farm"
        );

        std::fs::write(
            &cache,
            ld_so_cache(&[&host_b.join("libGL.so.1"), &host_b.join("libfixture.so.1")]),
        )
        .unwrap();
        let (mut fresh, _) = start_late_loader(
            &pkg,
            &td,
            mode,
            &[
                ("PLUGIN", "libGL.so.1"),
                ("RESULT", result_b.to_str().unwrap()),
                ("ONELF_LD_CACHE", cache.to_str().unwrap()),
            ],
        );
        let fresh_status = fresh.wait().unwrap();
        assert!(
            fresh_status.success(),
            "{mode}: the launch on the changed host failed: {fresh_status}"
        );
        let fresh_report = std::fs::read_to_string(&result_b).unwrap_or_default();
        assert!(
            fresh_report.contains("late=libGL.so.1:3"),
            "{mode}: the changed host supplied its own copy: {fresh_report}"
        );

        let farms = farms_of(&td);
        assert_eq!(
            farms.len(),
            farms_before + 2,
            "{mode}: the new host state built its farm beside the old: {farms:?}"
        );
        let (mut from_a, mut from_b) = (false, false);
        for farm in &farms {
            let target = std::fs::read_link(farm.join("libGL.so.1"));
            if target.as_ref().is_ok_and(|t| t.starts_with(&host_a)) {
                from_a = true;
            }
            if target.as_ref().is_ok_and(|t| t.starts_with(&host_b)) {
                from_b = true;
            }
        }
        assert!(
            from_a && from_b,
            "{mode}: each farm serves its own host state: {farms:?}"
        );
        assert!(
            view.is_dir(),
            "{mode}: the changed host left the held launch's view alone: {}",
            view.display()
        );
        if mode == "cache" {
            assert_eq!(
                view_count(&views),
                2,
                "{mode}: two identities run from two views"
            );
        }

        std::fs::write(&gate, "").unwrap();
        let held_status = held.wait().unwrap();
        assert!(
            held_status.success(),
            "{mode}: the held launch failed: {held_status}"
        );
        let held_report = std::fs::read_to_string(&result).unwrap_or_default();
        assert!(
            held_report.contains("late=libGL.so.1:2"),
            "{mode}: the held launch still loads the host it resolved: {held_report}"
        );
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// Two cache launches one after the other run from one published view:
/// the second reuses it, ready record inode and all, instead of having
/// its own sweep reclaim the view and rebuild it. A view nothing has used
/// for longer than the age limit is still reclaimed by a launch's sweep.
#[test]
fn sequential_cache_launches_reuse_their_view() {
    use std::os::unix::fs::MetadataExt;
    let td = workdir("cachereuse");
    let empty = td.join("empty.cache");
    std::fs::write(&empty, ld_so_cache(&[])).unwrap();
    let pkg = pack_late_loader(&td, "reuse");
    if pkg.as_os_str().is_empty() {
        return; // no compiler: documented soft-skip
    }
    let views = td.join("xdg-cache/onelf/views");
    let launch = || {
        let (mut child, view) = start_late_loader(
            &pkg,
            &td,
            "cache",
            &[
                ("PLUGIN", "libplugin.so.1"),
                ("ONELF_LD_CACHE", empty.to_str().unwrap()),
            ],
        );
        let status = child.wait().unwrap();
        assert!(status.success(), "the cache launch failed: {status}");
        view
    };
    let ready_inode = |view: &Path| std::fs::metadata(view.join("ready")).unwrap().ino();

    let first = launch();
    assert!(first.starts_with(&views), "{}", first.display());
    let inode = ready_inode(&first);
    let second = launch();
    assert_eq!(first, second, "one identity, one view");
    assert_eq!(
        ready_inode(&second),
        inode,
        "the second launch reused the view instead of rebuilding it"
    );

    // Another identity's idle view, last used long past the age limit.
    let stale = views.join(format!("view-{}", "0".repeat(32)));
    std::fs::create_dir_all(&stale).unwrap();
    std::fs::write(stale.join("config"), b"onelf-view 1\n").unwrap();
    std::fs::write(stale.join("ready"), b"onelf-view-ready 1\n").unwrap();
    let lease =
        std::fs::File::create(views.join(format!("view-{}.lease", "0".repeat(32)))).unwrap();
    lease
        .set_modified(std::time::SystemTime::now() - std::time::Duration::from_secs(40 * 86400))
        .unwrap();
    drop(lease);

    let third = launch();
    assert_eq!(third, first);
    assert_eq!(ready_inode(&third), inode, "the live identity's view stays");
    assert!(
        !stale.exists(),
        "the long idle view is reclaimed by the sweep"
    );
}

/// A cache sweep runs while two launches share one view and both sit
/// before their late loads, while one has drained, and while the last
/// one has loaded but not exited: the view and its package are skipped
/// every time, and the sweep after the last lease is gone reclaims both.
#[test]
fn cache_gc_spares_a_launch_awaiting_a_late_plugin_load() {
    let td = workdir("lategc");
    let empty = td.join("empty.cache");
    std::fs::write(&empty, ld_so_cache(&[])).unwrap();
    let pkg = pack_late_loader(&td, "gclate");
    if pkg.as_os_str().is_empty() {
        return; // no compiler: documented soft-skip
    }
    let cache_root = td.join("xdg-cache");
    let views = cache_root.join("onelf/views");
    let gate = td.join("gate");
    let gate_b = td.join("gate-b");
    let result = td.join("result");
    let result_b = td.join("result-b");
    let hold = td.join("hold");

    let holder = |gate: &str, result: &str, hold: &str| {
        start_late_loader(
            &pkg,
            &td,
            "cache",
            &[
                ("PLUGIN", "libplugin.so.1"),
                ("GATE", gate),
                ("RESULT", result),
                ("HOLD", hold),
                ("ONELF_LD_CACHE", empty.to_str().unwrap()),
            ],
        )
    };
    let (mut first, view) = holder(
        gate.to_str().unwrap(),
        result.to_str().unwrap(),
        hold.to_str().unwrap(),
    );
    // The second holder runs to completion once its gate opens, so the
    // sweep sees one drained launch and one still living.
    let (mut second, view_b) = holder(gate_b.to_str().unwrap(), result_b.to_str().unwrap(), "");
    assert_eq!(view, view_b, "one identity serves both launches");
    assert!(
        view.starts_with(&views),
        "the launch runs from a published view: {}",
        view.display()
    );
    assert_eq!(view_count(&views), 1, "the shared view is published once");

    let while_both_hold = cache_gc(&cache_root, &td);
    assert!(
        !while_both_hold.contains("idle view"),
        "the sweep must leave a view two launches hold: {while_both_hold}"
    );
    assert!(
        while_both_hold.contains("Skipped 1 package"),
        "the sweep must spare the live package: {while_both_hold}"
    );
    assert!(view.is_dir(), "the shared view survives the sweep");

    std::fs::write(&gate_b, "").unwrap();
    let second_status = second.wait().unwrap();
    assert!(
        second_status.success(),
        "the second launch failed: {second_status}"
    );
    let second_report = std::fs::read_to_string(&result_b).unwrap_or_default();
    assert!(
        second_report.contains("late=libplugin.so.1:42"),
        "the second launch's late load failed: {second_report}"
    );
    let after_one_left = cache_gc(&cache_root, &td);
    assert!(
        !after_one_left.contains("idle view"),
        "one drained launch must not idle the view the other holds: \
         {after_one_left}"
    );
    assert!(view.is_dir(), "the remaining launch keeps its view");

    std::fs::write(&gate, "").unwrap();
    assert!(
        until(|| {
            std::fs::read_to_string(&result).is_ok_and(|s| s.contains("late=libplugin.so.1:42"))
        }),
        "the last launch's late load failed"
    );
    let while_loaded = cache_gc(&cache_root, &td);
    assert!(
        !while_loaded.contains("idle view"),
        "a loaded but living launch still leases its view: {while_loaded}"
    );
    assert!(view.is_dir());

    std::fs::write(&hold, "").unwrap();
    let first_status = first.wait().unwrap();
    assert!(
        first_status.success(),
        "the last launch failed: {first_status}"
    );
    use rustix::fs::FlockOperation;
    let lease = views.join(format!(
        "{}.lease",
        view.file_name().unwrap().to_string_lossy()
    ));
    assert!(
        until(|| {
            std::fs::File::open(&lease)
                .map(|f| rustix::fs::flock(&f, FlockOperation::NonBlockingLockExclusive).is_ok())
                .unwrap_or(false)
        }),
        "the drained launch's lease is released"
    );
    let when_idle = cache_gc(&cache_root, &td);
    assert!(
        when_idle.contains("Removed 1 idle view(s)."),
        "the sweep reclaims the view once its lease is gone: {when_idle}"
    );
    assert!(
        when_idle.contains("Removed 1 stale package"),
        "the sweep reclaims the package with it: {when_idle}"
    );
    assert_eq!(view_count(&views), 0, "nothing of the view is left");
    let _ = std::fs::remove_dir_all(&td);
}

/// An app double-forks a helper that drops every inherited descriptor,
/// so nothing the app carried can hold its view open, and the launcher
/// returns while the helper waits. A cache sweep still finds the view
/// leased, the helper's late load reads the plugin out of the view with
/// nothing inherited, and the view is reclaimed only after the helper
/// finishes. Every other mode that runs a guardian shows the same
/// lifetime, and in each one the helper's adopting ancestor is a process
/// of the launch itself, never init or a process started later.
#[test]
fn a_double_fork_helper_that_closes_every_fd_keeps_its_late_load_alive() {
    let td = workdir("latefdclose");
    let empty = td.join("empty.cache");
    std::fs::write(&empty, ld_so_cache(&[])).unwrap();
    let pkg = pack_late_loader(&td, "fddrain");
    if pkg.as_os_str().is_empty() {
        return; // no compiler: documented soft-skip
    }
    let cache_root = td.join("xdg-cache");
    let views = cache_root.join("onelf/views");
    let ready = td.join("ready");
    let gate = td.join("gate");
    let result = td.join("result");
    let hold = td.join("hold");
    let done = td.join("done");

    for (mode, run_mode, mode_env) in guarded_modes() {
        for file in [&ready, &gate, &result, &hold, &done] {
            let _ = std::fs::remove_file(file);
        }
        let mut envs = vec![
            ("DAEMON", "1"),
            ("READY", ready.to_str().unwrap()),
            ("GATE", gate.to_str().unwrap()),
            ("PLUGIN", "libplugin.so.1"),
            ("RESULT", result.to_str().unwrap()),
            ("HOLD", hold.to_str().unwrap()),
            ("DONE", done.to_str().unwrap()),
            ("ONELF_LD_CACHE", empty.to_str().unwrap()),
        ];
        envs.extend(mode_env);
        let (mut child, view) = start_late_loader(&pkg, &td, run_mode, &envs);
        let status = child.wait().unwrap();
        assert!(
            status.success(),
            "{mode}: the launcher returned while the helper lives: {status}"
        );
        assert!(
            until(|| std::fs::read_to_string(&ready).is_ok_and(|s| s.starts_with("closed "))),
            "{mode}: the helper never dropped its descriptors"
        );
        let ancestor = std::fs::read_to_string(&ready).unwrap();
        let ancestor = ancestor.trim_start_matches("closed ").trim();
        // The process name, not the executable link or the command
        // line: a guardian inside a user namespace of its own keeps those
        // from this process.
        let status =
            std::fs::read_to_string(format!("/proc/{ancestor}/status")).unwrap_or_default();
        let field = |key: &str| {
            status
                .lines()
                .find_map(|l| l.strip_prefix(key))
                .map(str::trim)
                .unwrap_or_default()
                .to_string()
        };
        assert_eq!(
            field("Name:"),
            "fddrain.onelf",
            "{mode}: the helper's adopting ancestor {ancestor} is not the launch's guardian: {status}"
        );
        assert!(
            !field("State:").starts_with('Z'),
            "{mode}: the adopting guardian already exited: {status}"
        );
        if mode == "cache" {
            let while_held = cache_gc(&cache_root, &td);
            assert!(
                !while_held.contains("idle view"),
                "{mode}: a sweep must not idle the view a descriptor-dropping \
                 helper runs from: {while_held}"
            );
        }
        assert!(
            view.is_dir(),
            "{mode}: the view outlives the launcher: {}: {:?}",
            view.display(),
            std::fs::metadata(&view)
        );

        std::fs::write(&gate, "").unwrap();
        assert!(
            until(|| {
                std::fs::read_to_string(&result).is_ok_and(|s| s.contains("late=libplugin.so.1:42"))
            }),
            "{mode}: the helper's late load failed after every descriptor \
             was dropped"
        );
        if mode == "cache" {
            let after_load = cache_gc(&cache_root, &td);
            assert!(
                !after_load.contains("idle view"),
                "{mode}: the working helper's view stays leased: {after_load}"
            );
            assert!(view.is_dir(), "{mode}: the view stays while it works");
        }

        std::fs::write(&hold, "").unwrap();
        assert!(
            until(|| done.is_file()),
            "{mode}: the helper never finished"
        );
        if mode == "cache" {
            use rustix::fs::FlockOperation;
            let lease = views.join(format!(
                "{}.lease",
                view.file_name().unwrap().to_string_lossy()
            ));
            assert!(
                until(|| {
                    std::fs::File::open(&lease)
                        .map(|f| {
                            rustix::fs::flock(&f, FlockOperation::NonBlockingLockExclusive).is_ok()
                        })
                        .unwrap_or(false)
                }),
                "{mode}: the finished helper's lease is released"
            );
            let when_idle = cache_gc(&cache_root, &td);
            assert!(
                when_idle.contains("Removed 1 idle view(s)."),
                "{mode}: the drained helper's view is reclaimed: {when_idle}"
            );
            assert_eq!(view_count(&views), 0, "{mode}: nothing of the view is left");
        } else if mode == "rundir" {
            assert!(
                until(|| std::fs::symlink_metadata(&view).is_err()),
                "{mode}: the view is taken down after the helper finishes"
            );
        }
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// One mode [`guarded_modes`] lists: a label, the `ONELF_MODE` value,
/// and the environment the mode needs.
type GuardedMode = (
    &'static str,
    &'static str,
    Vec<(&'static str, &'static str)>,
);

/// The modes that run the application under a lifetime guardian. tmpfs
/// and both FUSE launch forms are included where this host has them.
fn guarded_modes() -> Vec<GuardedMode> {
    let mut modes = vec![("rundir", "rundir", vec![]), ("cache", "cache", vec![])];
    if tmpfs_available() {
        modes.push(("tmpfs", "tmpfs", vec![]));
    }
    if fuse_available() {
        modes.push(("private fuse", "fuse", vec![("ONELF_FUSE_NO_SHARE", "1")]));
        modes.push(("shared fuse", "fuse", vec![]));
    }
    modes
}

/// An app that counts the SIGINTs it receives: it marks `$ARMED` once
/// its handler is in place, waits for `$STOP`, settles so any duplicate
/// delivery lands, and writes the count to `$COUNT`. With `$RAISE` set
/// it kills itself with that signal at once instead.
const SIGNAL_COUNTER_SRC: &str = r#"#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

static volatile sig_atomic_t ints;

static void on_int(int sig) {
    (void)sig;
    ints++;
}

int main(void) {
    const char *raise_sig = getenv("RAISE");
    if (raise_sig && *raise_sig) {
        signal(atoi(raise_sig), SIG_DFL);
        raise(atoi(raise_sig));
        return 3;
    }
    const char *armed = getenv("ARMED");
    const char *stop = getenv("STOP");
    const char *count = getenv("COUNT");
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = on_int;
    sigaction(SIGINT, &sa, NULL);
    FILE *a = fopen(armed, "w");
    if (a) {
        fputs("1", a);
        fclose(a);
    }
    for (int i = 0; i < 600 && access(stop, F_OK) != 0; i++) {
        usleep(50000);
    }
    usleep(300000);
    FILE *c = fopen(count, "w");
    if (c) {
        fprintf(c, "%d", (int)ints);
        fclose(c);
    }
    return 0;
}
"#;

/// Runs `argv[1..]` as the session leader of a fresh pseudo-terminal,
/// its process group the terminal's foreground, types one Ctrl-C once
/// `$ARMED` exists, then creates `$STOP`, and prints how the program
/// ended. The Ctrl-C is the terminal's own SIGINT to the whole group.
const PTY_HARNESS_SRC: &str = r#"#define _XOPEN_SOURCE 600
#define _DEFAULT_SOURCE
#include <fcntl.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/ioctl.h>
#include <sys/wait.h>
#include <unistd.h>

int main(int argc, char **argv) {
    const char *armed = getenv("ARMED");
    const char *stop = getenv("STOP");
    if (argc < 2) {
        return 89;
    }
    int m = posix_openpt(O_RDWR | O_NOCTTY);
    if (m < 0 || grantpt(m) || unlockpt(m)) {
        return 90;
    }
    char *name = ptsname(m);
    pid_t p = fork();
    if (p == 0) {
        setsid();
        int s = open(name, O_RDWR);
        if (s < 0 || ioctl(s, TIOCSCTTY, 0)) {
            _exit(91);
        }
        dup2(s, 0);
        dup2(s, 1);
        dup2(s, 2);
        if (s > 2) {
            close(s);
        }
        close(m);
        execv(argv[1], argv + 1);
        _exit(92);
    }
    fcntl(m, F_SETFL, O_NONBLOCK);
    char buf[512];
    int status = 0, sent = 0, stopped = 0;
    for (int i = 0; i < 1200; i++) {
        while (read(m, buf, sizeof buf) > 0) {
        }
        if (!sent && access(armed, F_OK) == 0) {
            usleep(200000);
            if (write(m, "\x03", 1) == 1) {
                sent = 1;
            }
        } else if (sent && !stopped) {
            usleep(500000);
            FILE *f = fopen(stop, "w");
            if (f) {
                fputs("1", f);
                fclose(f);
            }
            stopped = 1;
        }
        if (waitpid(p, &status, WNOHANG) == p) {
            printf("sent=%d exit=%d signal=%d\n", sent,
                   WIFEXITED(status) ? WEXITSTATUS(status) : -1,
                   WIFSIGNALED(status) ? WTERMSIG(status) : 0);
            return 0;
        }
        usleep(50000);
    }
    kill(p, SIGKILL);
    return 93;
}
"#;

/// Pack the signal counter as `bin/run`, and compile the terminal
/// harness beside it. `None` without a compiler.
fn pack_signal_counter(td: &Path) -> Option<(PathBuf, PathBuf)> {
    let app = td.join("sigapp");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    write(&td.join("sig.c"), SIGNAL_COUNTER_SRC);
    if !cc(&td.join("sig.c"), &app.join("bin/run")) {
        return None;
    }
    write(&td.join("pty.c"), PTY_HARNESS_SRC);
    let harness = td.join("ptyrun");
    if !cc(&td.join("pty.c"), &harness) {
        return None;
    }
    let pkg = td.join("sigapp.onelf");
    let o = Command::new(onelf())
        .args(["pack", app.to_str().unwrap(), "-o", pkg.to_str().unwrap()])
        .args(["--command", "bin/run", "--mtime", "0", "--name", "sigapp"])
        .output()
        .expect("spawn onelf pack");
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    Some((pkg, harness))
}

/// A Ctrl-C typed at the terminal reaches the whole foreground process
/// group: the launcher, its guardian and the app. The app must receive
/// it exactly once, so neither the launcher nor the guardian forwards a
/// signal the terminal already delivered, and an app that handles the
/// first Ctrl-C is not hit again by forwarded copies.
#[test]
fn a_terminal_ctrl_c_reaches_a_guarded_app_once() {
    let td = workdir("ttysig");
    let Some((pkg, harness)) = pack_signal_counter(&td) else {
        return; // no compiler: documented soft-skip
    };
    for (mode, run_mode, mode_env) in guarded_modes() {
        let armed = td.join(format!("armed-{run_mode}-{}", mode_env.len()));
        let stop = td.join(format!("stop-{run_mode}-{}", mode_env.len()));
        let count = td.join(format!("count-{run_mode}-{}", mode_env.len()));
        let mut run = Command::new(&harness);
        run.arg(&pkg)
            .env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("ONELF_MODE", run_mode)
            .env("ARMED", &armed)
            .env("STOP", &stop)
            .env("COUNT", &count);
        isolate(&mut run, &td);
        for (name, value) in mode_env {
            run.env(name, value);
        }
        let o = run_package(&mut run);
        let report = String::from_utf8_lossy(&o.stdout);
        assert!(o.status.success(), "{mode}: the harness failed: {report}");
        assert!(report.contains("sent=1 exit=0"), "{mode}: {report}");
        assert_eq!(
            std::fs::read_to_string(&count).unwrap_or_default(),
            "1",
            "{mode}: the app must see the terminal's Ctrl-C once"
        );
    }
}

/// An app killed by a signal makes the launcher die of the same signal,
/// so a shell loop or a supervisor sees the signal rather than an exit
/// status of 128 plus its number.
#[test]
fn a_signal_killed_app_kills_its_launcher_with_the_same_signal() {
    use std::os::unix::process::ExitStatusExt;
    let td = workdir("sigdeath");
    let Some((pkg, _)) = pack_signal_counter(&td) else {
        return; // no compiler: documented soft-skip
    };
    for (mode, run_mode, mode_env) in guarded_modes() {
        let mut run = Command::new(&pkg);
        run.env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("ONELF_MODE", run_mode)
            .env("RAISE", "15");
        isolate(&mut run, &td);
        for (name, value) in mode_env {
            run.env(name, value);
        }
        let status = run_package(&mut run).status;
        assert_eq!(
            status.signal(),
            Some(15),
            "{mode}: the launcher must die of the app's SIGTERM: {status}"
        );
    }
}

/// The environment a development run needs to stay hermetic: a PATH, an
/// isolated HOME, the launch's own store, and set extraction instead of
/// a mount. The caller appends the run's spec and flags.
fn dev_run(td: &Path, args: &[&str]) -> Command {
    let mut cmd = Command::new(onelf());
    cmd.arg("run")
        .args(args)
        .env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_SET_MODE", "extract")
        .env("ONELF_PLATFORM_STORE", td.join("store"));
    isolate(&mut cmd, td);
    cmd
}

/// The one prepared view in a test's store, which a single-launch test
/// can name this way. The view's lease and creation lock share its name
/// prefix, so only the directory answers.
fn the_prepared_view(store: &Path) -> PathBuf {
    std::fs::read_dir(store)
        .expect("the view store")
        .find_map(|e| {
            let e = e.unwrap();
            let is_view = e.file_type().is_ok_and(|t| t.is_dir())
                && e.file_name()
                    .to_str()
                    .is_some_and(|n| n.starts_with("view-"));
            is_view.then(|| e.path())
        })
        .expect("the prepared view")
}

/// A development `run --bundle` stages the same sysroot closure a build
/// stages, and the launch resolves against it.
#[test]
fn run_bundle_assembles_a_sysroot_recipe() {
    let td = workdir("runsysroot");
    let Some(fixture) = synthetic_sysroot(&td) else {
        return;
    };
    let dir = td.join("app");
    std::fs::create_dir_all(&dir).unwrap();
    sysroot_recipe(&dir, &fixture, "");

    let mut cmd = dev_run(&td, &["--bundle"]);
    cmd.arg(&dir).env("ONELF_LD_CACHE", &fixture.ld_cache);
    let out = cmd.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{stdout}{stderr}");
    assert!(stdout.contains("value=42"), "{stdout}{stderr}");
    assert!(
        dir.join("lib/libfixture.so.1").is_file(),
        "the sysroot closure is absent from the staged tree:\n{stderr}"
    );
    assert!(
        dir.join(".onelf/provenance.toml").is_file(),
        "the sysroot build carries no provenance:\n{stderr}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// The sysroot rules a recipe names reach the assembly a development run
/// stages: the policy prunes what never ships, and the platform line
/// hands its libraries to the host.
#[test]
fn run_bundle_applies_the_sysroot_rules() {
    let td = workdir("runrules");
    let Some(fixture) = synthetic_sysroot(&td) else {
        return;
    };
    let dir = td.join("app");
    std::fs::create_dir_all(&dir).unwrap();
    sysroot_recipe(&dir, &fixture, "");

    let mut cmd = dev_run(&td, &["--bundle"]);
    cmd.arg(&dir).env("ONELF_LD_CACHE", &fixture.ld_cache);
    let out = cmd.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{stdout}{stderr}");
    assert!(stdout.contains("value=42"), "{stdout}{stderr}");
    assert!(
        !dir.join("share/doc").exists(),
        "the policy's pruning did not reach the staged tree:\n{stderr}"
    );
    assert!(
        !dir.join("lib/libGL.so.1").exists(),
        "the platform line's host decision did not reach the staged tree:\n{stderr}"
    );
    assert!(
        stderr.contains("Host-provided:") && stderr.contains("libGL.so.1"),
        "the rule's decision is not reported:\n{stderr}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// A bundle exclusion reaches the development launch: the excluded
/// soname stays out of the assembled tree, and the launch runs against
/// exactly that tree.
#[test]
fn run_bundle_honors_bundle_exclusions() {
    let td = workdir("runexclude");
    let src = td.join("src");
    std::fs::create_dir_all(&src).unwrap();

    // A host of this test's own making, supplying both sonames through
    // the recipe's search paths.
    let host = td.join("host");
    std::fs::create_dir_all(&host).unwrap();
    write(&src.join("keep.c"), "int keep_value(void){return 5;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libkeep.so.9fixture",
            src.join("keep.c").to_str().unwrap(),
        ],
        &host.join("libkeep.so.9fixture"),
    ));
    write(&src.join("extra.c"), "int extra_value(void){return 7;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libextra.so.9fixture",
            src.join("extra.c").to_str().unwrap(),
        ],
        &host.join("libextra.so.9fixture"),
    ));

    // The application needs one soname outright and opens the other by
    // name, so the scanner looks for both once dlopen scanning is on.
    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    write(
        &src.join("app.c"),
        "#include <dlfcn.h>\n#include <stdio.h>\nint keep_value(void);\nint main(void){void *h = dlopen(\"libextra.so.9fixture\", RTLD_NOW);printf(\"extra=%s\\n\", h ? \"loaded\" : \"absent\");if (h) dlclose(h);printf(\"value=%d\\n\", keep_value());return 0;}\n",
    );
    assert!(cc_with(
        &[
            src.join("app.c").to_str().unwrap(),
            &format!("-L{}", host.display()),
            "-l:libkeep.so.9fixture",
            "-ldl",
        ],
        &dir.join("bin/app"),
    ));
    let recipe = |dir: &Path, exclude: bool| {
        write(
            &dir.join("onelf.toml"),
            &format!(
                "[package]\ncommand = \"bin/app\"\n\n[bundle]\nscan-dlopen = true\n\
                 dlopen = [\"libextra.so.9fixture\"]\nsearch-paths = [\"{}\"]{}",
                host.display(),
                if exclude {
                    "\nexclude = [\"libextra\"]"
                } else {
                    ""
                }
            ),
        );
    };

    // Without the exclusion both libraries land in the bundle.
    let control = td.join("control");
    std::fs::create_dir_all(control.join("bin")).unwrap();
    std::fs::copy(dir.join("bin/app"), control.join("bin/app")).unwrap();
    recipe(&control, false);
    let mut cmd = dev_run(&td, &["--bundle"]);
    cmd.arg(&control);
    let out = cmd.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{stdout}{stderr}");
    assert!(stdout.contains("extra=loaded"), "{stdout}{stderr}");
    assert!(stdout.contains("value=5"), "{stdout}{stderr}");
    assert!(control.join("lib/libkeep.so.9fixture").is_file());
    assert!(control.join("lib/libextra.so.9fixture").is_file());

    // With it, the excluded soname stays out and the launch runs against
    // exactly that tree.
    recipe(&dir, true);
    let mut cmd = dev_run(&td, &["--bundle"]);
    cmd.arg(&dir);
    let out = cmd.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{stdout}{stderr}");
    assert!(stdout.contains("extra=absent"), "{stdout}{stderr}");
    assert!(stdout.contains("value=5"), "{stdout}{stderr}");
    assert!(dir.join("lib/libkeep.so.9fixture").is_file());
    assert!(
        !dir.join("lib/libextra.so.9fixture").exists(),
        "the excluded soname was bundled:\n{stderr}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// A named entrypoint launches with its own set selection: the
/// entrypoint that declares no sets acquires nothing, and the one that
/// selects a set acquires exactly that pin.
#[test]
fn run_bundle_acquires_the_selected_entrypoints_sets() {
    let td = workdir("runselect");
    if set_library(
        &td,
        "toolkit",
        "libtoolkit.so.99fixture",
        "int toolkit_value(void){return 9;}\n",
    )
    .is_none()
    {
        return;
    }
    let (hash, set_pkg) = pack_set(&td, "toolkit", "toolkit");

    let dir = td.join("app");
    write(&dir.join("bin/cli"), "#!/bin/sh\necho ran=cli\n");
    write(&dir.join("bin/gui"), "#!/bin/sh\necho ran=gui\n");
    for script in ["bin/cli", "bin/gui"] {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(dir.join(script), std::fs::Permissions::from_mode(0o755)).unwrap();
    }
    write(
        &dir.join("onelf.toml"),
        &format!(
            "[package]\ncommand = \"bin/cli\"\n\n[bundle]\nskip = true\n\n\
             [sysroot.sets.toolkit]\npackages = [\"libtoolkit\"]\nurl = \"file://{}\"\n\
             blake3 = \"{hash}\"\n\n\
             [[entrypoint]]\nname = \"cli\"\npath = \"bin/cli\"\nsets = []\ndefault = true\n\n\
             [[entrypoint]]\nname = \"gui\"\npath = \"bin/gui\"\nsets = [\"toolkit\"]\n",
            set_pkg.display()
        ),
    );
    let store = td.join("store");

    // The CLI entrypoint selects nothing: no acquisition, no store.
    let mut cmd = dev_run(&td, &["--bundle", "--entrypoint", "cli"]);
    cmd.arg(&dir);
    let out = cmd.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{stdout}{stderr}");
    assert!(stdout.contains("ran=cli"), "{stdout}{stderr}");
    assert!(
        !store.join("toolkit").exists(),
        "the entrypoint that selects no sets acquired the toolkit:\n{stderr}"
    );

    // The GUI entrypoint selects the toolkit set: exactly that pin.
    let mut cmd = dev_run(&td, &["--bundle", "--entrypoint", "gui"]);
    cmd.arg(&dir);
    let out = cmd.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{stdout}{stderr}");
    assert!(stdout.contains("ran=gui"), "{stdout}{stderr}");
    assert!(
        store
            .join("toolkit")
            .join(format!("{hash}.onelf"))
            .is_file(),
        "the selected set is not in the store:\n{stderr}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// A development run keeps its unpackaged behavior: nothing assembles
/// without `--bundle`, and `--bundle` on a recipe-less tree still runs.
#[test]
fn run_without_bundle_keeps_the_development_launch() {
    let td = workdir("rundev");

    // No recipe: the single binary under bin/ launches, with or without
    // --bundle, and --bundle without a recipe says so and runs anyway.
    let dir = td.join("app");
    write(&dir.join("bin/run.sh"), "#!/bin/sh\necho hi\n");
    use std::os::unix::fs::PermissionsExt;
    std::fs::set_permissions(
        dir.join("bin/run.sh"),
        std::fs::Permissions::from_mode(0o755),
    )
    .unwrap();
    for bundle in [false, true] {
        let mut args = Vec::new();
        if bundle {
            args.push("--bundle");
        }
        let mut cmd = dev_run(&td, &args);
        cmd.arg(&dir);
        let out = cmd.output().expect("spawn onelf run");
        let stdout = String::from_utf8_lossy(&out.stdout);
        let stderr = String::from_utf8_lossy(&out.stderr);
        assert!(out.status.success(), "bundle={bundle}: {stdout}{stderr}");
        assert!(stdout.contains("hi"), "bundle={bundle}: {stdout}{stderr}");
        if bundle {
            assert!(stderr.contains("--bundle skipped"), "{stderr}");
        }
    }

    // Without --bundle nothing assembles: an [input] the recipe imports
    // is not staged, and the missing target is reported.
    let upstream = td.join("upstream");
    write(&upstream.join("app"), "#!/bin/sh\necho imported\n");
    std::fs::set_permissions(upstream.join("app"), std::fs::Permissions::from_mode(0o755)).unwrap();
    let dir = td.join("imp");
    std::fs::create_dir_all(&dir).unwrap();
    write(
        &dir.join("onelf.toml"),
        "[package]\ncommand = \"bin/app\"\n\n[input]\nbinary = \"../upstream/app\"\n",
    );
    let mut cmd = dev_run(&td, &[]);
    cmd.arg(&dir);
    let out = cmd.output().expect("spawn onelf run");
    assert!(!out.status.success());
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(stderr.contains("entrypoint target not found"), "{stderr}");
    assert!(
        stderr.contains("--bundle"),
        "the incomplete tree does not name the assembly that stages it: {stderr}"
    );
    assert!(
        !dir.join("bin/app").exists(),
        "the import ran without --bundle"
    );

    // Without --bundle no set is acquired, so an entrypoint that selects
    // one is an incomplete tree: the run names the sets and the assembly
    // instead of letting the host stand in. One that selects none runs.
    let dir = td.join("sets");
    write(&dir.join("bin/run.sh"), "#!/bin/sh\necho ran\n");
    std::fs::set_permissions(
        dir.join("bin/run.sh"),
        std::fs::Permissions::from_mode(0o755),
    )
    .unwrap();
    write(
        &dir.join("onelf.toml"),
        &format!(
            "[package]\ncommand = \"bin/run.sh\"\n\n[bundle]\nskip = true\n\n\
             [sysroot.sets.toolkit]\npackages = [\"t\"]\nurl = \"file:///nonexistent/t.onelf\"\n\
             blake3 = \"{}\"\n\n\
             [[entrypoint]]\nname = \"cli\"\npath = \"bin/run.sh\"\nsets = []\n",
            "0".repeat(64)
        ),
    );
    let mut cmd = dev_run(&td, &[]);
    cmd.arg(&dir);
    let out = cmd.output().expect("spawn onelf run");
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "the run ignored its sets: {stderr}");
    assert!(stderr.contains("selects the sets toolkit"), "{stderr}");
    assert!(stderr.contains("--bundle"), "{stderr}");
    assert!(!String::from_utf8_lossy(&out.stdout).contains("ran"));
    let mut cmd = dev_run(&td, &["--entrypoint", "cli"]);
    cmd.arg(&dir);
    let out = cmd.output().expect("spawn onelf run");
    assert!(
        out.status.success() && String::from_utf8_lossy(&out.stdout).contains("ran"),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// The recipe's host-library decision reaches a bundle launch: under
/// `auto` the driver stack on the host satisfies the application, while
/// the same tree with `never` refuses the host copy and the launch fails
/// naming the soname nothing in the tree supplies.
#[test]
fn run_bundle_honors_the_host_libs_decision() {
    let td = workdir("runhostlibs");
    let src = td.join("src");
    std::fs::create_dir_all(&src).unwrap();

    // A host driver of this test's own making, named by the loader cache.
    let host = td.join("host");
    std::fs::create_dir_all(&host).unwrap();
    write(&src.join("gl.c"), "int gl_value(void){return 6;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libGL.so.1",
            src.join("gl.c").to_str().unwrap(),
        ],
        &host.join("libGL.so.1"),
    ));
    let cache = td.join("ld.so.cache");
    std::fs::write(&cache, ld_so_cache(&[&host.join("libGL.so.1")])).unwrap();

    // The application needs the driver soname; the tree holds a library
    // directory without it, so the resolver is what could satisfy it.
    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    std::fs::create_dir_all(dir.join("lib")).unwrap();
    write(
        &src.join("app.c"),
        "#include <stdio.h>\nextern int gl_value(void);\nint main(void){printf(\"value=%d\\n\", gl_value());return 0;}\n",
    );
    assert!(cc_with(
        &[
            src.join("app.c").to_str().unwrap(),
            &format!("-L{}", host.display()),
            "-l:libGL.so.1",
        ],
        &dir.join("bin/app"),
    ));
    write(&src.join("placeholder.c"), "int hold(void){return 0;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            src.join("placeholder.c").to_str().unwrap()
        ],
        &dir.join("lib/libplaceholder.so"),
    ));

    let recipe = |dir: &Path, never: bool| {
        write(
            &dir.join("onelf.toml"),
            &format!(
                "[package]\ncommand = \"bin/app\"{}[bundle]\nskip = true\n",
                if never {
                    "\nhost-libs = \"never\"\n\n"
                } else {
                    "\n\n"
                }
            ),
        );
    };

    // Control: the driver family's host copy satisfies the launch.
    let control = td.join("control");
    std::fs::create_dir_all(control.join("bin")).unwrap();
    std::fs::create_dir_all(control.join("lib")).unwrap();
    std::fs::copy(dir.join("bin/app"), control.join("bin/app")).unwrap();
    std::fs::copy(
        dir.join("lib/libplaceholder.so"),
        control.join("lib/libplaceholder.so"),
    )
    .unwrap();
    recipe(&control, false);
    let mut cmd = dev_run(&td, &["--bundle"]);
    cmd.arg(&control).env("ONELF_LD_CACHE", &cache);
    let out = cmd.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{stdout}{stderr}");
    assert!(stdout.contains("value=6"), "{stdout}{stderr}");

    // `never`: the host copy must not satisfy the launch. Whether the
    // loader finds no copy at all or a system one that lacks the
    // fixture's symbol, the launch ends early and never answers with
    // the fixture host's value, which the farm would have supplied.
    recipe(&dir, true);
    let mut cmd = dev_run(&td, &["--bundle"]);
    cmd.arg(&dir).env("ONELF_LD_CACHE", &cache);
    let out = cmd.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        !out.status.success(),
        "the launch ran on a host copy the recipe refused: {stdout} {}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(
        !stdout.contains("value=6"),
        "the refused host copy satisfied the launch: {stdout}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// A library directory the caller puts on `LD_LIBRARY_PATH` never
/// supplies a dependency to a bundled helper a packed launch starts: the
/// caller's value is gone from the application's environment, so the
/// helper's lookup cannot reach the decoy there.
#[test]
fn an_inherited_library_path_does_not_reach_a_bundled_helper() {
    let td = workdir("packinherited");
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    let caller = td.join("caller-lib");
    std::fs::create_dir_all(&caller).unwrap();
    write(&td.join("hole.c"), "int hole_value(void){return 3;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libhole.so.1",
            td.join("hole.c").to_str().unwrap(),
        ],
        &caller.join("libhole.so.1")
    ));
    write(
        &td.join("helper.c"),
        r#"#include <dlfcn.h>
#include <stdio.h>
int main(void) {
    void *h = dlopen("libhole.so.1", RTLD_NOW);
    printf("hole=%s\n", h ? "loaded" : "absent");
    return 0;
}
"#,
    );
    assert!(cc_with(
        &[td.join("helper.c").to_str().unwrap(), "-ldl"],
        &app.join("bin/helper")
    ));
    write(
        &app.join("bin/run.sh"),
        "#!/bin/sh\necho \"lp=${LD_LIBRARY_PATH-(unset)}\"\nexec \"$ONELF_DIR/bin/helper\"\n",
    );
    use std::os::unix::fs::PermissionsExt;
    std::fs::set_permissions(
        app.join("bin/run.sh"),
        std::fs::Permissions::from_mode(0o755),
    )
    .unwrap();

    let pkg = td.join("app.onelf");
    let o = Command::new(onelf())
        .args(["pack", app.to_str().unwrap(), "-o", pkg.to_str().unwrap()])
        .args(["--command", "bin/run.sh", "--mtime", "0"])
        .output()
        .expect("spawn onelf pack");
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));

    let mut modes = vec!["rundir"];
    if fuse_available() {
        modes.push("fuse");
    }
    for mode in modes {
        let mut run = Command::new(&pkg);
        run.env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("ONELF_MODE", mode)
            .env("LD_LIBRARY_PATH", &caller);
        isolate(&mut run, &td);
        let out = run_package(&mut run);
        let stdout = String::from_utf8_lossy(&out.stdout);
        let report = format!("{mode}: {}{stdout}", String::from_utf8_lossy(&out.stderr));
        assert!(out.status.success(), "{report}");
        assert!(
            stdout.contains("hole=absent"),
            "the caller's copy loaded: {report}"
        );
        assert!(stdout.contains("lp=(unset)"), "{report}");
    }
    let _ = std::fs::remove_dir_all(&td);
}

/// A library directory the caller puts on `LD_LIBRARY_PATH` never
/// supplies a development launch's missing dependency: the launch
/// resolves from the tree's own directories alone, and neither the app
/// nor a host child it spawns sees the caller's directory.
#[test]
fn an_inherited_library_path_does_not_satisfy_a_dev_run() {
    let td = workdir("runinherited");
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    std::fs::create_dir_all(app.join("lib")).unwrap();
    let caller = td.join("caller-lib");
    std::fs::create_dir_all(&caller).unwrap();

    // The dependency exists only where the caller points the loader.
    write(&td.join("hole.c"), "int hole_value(void){return 3;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libhole.so.1",
            td.join("hole.c").to_str().unwrap(),
        ],
        &caller.join("libhole.so.1")
    ));
    // The tree carries a library directory of its own, so the launch has
    // a search path to resolve from.
    write(&td.join("plain.c"), "int plain_value(void){return 1;}\n");
    assert!(cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libplain.so.1",
            td.join("plain.c").to_str().unwrap(),
        ],
        &app.join("lib/libplain.so.1")
    ));
    write(
        &td.join("app.c"),
        r#"#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
int main(void) {
    const char *lp = getenv("LD_LIBRARY_PATH");
    printf("app_lp=%s\n", lp ? lp : "(unset)");
    void *h = dlopen("libhole.so.1", RTLD_NOW);
    printf("hole=%s\n", h ? "loaded" : "absent");
    if (h) dlclose(h);
    fflush(stdout);
    if (system("echo child_lp=$LD_LIBRARY_PATH") != 0) return 1;
    return 0;
}
"#,
    );
    assert!(cc_with(
        &[td.join("app.c").to_str().unwrap(), "-ldl"],
        &app.join("bin/app")
    ));

    let mut run = Command::new(onelf());
    run.args(["run", app.to_str().unwrap(), "--command", "bin/app"])
        .env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("LD_LIBRARY_PATH", &caller);
    isolate(&mut run, &td);
    let out = run.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let report = format!("{}{}", String::from_utf8_lossy(&out.stderr), stdout);
    assert!(out.status.success(), "{report}");
    assert!(
        stdout.contains("hole=absent"),
        "the caller's copy loaded: {report}"
    );
    let line = |key: &str| {
        stdout
            .lines()
            .find_map(|l| l.strip_prefix(key))
            .unwrap_or_else(|| panic!("no {key} in {report}"))
            .to_string()
    };
    let app_lp = line("app_lp=");
    let store = td.join("xdg-cache/onelf/views");
    let view = the_prepared_view(&store);
    assert!(
        app_lp.contains(view.join("lib").to_str().unwrap()) && !app_lp.contains("caller-lib"),
        "the app's path is not the prepared view's own: {app_lp}"
    );
    let child_lp = line("child_lp=");
    assert!(
        !child_lp.contains("caller-lib"),
        "the caller's directory reached a child: {child_lp}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// The assembly summary lines in a build log: the fixed labels the
/// summary renders, in the order the log carries them. No other build
/// output starts a line with these labels.
fn summary_lines(log: &str) -> Vec<&str> {
    const PREFIXES: [&str; 6] = [
        "Source: ",
        "Frameworks requested: ",
        "Rule ",
        "Shared sets: ",
        "Pinned GL build: ",
        "Not inferred: ",
    ];
    log.lines()
        .filter(|l| PREFIXES.iter().any(|p| l.starts_with(p)))
        .collect()
}

/// Write an AppDir whose recipe skips bundling, holding one executable
/// script as the package command.
fn skip_appdir(td: &Path, tag: &str) -> PathBuf {
    let dir = td.join(tag);
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    write(&dir.join("bin/app"), "#!/bin/sh\necho hi\n");
    std::fs::set_permissions(
        dir.join("bin/app"),
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();
    write(
        &dir.join("onelf.toml"),
        "[package]\ncommand = \"bin/app\"\nmtime = 0\n\n[bundle]\nskip = true\n",
    );
    dir
}

/// A skipped assembly is reported as unchecked, with no completeness
/// claim: the summary names the tree as authored and the audit that did
/// not run, then the bounded-inference limit, and nothing else.
#[test]
fn a_skip_build_reports_the_tree_unchecked_without_a_completeness_claim() {
    let td = workdir("skipreport");
    let dir = skip_appdir(&td, "app");

    let out = onelf_build(&dir);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{stderr}");
    assert_eq!(
        summary_lines(&stderr),
        [
            "Source: unchecked; the tree stands as authored, no scan or \
             dependency audit ran, and nothing here claims it complete",
            "Not inferred: computed plugin paths, script subprocesses, \
             application assets, kernel features and external services are \
             not audited",
        ],
        "{stderr}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A host-scan build attributes its source: the summary says the scan
/// came from this machine and that unresolved dependencies stay
/// warnings, never a completeness claim.
#[test]
fn a_host_scan_build_attributes_its_source() {
    let td = workdir("hostscanreport");
    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    if !cc_libm(&td.join("app.c"), &dir.join("bin/app")) {
        let _ = std::fs::remove_dir_all(&td);
        return; // no compiler: documented soft-skip
    }
    write(
        &dir.join("onelf.toml"),
        "[package]\nname = \"hostscan\"\ncommand = \"bin/app\"\nmtime = 0\n",
    );

    let out = onelf_build(&dir);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{stderr}");
    assert_eq!(
        summary_lines(&stderr),
        [
            "Source: host scan; unresolved required dependencies fail the \
             build, host-platform providers are reported",
            "Not inferred: computed plugin paths, script subprocesses, \
             application assets, kernel features and external services are \
             not audited",
        ],
        "{stderr}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A high-level host-scan build is strict: an entrypoint whose required
/// library the scan cannot find fails `onelf build` and `onelf run
/// --bundle`, naming the object, the soname and the entrypoint, and no
/// package is written. The low-level `bundle-libs` over the same tree
/// keeps its warning and succeeds.
#[test]
fn a_host_scan_build_fails_on_a_missing_required_dependency() {
    let td = workdir("hoststrict");
    let libs = td.join("gone");
    std::fs::create_dir_all(&libs).unwrap();
    write(&td.join("dep.c"), "int missingdep_value(void){return 3;}\n");
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libmissingdep.so.1",
            td.join("dep.c").to_str().unwrap(),
        ],
        &libs.join("libmissingdep.so.1"),
    ) {
        let _ = std::fs::remove_dir_all(&td);
        return; // no compiler: documented soft-skip
    }
    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    write(
        &td.join("app.c"),
        "int missingdep_value(void);\nint main(void){return missingdep_value() == 3 ? 0 : 1;}\n",
    );
    assert!(cc_with(
        &[
            td.join("app.c").to_str().unwrap(),
            &format!("-L{}", libs.display()),
            "-l:libmissingdep.so.1",
        ],
        &dir.join("bin/app"),
    ));
    std::fs::remove_dir_all(&libs).unwrap();
    write(
        &dir.join("onelf.toml"),
        "[package]\nname = \"hoststrict\"\ncommand = \"bin/app\"\nmtime = 0\n",
    );

    let out = onelf_build(&dir);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "{stderr}");
    assert!(
        stderr.contains("bin/app needs libmissingdep.so.1"),
        "{stderr}"
    );
    assert!(stderr.contains("entrypoint '"), "{stderr}");
    let packages: Vec<_> = std::fs::read_dir(&dir)
        .unwrap()
        .flatten()
        .filter(|e| e.path().extension().is_some_and(|x| x == "onelf"))
        .collect();
    assert!(packages.is_empty(), "a refused build writes no output");

    let mut run = dev_run(&td, &["--bundle"]);
    run.arg(&dir);
    let out = run.output().expect("spawn onelf run");
    let run_err = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "{run_err}");
    assert!(run_err.contains("libmissingdep.so.1"), "{run_err}");

    let out = run_onelf(&["bundle-libs", dir.to_str().unwrap()], None);
    let low = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{low}");
    assert!(
        low.contains("warning:") && low.contains("libmissingdep.so.1"),
        "{low}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// A recipe exclusion is policy, not a promise that the host supplies
/// the library: the runtime takes only drivers and the libc family from
/// the host, so a high-level build whose entrypoint needs an excluded
/// library stops with the exclusion named instead of shipping an object
/// that cannot load. The low-level `bundle-libs` keeps its warning.
#[test]
fn an_excluded_library_the_app_needs_stops_the_high_level_build() {
    let td = workdir("hostexcluded");
    let libs = td.join("libs");
    std::fs::create_dir_all(&libs).unwrap();
    write(&td.join("dep.c"), "int excluded_value(void){return 3;}\n");
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libexcludeddep.so.1",
            td.join("dep.c").to_str().unwrap(),
        ],
        &libs.join("libexcludeddep.so.1"),
    ) {
        let _ = std::fs::remove_dir_all(&td);
        return; // no compiler: documented soft-skip
    }
    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    write(
        &td.join("app.c"),
        "int excluded_value(void);\nint main(void){return excluded_value() == 3 ? 0 : 1;}\n",
    );
    assert!(cc_with(
        &[
            td.join("app.c").to_str().unwrap(),
            &format!("-L{}", libs.display()),
            "-l:libexcludeddep.so.1",
        ],
        &dir.join("bin/app"),
    ));
    write(
        &dir.join("onelf.toml"),
        &format!(
            "[package]\nname = \"hostexcluded\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [\"{}\"]\nexclude = [\"libexcludeddep\"]\n",
            libs.display()
        ),
    );

    let out = onelf_build(&dir);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "{stderr}");
    assert!(
        stderr.contains("bin/app needs libexcludeddep.so.1, which [bundle] exclude leaves out"),
        "{stderr}"
    );
    assert!(
        !dir.join("hostexcluded.onelf").exists(),
        "a refused build writes no output"
    );

    let out = run_onelf(&["bundle-libs", dir.to_str().unwrap()], None);
    let low = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{low}");
    assert!(low.contains("libexcludeddep.so.1"), "{low}");
    let _ = std::fs::remove_dir_all(&td);
}

/// A sysroot build attributes its selected source: the summary says the
