/// The summary is deterministic: two builds of one fixed fixture, in
/// separate invocations and directories, render identical summary lines.
#[test]
fn the_build_summary_is_deterministic_across_builds() {
    let build = |tag: &str| -> Vec<String> {
        let td = workdir(tag);
        let dir = skip_appdir(&td, "app");
        let out = onelf_build(&dir);
        let stderr = String::from_utf8_lossy(&out.stderr);
        assert!(out.status.success(), "{stderr}");
        summary_lines(&stderr)
            .into_iter()
            .map(str::to_string)
            .collect()
    };
    let a = build("sumdet-a");
    let b = build("sumdet-b");
    assert!(!a.is_empty(), "no summary lines in the build output");
    assert_eq!(a, b, "{a:?} vs {b:?}");
}

/// A recipe environment naming a loader search path is refused in both
/// development forms before anything launches, with the supported
/// alternatives named, while every other recipe setting still applies.
#[test]
fn a_recipe_library_path_is_refused_in_development() {
    let td = workdir("runrefuse");
    let dir = td.join("app");
    write(
        &dir.join("bin/run.sh"),
        "#!/bin/sh\necho var=$ONELF_T_DEVVAR\n",
    );
    use std::os::unix::fs::PermissionsExt;
    std::fs::set_permissions(
        dir.join("bin/run.sh"),
        std::fs::Permissions::from_mode(0o755),
    )
    .unwrap();
    write(
        &dir.join("onelf.toml"),
        "[package]\ncommand = \"bin/run.sh\"\n\n[env]\nLD_LIBRARY_PATH = \"/caller/lib\"\n",
    );

    for bundle in [false, true] {
        let args: &[&str] = if bundle { &["--bundle"] } else { &[] };
        let mut cmd = dev_run(&td, args);
        cmd.arg(&dir);
        let out = cmd.output().expect("spawn onelf run");
        let stderr = String::from_utf8_lossy(&out.stderr);
        assert!(
            !out.status.success(),
            "bundle={bundle}: the launch ran despite the refusal"
        );
        assert!(
            stderr.contains("LD_LIBRARY_PATH"),
            "bundle={bundle}: {stderr}"
        );
        assert!(stderr.contains("resolver"), "bundle={bundle}: {stderr}");
        assert!(
            !String::from_utf8_lossy(&out.stdout).contains("var="),
            "bundle={bundle}: the app launched"
        );
    }

    // A recipe setting that is not a loader search path applies, so the
    // refusal is about the protected names and nothing else.
    write(
        &dir.join("onelf.toml"),
        "[package]\ncommand = \"bin/run.sh\"\n\n[env]\nONELF_T_DEVVAR = \"from-recipe\"\n",
    );
    let mut cmd = dev_run(&td, &[]);
    cmd.arg(&dir);
    let out = cmd.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        out.status.success() && stdout.contains("var=from-recipe"),
        "{}{}",
        stdout,
        String::from_utf8_lossy(&out.stderr)
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// The prepared view a development launch runs from: private to the
/// launch, carrying the evaluated mappings the constructor reads back,
/// reused untouched while nothing that changes it changed, and leaving
/// the AppDir exactly as it stood.
#[test]
fn a_dev_run_launches_from_one_prepared_view() {
    let td = workdir("runview");
    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    write(&dir.join("share/data.txt"), "data\n");
    write(
        &td.join("app.c"),
        r#"#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
int main(int argc, char **argv) {
    char cwd[4096] = {0};
    getcwd(cwd, sizeof cwd);
    printf("mode=%s\n", getenv("ONELF_ACTIVE_MODE") ? getenv("ONELF_ACTIVE_MODE") : "(unset)");
    printf("dir=%s\n", getenv("ONELF_DIR") ? getenv("ONELF_DIR") : "(unset)");
    printf("cwd=%s\n", cwd);
    printf("data=%s\n", getenv("XDG_DATA_DIRS") ? getenv("XDG_DATA_DIRS") : "(unset)");
    for (int i = 1; i < argc; i++) printf("arg%d=%s\n", i, argv[i]);
    return 0;
}
"#,
    );
    assert!(cc_with(
        &[td.join("app.c").to_str().unwrap()],
        &dir.join("bin/app")
    ));
    write(
        &dir.join("onelf.toml"),
        "[package]\ncommand = \"bin/app\"\nworking-dir = \"package\"\n\n\
         [[entrypoint]]\nname = \"main\"\npath = \"bin/app\"\nargs = [\"--from-recipe\"]\ndefault = true\n",
    );
    let store = td.join("xdg-cache/onelf/views");

    let mut cmd = dev_run(&td, &[]);
    cmd.arg(&dir).arg("passed-on");
    let out = cmd.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let report = format!("{}{}", String::from_utf8_lossy(&out.stderr), stdout);
    assert!(out.status.success(), "{report}");
    let line = |key: &str| {
        stdout
            .lines()
            .find_map(|l| l.strip_prefix(key))
            .unwrap_or_else(|| panic!("no {key} in {report}"))
            .to_string()
    };
    assert_eq!(line("mode="), "dev", "{report}");
    let dir_root = dir.canonicalize().unwrap();
    assert_eq!(line("cwd="), line("dir="), "{report}");
    assert_eq!(line("arg1="), "--from-recipe", "{report}");
    assert_eq!(line("arg2="), "passed-on", "{report}");
    assert!(!line("dir=").starts_with(dir_root.to_string_lossy().as_ref()));
    assert!(line("dir=").contains("views/view-"), "{report}");
    let view = std::path::PathBuf::from(line("dir=").to_string());
    assert!(view.starts_with(&store), "{report}");
    let data = line("data=");
    assert!(
        data.contains(&view.join("share").to_string_lossy().to_string()),
        "the evaluated mapping names the view's share: {report}"
    );

    // The evaluated mappings live in the view alone, named for the view,
    // and the AppDir is untouched by the launch.
    let record = view.join(".onelf/runtime-env");
    assert!(record.is_file(), "the view carries no generated input");
    let text = std::fs::read_to_string(&record).unwrap();
    assert!(text.starts_with("ONELF-RUNTIME-ENV 1 "), "{report}");
    assert!(
        text.contains(&view.join("share").to_string_lossy().to_string()),
        "the stored input names the view root: {text}"
    );
    assert!(
        !text.contains(&dir_root.join("share").to_string_lossy().to_string()),
        "the stored input names the AppDir: {text}"
    );
    assert!(!dir_root.join(".onelf/runtime-env").exists());

    // Every staged file is its own inode, so an edit to the AppDir in
    // place can never reach the published view.
    let inode = |p: &std::path::Path| {
        use std::os::unix::fs::MetadataExt;
        let m = std::fs::metadata(p).unwrap();
        (m.dev(), m.ino())
    };
    for rel in ["bin/app", "share/data.txt", "onelf.toml"] {
        assert_ne!(
            inode(&dir_root.join(rel)),
            inode(&view.join(rel)),
            "{rel} is shared with the view"
        );
        assert_eq!(
            std::fs::read(dir_root.join(rel)).unwrap(),
            std::fs::read(view.join(rel)).unwrap()
        );
    }
    let ready = view.join("ready");
    let stamp = |p: &std::path::Path| std::fs::symlink_metadata(p).unwrap().modified().unwrap();

    // The same launch again reuses the view whole: no restage, no
    // reissue of the records.
    let before = (stamp(&ready), stamp(&view.join("config")));
    let mut cmd = dev_run(&td, &[]);
    cmd.arg(&dir).arg("passed-on");
    let out = cmd.output().expect("spawn onelf run");
    assert!(out.status.success(), "{report}");
    assert_eq!(line("cwd="), line("dir="), "{report}");
    assert_eq!(stamp(&ready), before.0, "the iteration rebuilt the view");
    assert_eq!(stamp(&view.join("config")), before.1);

    // A changed tree is another view, and the old one stays.
    write(&dir.join("bin/extra"), "#!/bin/sh\necho x\n");
    use std::os::unix::fs::PermissionsExt;
    std::fs::set_permissions(
        dir.join("bin/extra"),
        std::fs::Permissions::from_mode(0o755),
    )
    .unwrap();
    let mut cmd = dev_run(&td, &[]);
    cmd.arg(&dir).arg("passed-on");
    let out = cmd.output().expect("spawn onelf run");
    assert!(out.status.success());
    let views = std::fs::read_dir(&store)
        .unwrap()
        .filter_map(|e| {
            let p = e.unwrap().path();
            let dir = p.is_dir();
            p.file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| dir && n.starts_with("view-"))
                .then_some(p)
        })
        .count();
    assert_eq!(views, 2, "a changed tree shares the old view");

    let _ = std::fs::remove_dir_all(&td);
}

/// The view a development run launched from stays claimed for as long
/// as the entrypoint runs: the run's lease survives the exec, so a
/// collection while the app is alive leaves the view in place, and the
/// same collection reclaims it once the app has exited.
#[test]
fn a_running_dev_run_keeps_its_view_from_collection() {
    let td = workdir("runlease");
    let dir = td.join("app");
    write(
        &dir.join("bin/app"),
        "#!/bin/sh\n: > \"$1\"\nwhile [ ! -e \"$2\" ]; do sleep 0.05; done\n",
    );
    use std::os::unix::fs::PermissionsExt;
    std::fs::set_permissions(dir.join("bin/app"), std::fs::Permissions::from_mode(0o755)).unwrap();
    write(
        &dir.join("onelf.toml"),
        "[package]\ncommand = \"bin/app\"\n",
    );
    let (started, gate) = (td.join("started"), td.join("gate"));

    let mut cmd = dev_run(&td, &[]);
    cmd.arg(&dir)
        .arg("--")
        .arg(&started)
        .arg(&gate)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null());
    let mut child = cmd.spawn().expect("spawn onelf run");
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
    while !started.exists() {
        if std::time::Instant::now() > deadline || child.try_wait().unwrap().is_some() {
            let _ = child.kill();
            panic!("the development run never started its entrypoint");
        }
        std::thread::sleep(std::time::Duration::from_millis(20));
    }
    let view = the_prepared_view(&td.join("xdg-cache/onelf/views"));

    let report = cache_gc(&td.join("xdg-cache"), &td);
    assert!(
        view.join("ready").exists(),
        "a live run's view was collected: {report}"
    );

    write(&gate, "");
    assert!(child.wait().unwrap().success());
    let report = cache_gc(&td.join("xdg-cache"), &td);
    assert!(!view.exists(), "the idle view was not reclaimed: {report}");
    let _ = std::fs::remove_dir_all(&td);
}

/// The capability limits of a development launch are stated outright:
/// a re-exec that clears the environment starts outside the prepared
/// environment, the recipe's preload list is not opened, and the
/// absolute-path overlays say whether they are in effect.
#[test]
fn a_dev_run_states_its_capability_limits() {
    let td = workdir("runlimits");
    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    write(&dir.join("share/devov/marker"), "from-view\n");
    write(
        &td.join("app.c"),
        r#"#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
int main(void) {
    if (getenv("REEXEC")) {
        char *argv[] = {"app", 0};
        char *envp[] = {"AGAIN=1", 0};
        fflush(stdout);
        execve("/proc/self/exe", argv, envp);
        return 1;
    }
    if (getenv("AGAIN")) {
        printf("again_mode=%s\n", getenv("ONELF_ACTIVE_MODE") ? getenv("ONELF_ACTIVE_MODE") : "(unset)");
        return 0;
    }
    FILE *f = fopen("/usr/share/devov/marker", "r");
    char buf[16] = {0};
    if (f && fgets(buf, sizeof buf, f)) printf("marker=%s", buf);
    else printf("marker=missing\n");
    if (f) fclose(f);
    return 0;
}
"#,
    );
    assert!(cc_with(
        &[td.join("app.c").to_str().unwrap()],
        &dir.join("bin/app")
    ));
    write(
        &dir.join("onelf.toml"),
        &format!(
            "preload = [\"{}\"]\n\n[package]\ncommand = \"bin/app\"\n\n[paths]\n\"/usr/share/devov\" = \"share/devov\"\n",
            dir.join("bin/app").display()
        ),
    );
    let mut plain = dev_run(&td, &[]);
    plain.arg(&dir);
    let out = plain.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    let report = format!("{stdout}{stderr}");
    assert!(out.status.success(), "{report}");
    assert!(
        stderr.contains("preload list is opened by the packaged constructor"),
        "the preload limit is not stated: {report}"
    );
    assert!(
        stderr.contains("absolute paths"),
        "the overlays do not say whether they are in effect: {report}"
    );
    if stdout.contains("marker=from-view") {
        assert!(
            stderr.contains("answer for the absolute paths"),
            "an overlay in effect is not reported: {report}"
        );
    } else {
        assert!(
            stdout.contains("marker=missing"),
            "the marker neither hit nor missed: {report}"
        );
        assert!(
            stderr.contains("not overlaid"),
            "a failed overlay is not reported: {report}"
        );
    }

    let mut reexec = dev_run(&td, &[]);
    reexec.arg(&dir).env("REEXEC", "1");
    let out = reexec.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    let report = format!("{stdout}{stderr}");
    assert!(out.status.success(), "{report}");
    assert!(
        stderr.contains("re-exec that clears the environment is not hooked"),
        "the re-exec limit is not stated: {report}"
    );
    assert!(
        stdout.contains("again_mode=(unset)"),
        "a re-exec that clears the environment stayed inside the prepared environment: {report}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A set a development launch activates reaches the launch's mappings:
/// the set's directories appear where the evaluated mappings put them,
/// in the app's environment and in the stored input alike.
#[test]
fn a_dev_runs_active_set_reaches_the_evaluated_mappings() {
    let td = workdir("runsetmap");
    let Some(set_lib) = set_library(
        &td,
        "toolkit",
        "libtoolkit.so.99fixture",
        "int toolkit_value(void){return 9;}\n",
    ) else {
        return;
    };
    std::fs::create_dir_all(set_lib.join("lib/qt6/plugins")).unwrap();
    write(&td.join("qtplugin.c"), "int qt_plugin(void){return 1;}\n");
    assert!(cc_with(
        &["-shared", "-fPIC", td.join("qtplugin.c").to_str().unwrap(),],
        &set_lib.join("lib/qt6/plugins/libqfake.so")
    ));
    let (hash, set_pkg) = pack_set(&td, "toolkit", "toolkit");

    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    write(
        &td.join("app.c"),
        r#"#include <stdio.h>
#include <stdlib.h>
int main(void) {
    printf("qt=%s\n", getenv("QT_PLUGIN_PATH") ? getenv("QT_PLUGIN_PATH") : "(unset)");
    return 0;
}
"#,
    );
    assert!(cc_with(
        &[td.join("app.c").to_str().unwrap()],
        &dir.join("bin/app")
    ));
    write(
        &dir.join("onelf.toml"),
        &format!(
            "[package]\ncommand = \"bin/app\"\n\n[bundle]\nskip = true\n\n\
             [sysroot.sets.toolkit]\npackages = [\"libtoolkit\"]\nurl = \"file://{}\"\n\
             blake3 = \"{hash}\"\n",
            set_pkg.display()
        ),
    );

    let mut cmd = dev_run(&td, &["--bundle"]);
    cmd.arg(&dir);
    let out = cmd.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    let report = format!("{stdout}{stderr}");
    assert!(out.status.success(), "{report}");
    let qt = stdout
        .lines()
        .find_map(|l| l.strip_prefix("qt="))
        .unwrap_or_else(|| panic!("no qt= in {report}"));
    let onelf_dir_listing =
        std::fs::read_to_string(dir.join(".onelf/sets")).unwrap_or_else(|e| e.to_string());
    assert!(
        qt.ends_with("qt6/plugins"),
        "the active set's plugin directory is not the mapping's value: {report} [.onelf: {onelf_dir_listing}]"
    );
    assert!(
        !qt.contains(&dir.canonicalize().unwrap().to_string_lossy().to_string()),
        "the mapping names the AppDir instead of the set: {report}"
    );

    // The stored input carries the same evaluated value, naming the
    // set root the launch acquired.
    let store = td.join("xdg-cache/onelf/views");
    let view = the_prepared_view(&store);
    let text = std::fs::read_to_string(view.join(".onelf/runtime-env")).unwrap();
    let line = text
        .lines()
        .find(|l| l.starts_with("QT_PLUGIN_PATH="))
        .unwrap_or_else(|| panic!("the stored input has no QT_PLUGIN_PATH: {text}"));
    assert!(
        line.contains("qt6/plugins"),
        "the stored mapping lost the set's directory: {line}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A development launch leaves the caller's original values in the
/// restoration record the host programs the app starts read, whatever
/// the launch resolved for the app itself, and the shared launch
/// variables reach the app exactly as a packed launch sets them.
#[test]
fn a_dev_run_records_the_callers_environment_for_host_children() {
    let td = workdir("runrecord");
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    let caller = td.join("caller-lib");
    std::fs::create_dir_all(&caller).unwrap();
    write(
        &td.join("app.c"),
        r#"#include <stdio.h>
#include <stdlib.h>
int main(void) {
    printf("mode=%s\n", getenv("ONELF_ACTIVE_MODE") ? getenv("ONELF_ACTIVE_MODE") : "(unset)");
    printf("dir=%s\n", getenv("ONELF_DIR") ? getenv("ONELF_DIR") : "(unset)");
    printf("record=%s\n", getenv("ONELF_HOST_ENV") ? getenv("ONELF_HOST_ENV") : "(unset)");
    return 0;
}
"#,
    );
    assert!(cc_with(
        &[td.join("app.c").to_str().unwrap()],
        &app.join("bin/app")
    ));

    let mut run = Command::new(onelf());
    run.args(["run", app.to_str().unwrap(), "--command", "bin/app"])
        .env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("LD_LIBRARY_PATH", &caller);
    isolate(&mut run, &td);
    let out = run.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let report = format!("{}{}", String::from_utf8_lossy(&out.stderr), stdout);
    assert!(out.status.success(), "{report}");
    let line = |key: &str| {
        stdout
            .lines()
            .find_map(|l| l.strip_prefix(key))
            .unwrap_or_else(|| panic!("no {key} in {report}"))
            .to_string()
    };
    assert_eq!(line("mode="), "dev", "{report}");
    let store = td.join("xdg-cache/onelf/views");
    let view = the_prepared_view(&store);
    assert_eq!(line("dir="), view.to_string_lossy(), "{report}");
    let caller_s = caller.to_string_lossy().into_owned();
    let entry = format!("LD_LIBRARY_PATH=*{}:{};", caller_s.len(), caller_s);
    assert!(
        line("record=").contains(&entry),
        "the record lacks the caller's own value: {report}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// Two development launches of one tree with different caller
/// environments build different views: the caller's own values feed the
/// mappings the launch evaluates and the restoration record it stores,
/// so a changed caller environment never reuses a stale view, and an
/// unchanged one reuses the view it built. A packed launch keys on
/// nothing the caller changes, and each launch still answers with its
/// own caller's value.
#[test]
fn distinct_caller_environments_get_distinct_development_views() {
    let td = workdir("parity-views");
    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    std::fs::create_dir_all(dir.join("share/file/misc")).unwrap();
    write(&dir.join("share/file/misc/magic.mgc"), "database\n");
    write(
        &td.join("views.c"),
        r#"#include <stdio.h>
#include <stdlib.h>
int main(void) {
    printf("magic=%s\n", getenv("MAGIC") ? getenv("MAGIC") : "(unset)");
    printf("dir=%s\n", getenv("ONELF_DIR") ? getenv("ONELF_DIR") : "(unset)");
    return 0;
}
"#,
    );
    assert!(cc_with(
        &[td.join("views.c").to_str().unwrap()],
        &dir.join("bin/app")
    ));

    let store = td.join("xdg-cache/onelf/views");
    let view_count = || {
        std::fs::read_dir(&store)
            .unwrap()
            .filter_map(|e| {
                let p = e.unwrap().path();
                let dir = p.is_dir();
                p.file_name()
                    .and_then(|n| n.to_str())
                    .is_some_and(|n| dir && n.starts_with("view-"))
                    .then_some(p)
            })
            .count()
    };
    let launch = |magic: &str, caller_lib: &Path| -> (String, String) {
        let mut cmd = dev_run(&td, &["--command", "bin/app"]);
        cmd.arg(&dir)
            .env("MAGIC", magic)
            .env("LD_LIBRARY_PATH", caller_lib);
        let out = cmd.output().expect("spawn onelf run");
        let stdout = String::from_utf8_lossy(&out.stdout);
        let report = format!("{}{}", String::from_utf8_lossy(&out.stderr), stdout);
        assert!(out.status.success(), "{report}");
        let line = |key: &str| {
            stdout
                .lines()
                .find_map(|l| l.strip_prefix(key))
                .unwrap_or_else(|| panic!("no {key} in {report}"))
                .to_string()
        };
        (line("magic="), line("dir="))
    };

    let lib_a = td.join("caller-a");
    let lib_b = td.join("caller-b");
    std::fs::create_dir_all(&lib_a).unwrap();
    std::fs::create_dir_all(&lib_b).unwrap();

    // The caller's database and library path are the launch's inputs:
    // the app keeps the caller's database, and the launch stages a view.
    let (magic_a, dir_a) = launch("/caller/a.mgc", &lib_a);
    assert_eq!(magic_a, "/caller/a.mgc");
    assert!(dir_a.contains("views/view-"), "{dir_a}");

    // A different caller environment stages a second view and answers
    // with its own values; the first view stays for its caller.
    let (magic_b, dir_b) = launch("/caller/b.mgc", &lib_b);
    assert_eq!(magic_b, "/caller/b.mgc");
    assert_ne!(dir_a, dir_b);
    assert_eq!(view_count(), 2);
    assert!(std::path::Path::new(&dir_a).is_dir());

    // The unchanged caller environment reuses its view whole: the same
    // tree, no restage, no reissue of the records.
    let view_a = std::path::PathBuf::from(&dir_a);
    let stamp = |p: &Path| std::fs::symlink_metadata(p).unwrap().modified().unwrap();
    let before = (stamp(&view_a.join("ready")), stamp(&view_a.join("config")));
    let (magic_again, dir_again) = launch("/caller/a.mgc", &lib_a);
    assert_eq!(magic_again, "/caller/a.mgc");
    assert_eq!(dir_again, dir_a);
    assert_eq!(view_count(), 2);
    assert_eq!(stamp(&view_a.join("ready")), before.0);
    assert_eq!(stamp(&view_a.join("config")), before.1);

    // Packed launches key on nothing the caller changes, and each still
    // answers with its own caller's value.
    let pkg = td.join("packed.onelf");
    let o = Command::new(onelf())
        .args([
            "pack",
            dir.to_str().unwrap(),
            "-o",
            pkg.to_str().unwrap(),
            "--command",
            "bin/app",
            "--mtime",
            "0",
            "--name",
            "viewctl",
        ])
        .output()
        .expect("spawn onelf pack");
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    for magic in ["/caller/a.mgc", "/caller/b.mgc"] {
        let mut cmd = Command::new(&pkg);
        cmd.env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("HOME", td.to_str().unwrap())
            .env("MAGIC", magic);
        isolate(&mut cmd, &td);
        let out = run_package(&mut cmd);
        let stdout = String::from_utf8_lossy(&out.stdout);
        let report = format!("{}{}", String::from_utf8_lossy(&out.stderr), stdout);
        assert!(out.status.success(), "{report}");
        assert!(
            stdout.contains(&format!("magic={magic}")),
            "the packed launch kept the caller's value: {report}"
        );
    }

    let _ = std::fs::remove_dir_all(&td);
}

/// A host shared object by soname, from the usual library directories.
/// The audio fixtures link a soname they cannot call through headers the
/// machine may not ship, so the bundler's rules trigger on the closure
/// while the fixture itself stays portable.
fn host_library(soname: &str) -> Option<PathBuf> {
    [
        "/usr/lib",
        "/usr/lib64",
        "/lib64",
        "/lib",
        "/usr/lib/x86_64-linux-gnu",
        "/lib/x86_64-linux-gnu",
    ]
    .iter()
    .map(|dir| Path::new(dir).join(soname))
    .find(|path| path.is_file())
}

/// The host gst-plugin-scanner at one of the locations the gstreamer
/// rule's own candidates name for an installation prefix, or at the
/// Debian and Ubuntu multiarch location.
fn host_gst_scanner() -> Option<PathBuf> {
    [
        "/usr/libexec/gstreamer-1.0/gst-plugin-scanner",
        "/usr/lib/gstreamer-1.0/gst-plugin-scanner",
        "/usr/lib64/gstreamer-1.0/gst-plugin-scanner",
        "/usr/lib/x86_64-linux-gnu/gstreamer1.0/gstreamer-1.0/gst-plugin-scanner",
    ]
    .iter()
    .map(PathBuf::from)
    .find(|path| path.is_file())
}

/// The host plugin library that answers a GStreamer element, read out of
/// `gst-inspect-1.0`'s report, so the fixture does not hardcode a plugin
/// directory layout.
fn gst_plugin_library(element: &str) -> Option<PathBuf> {
    let out = Command::new("gst-inspect-1.0")
        .arg(element)
        .stderr(std::process::Stdio::null())
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    String::from_utf8_lossy(&out.stdout)
        .lines()
        .find_map(|line| line.strip_prefix("  Filename "))
        .map(|path| PathBuf::from(path.trim()))
        .filter(|path| path.is_file())
}

/// Whether pkg-config finds a development package. The ALSA fixture is
/// the one that calls into its library, so it is the one that needs
/// headers.
fn pkg_config_available(name: &str) -> bool {
    Command::new("pkg-config")
        .args(["--exists", name])
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .is_ok_and(|status| status.success())
}

/// Whether a live PipeWire server answers on this machine's runtime
/// directory. The connection fixture negotiates a real stream state, so
/// it needs the real server, not merely the libraries.
fn pipewire_server_reachable() -> bool {
    Command::new("pw-cli")
        .args(["info", "0"])
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .is_ok_and(|status| status.success())
}

/// The tree-local copies the GStreamer fixture bundles: the soname the
/// rule triggers on must be a real gstreamer at runtime, because the
/// helper copy the registry scanner runs resolves it beside itself.
fn stage_gst_tree(td: &Path, gst: &Path, scanner: &Path, plugins: &[&Path]) -> PathBuf {
    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    std::fs::create_dir_all(dir.join("lib/gstreamer-1.0")).unwrap();
    std::fs::copy(gst, dir.join("lib/libgstreamer-1.0.so.0")).unwrap();
    // The plugin loader matches a plugin by its file name, so the
    // copies keep the names the host installation gave them.
    for plugin in plugins {
        let name = plugin.file_name().unwrap().to_owned();
        std::fs::copy(plugin, dir.join("lib/gstreamer-1.0").join(name)).unwrap();
    }
    std::fs::copy(scanner, dir.join("lib/gstreamer-1.0/gst-plugin-scanner")).unwrap();
    dir
}

/// The application the GStreamer fixture packs: it reports the
/// environment the launch gave it, then runs a real audiotestsrc to
/// filesink pipeline through the host gst-launch tool under that
/// environment and reports what came out of the sink. Linked against the
/// framework soname so the bundle carries plugins and scanner, though
/// the application itself never calls into gstreamer.
const GSTPIPE_SOURCE: &str = r#"#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/wait.h>
#include <unistd.h>

int main(int argc, char **argv) {
    const char *scanner = getenv("GST_PLUGIN_SCANNER");
    const char *scanner10 = getenv("GST_PLUGIN_SCANNER_1_0");
    const char *syspath = getenv("GST_PLUGIN_SYSTEM_PATH_1_0");
    const char *dir = getenv("ONELF_DIR");
    printf("dir=%s\n", dir ? dir : "(unset)");
    printf("scanner=%s\n", scanner ? scanner : "(unset)");
    printf("scanner10=%s\n", scanner10 ? scanner10 : "(unset)");
    printf("syspath=%s\n", syspath ? syspath : "(unset)");
    printf("scanner_ready=%d\n", scanner && access(scanner, X_OK) == 0);
    if (argc < 2) {
        printf("usage=missing\n");
        return 2;
    }
    char cmd[4096];
    snprintf(cmd, sizeof cmd,
             "gst-launch-1.0 audiotestsrc num-buffers=10 ! filesink location=%s",
             argv[1]);
    FILE *p = popen(cmd, "r");
    if (!p) {
        printf("spawn=fail\n");
        return 1;
    }
    int playing = 0;
    int eos = 0;
    char line[512];
    while (fgets(line, sizeof line, p)) {
        if (strstr(line, "Setting pipeline to PLAYING")) playing = 1;
        if (strstr(line, "EOS")) eos = 1;
    }
    int st = pclose(p);
    printf("gst_exit=%d\n", WIFEXITED(st) ? WEXITSTATUS(st) : -1);
    printf("playing=%d\n", playing);
    printf("eos=%d\n", eos);
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        printf("audio_bytes=0\naudio_nonzero=0\n");
        return 0;
    }
    unsigned char buf[4096];
    long bytes = 0;
    long nonzero = 0;
    size_t got;
    while ((got = fread(buf, 1, sizeof buf, f)) > 0) {
        for (size_t i = 0; i < got; i++) {
            bytes++;
            if (buf[i] != 0) nonzero++;
        }
    }
    fclose(f);
    printf("audio_bytes=%ld\n", bytes);
    printf("audio_nonzero=%ld\n", nonzero);
    return 0;
}
"#;

/// A packed package runs a real GStreamer pipeline with the package's
/// own plugin copies and its own registry scanner: the launch names the
/// private scanner for the app, the pipeline reaches PLAYING and EOS and
/// delivers real audio bytes, and the registry the run built names the
/// private plugin paths alone, with no host plugin or scanner path in
/// it. No hardware is involved: the sink is a file.
#[test]
fn a_packed_pipeline_plays_through_the_pack_scanner() {
    if !have("gst-launch-1.0") {
        skip("gstreamer", "no gst-launch-1.0 on PATH");
        return;
    }
    let Some(scanner) = host_gst_scanner() else {
        skip("gstreamer-scanner", "the host ships no gst-plugin-scanner");
        return;
    };
    let Some(coreelements) = gst_plugin_library("filesink") else {
        skip(
            "gstreamer-plugins",
            "gst-inspect-1.0 names no library for filesink",
        );
        return;
    };
    let Some(audiotestsrc) = gst_plugin_library("audiotestsrc") else {
        skip(
            "gstreamer-plugins",
            "gst-inspect-1.0 names no library for audiotestsrc",
        );
        return;
    };
    let td = workdir("gstpipe");
    let Some(gst) = host_library("libgstreamer-1.0.so.0") else {
        skip("gstreamer", "the host ships no libgstreamer-1.0.so.0");
        return;
    };
    let dir = stage_gst_tree(&td, &gst, &scanner, &[&coreelements, &audiotestsrc]);
    write(&td.join("gstpipe.c"), GSTPIPE_SOURCE);
    if !cc_with(
        &[
            td.join("gstpipe.c").to_str().unwrap(),
            &format!("-L{}", gst.parent().unwrap().display()),
            "-l:libgstreamer-1.0.so.0",
            "-Wl,-rpath,$ORIGIN/../lib",
        ],
        &dir.join("bin/app"),
    ) {
        return;
    }
    write(
        &dir.join("onelf.toml"),
        "[package]\nname = \"gstpipe\"\ncommand = \"bin/app\"\nmtime = 0\n",
    );
    let o = Command::new(onelf())
        .arg("build")
        .current_dir(&dir)
        .env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .output()
        .expect("spawn onelf build");
    let log = format!(
        "{}{}",
        String::from_utf8_lossy(&o.stdout),
        String::from_utf8_lossy(&o.stderr)
    );
    assert!(o.status.success(), "{log}");
    // The rule's helper sits staged beside the plugins it needs.
    assert!(
        dir.join("libexec/gstreamer-1.0/gst-plugin-scanner")
            .is_file(),
        "{log}"
    );

    let pkg = dir.join("gstpipe.onelf");
    let audio = td.join("audio.raw");
    let mut cmd = packed_launch(&pkg, &td);
    cmd.arg(audio.to_str().unwrap());
    let out = run_package(&mut cmd);
    let stdout = String::from_utf8_lossy(&out.stdout);
    let report = format!("{stdout}\n{}", String::from_utf8_lossy(&out.stderr));
    assert!(out.status.success(), "{report}");
    let line = |key: &str| {
        stdout
            .lines()
            .find_map(|l| l.strip_prefix(key))
            .unwrap_or_else(|| panic!("no {key} in {report}"))
            .to_string()
    };
    let tree = line("dir=");
    assert!(
        tree.starts_with(td.to_str().unwrap()),
        "the launch tree left the scratch: {report}"
    );
    for key in ["scanner=", "scanner10="] {
        let named = line(key);
        assert!(
            !named.starts_with("/usr"),
            "the host installation's scanner answered: {report}"
        );
        assert!(
            named.starts_with(&tree) && named.ends_with("/lib/gstreamer-1.0/gst-plugin-scanner"),
            "the launch did not name the package's own scanner: {report}"
        );
    }
    let syspath = line("syspath=");
    assert!(
        syspath.starts_with(&tree) && !syspath.contains("/usr/"),
        "the plugin search path is not the package's: {report}"
    );
    assert_eq!(line("scanner_ready="), "1", "{report}");
    assert_eq!(line("gst_exit="), "0", "{report}");
    assert_eq!(line("playing="), "1", "{report}");
    assert_eq!(line("eos="), "1", "{report}");
    let bytes: u64 = line("audio_bytes=").parse().unwrap();
    let nonzero: u64 = line("audio_nonzero=").parse().unwrap();
    assert!(
        bytes >= 10_000,
        "the pipeline delivered only {bytes} bytes: {report}"
    );
    assert!(nonzero > 0, "the delivered audio is silence: {report}");

    // The registry this run built names the private plugins alone: no
    // host plugin directory and no host scanner path appear in it.
    let cache = td.join("xdg-cache/gstreamer-1.0");
    let registry = std::fs::read_dir(&cache)
        .unwrap()
        .flatten()
        .map(|entry| entry.path())
        .find(|path| {
            path.file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| name.starts_with("registry."))
        })
        .unwrap_or_else(|| panic!("no registry cache under {}: {report}", cache.display()));
    let registry = String::from_utf8_lossy(&std::fs::read(&registry).unwrap()).into_owned();
    let private = |name: &str| format!("{tree}/lib/gstreamer-1.0/{name}");
    for plugin in ["libgstcoreelements.so", "libgstaudiotestsrc.so"] {
        assert!(
            registry.contains(&private(plugin)),
            "the registry does not name the private {plugin}: {report}"
        );
    }
    assert!(
        !registry.contains("/usr/lib/gstreamer-1.0"),
        "the registry reached the host plugin directory: {report}"
    );
    assert!(
        !registry.contains("/usr/libexec/gstreamer-1.0"),
        "the registry reached the host scanner location: {report}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// The application the hostile-ALSA fixture packs: it reports the
/// configuration pointers the launch gave it, probes the devices the
/// hostile and user snippets would define, and writes frames to the
/// null device. Linked against libasound, so the bundler carries the
/// configuration and plugin tree the rules require.
const ALSAHOST_SOURCE: &str = r#"#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <alsa/asoundlib.h>

static void probe(const char *key, const char *name) {
    snd_pcm_t *pcm = NULL;
    int err = snd_pcm_open(&pcm, name, SND_PCM_STREAM_PLAYBACK, 0);
    if (err == 0) {
        printf("%s=ok\n", key);
        snd_pcm_close(pcm);
    } else {
        printf("%s=failed:%s\n", key, snd_strerror(err));
    }
}

int main(void) {
    const char *dir = getenv("ONELF_DIR");
    printf("dir=%s\n", dir ? dir : "(unset)");
    printf("cfg_path=%s\n", getenv("ALSA_CONFIG_PATH") ? getenv("ALSA_CONFIG_PATH") : "(unset)");
    printf("cfg_dir=%s\n", getenv("ALSA_CONFIG_DIR") ? getenv("ALSA_CONFIG_DIR") : "(unset)");
    printf("plugin_dir=%s\n", getenv("ALSA_PLUGIN_DIR") ? getenv("ALSA_PLUGIN_DIR") : "(unset)");
    probe("default_open", "default");
    probe("user_device", "user_marker");
    probe("hostile_device", "hostile_host_marker");
    snd_pcm_t *pcm = NULL;
    int err = snd_pcm_open(&pcm, "null", SND_PCM_STREAM_PLAYBACK, 0);
    if (err == 0) {
        printf("null_open=ok\n");
    } else {
        printf("null_open=failed:%s\n", snd_strerror(err));
    }
    if (err == 0) {
        err = snd_pcm_set_params(pcm, SND_PCM_FORMAT_U8, SND_PCM_ACCESS_RW_INTERLEAVED,
                                 1, 8000, 1, 200000);
        printf("null_params=%s\n", err == 0 ? "ok" : snd_strerror(err));
        if (err == 0) {
            unsigned char buf[1024];
            memset(buf, 0x5a, sizeof buf);
            snd_pcm_sframes_t written = snd_pcm_writei(pcm, buf, 1024);
            printf("null_written=%ld\n", (long)written);
            snd_pcm_drain(pcm);
        }
        snd_pcm_close(pcm);
    }
    return 0;
}
"#;

/// Hostile snippets in the user configuration locations cannot take the
/// packed stack down, and a caller's own configuration file outranks
/// them: the launch keeps the caller's ALSA_CONFIG_PATH, the hostile
/// files are never parsed, the private configuration directories are the
/// tree's, and the null device carries real frames. The raw binary over
/// the same hostile home fails its opens first, so the hostility is
/// proven real rather than assumed. No hardware is involved: the null
/// device only.
#[test]
fn hostile_user_alsa_snippets_leave_the_private_stack_working() {
    if !pkg_config_available("alsa") {
        skip(
            "alsa-devel",
            "no alsa headers for the probe (pkg-config alsa)",
        );
        return;
    }
    if host_library("libasound.so.2").is_none() {
        skip("alsa", "the host ships no libasound.so.2");
        return;
    }
    if !Path::new("/usr/share/alsa/alsa.conf").is_file() {
        skip("alsa-config", "the host ships no /usr/share/alsa/alsa.conf");
        return;
    }
    let td = workdir("alsahost");

    // The hostile home: a valid but wrong default that a marker device
    // accompanies, a malformed snippet at the XDG location, and garbage
    // for a pulse client that reads the same home.
    let home = td.join("home");
    write(
        &home.join(".asoundrc"),
        "pcm.!default {\n    type hostile_dead_end\n}\npcm.hostile_host_marker {\n    type null\n}\n",
    );
    write(
        &home.join(".config/alsa/asoundrc"),
        "this is }{ not alsa config\n",
    );
    write(
        &home.join(".config/pulse/client.conf"),
        "garbage {{{ broken\n",
    );
    // The caller's own configuration: a full replacement that defines
    // the working default, the null device and a marker device.
    write(
        &td.join("user-alsa.conf"),
        "pcm.default {\n    type null\n}\npcm.null {\n    type null\n}\npcm.user_marker {\n    type null\n}\n",
    );

    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    write(&td.join("alsahost.c"), ALSAHOST_SOURCE);
    if !cc_with(
        &[td.join("alsahost.c").to_str().unwrap(), "-lasound"],
        &dir.join("bin/app"),
    ) {
        return;
    }
    write(
        &dir.join("onelf.toml"),
        "[package]\nname = \"alsahost\"\ncommand = \"bin/app\"\nmtime = 0\n",
    );
    let o = Command::new(onelf())
        .arg("build")
        .current_dir(&dir)
        .env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .output()
        .expect("spawn onelf build");
    let log = format!(
        "{}{}",
        String::from_utf8_lossy(&o.stdout),
        String::from_utf8_lossy(&o.stderr)
    );
    assert!(o.status.success(), "{log}");
    let pkg = dir.join("alsahost.onelf");
    let line = |stdout: &str, key: &str| {
        stdout
            .lines()
            .find_map(|l| l.strip_prefix(key))
            .unwrap_or_else(|| panic!("no {key} in {stdout}"))
            .to_string()
    };

    // The raw binary over the hostile home: the host's own configuration
    // parses the snippets and collapses, so the opens fail.
    let mut base = Command::new(dir.join("bin/app"));
    base.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", &home)
        .env("XDG_CONFIG_HOME", home.join(".config"));
    let out = base.output().expect("run the raw ALSA probe");
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(out.status.success(), "{stdout}");
    assert!(
        line(&stdout, "default_open=").starts_with("failed"),
        "the hostile home did not break the host configuration: {stdout}"
    );
    assert!(
        line(&stdout, "null_open=").starts_with("failed"),
        "the hostile home left the host configuration usable: {stdout}"
    );

    // Packed over the same hostile home with the caller's configuration:
    // the launch keeps the caller's path, the hostile files are never
    // read, and the stack works on the tree's private directories.
    let mut cmd = packed_launch(&pkg, &td);
    cmd.env("HOME", &home)
        .env("XDG_CONFIG_HOME", home.join(".config"))
        .env("ALSA_CONFIG_PATH", td.join("user-alsa.conf"));
    let out = run_package(&mut cmd);
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    let report = format!("{stdout}\n{stderr}");
    assert!(out.status.success(), "{report}");
    let tree = line(&stdout, "dir=");
    assert_eq!(
        line(&stdout, "cfg_path="),
        td.join("user-alsa.conf").to_str().unwrap(),
        "the launch lost the caller's configuration: {report}"
    );
    let cfg_dir = line(&stdout, "cfg_dir=");
    assert!(
        cfg_dir.starts_with(&tree) && cfg_dir.ends_with("/share/alsa"),
        "the configuration directory is not the package's: {report}"
    );
    let plugin_dir = line(&stdout, "plugin_dir=");
    assert!(
        plugin_dir.starts_with(&tree) && plugin_dir.ends_with("/lib/alsa-lib"),
        "the plugin directory is not the package's: {report}"
    );
    assert!(
        line(&stdout, "hostile_device=").starts_with("failed"),
        "the hostile snippet's device answered: {report}"
    );
    assert_eq!(
        line(&stdout, "user_device="),
        "ok",
        "the caller's configuration did not answer: {report}"
    );
    assert_eq!(
        line(&stdout, "default_open="),
        "ok",
        "the caller's default did not open: {report}"
    );
    assert_eq!(line(&stdout, "null_open="), "ok", "{report}");
    let written: i64 = line(&stdout, "null_written=").parse().unwrap();
    assert!(written > 0, "the null device took no frames: {report}");
    assert!(
        !stderr.contains("asoundrc"),
        "the hostile snippet files were parsed after all: {report}"
    );

    // Packed over a clean home with no caller configuration: the carried
    // configuration is what the launch points at, privately.
    let clean = td.join("cleanhome");
    std::fs::create_dir_all(&clean).unwrap();
    let mut cmd = packed_launch(&pkg, &td);
    cmd.env("HOME", &clean);
    let out = run_package(&mut cmd);
    let stdout = String::from_utf8_lossy(&out.stdout);
    let report = format!("{stdout}\n{}", String::from_utf8_lossy(&out.stderr));
    assert!(out.status.success(), "{report}");
    let tree = line(&stdout, "dir=");
    let cfg_path = line(&stdout, "cfg_path=");
    assert!(
        cfg_path.starts_with(&tree) && cfg_path.contains("/share/alsa/alsa.conf"),
        "the carried configuration is not what the launch named: {report}"
    );
    assert_eq!(line(&stdout, "null_open="), "ok", "{report}");
    let written: i64 = line(&stdout, "null_written=").parse().unwrap();
    assert!(written > 0, "the null device took no frames: {report}");

    let _ = std::fs::remove_dir_all(&td);
}

/// The application the hostile-PipeWire fixture packs: it reports the
/// private SPA pointers the launch gave it, bridges the server socket
/// into its runtime directory, and drives pw-cli to the real server.
/// Linked against the soname so the bundle carries the module trees.
const PWCLIENT_SOURCE: &str = r#"#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/wait.h>
#include <unistd.h>

static void grab_version(char *version, size_t cap, const char *line,
                         const char *needle) {
    const char *q = strstr(line, needle);
    if (!q || version[0]) {
        return;
    }
    q += strlen(needle);
    const char *e = strchr(q, '"');
    if (e && (size_t)(e - q) < cap) {
        memcpy(version, q, (size_t)(e - q));
        version[e - q] = 0;
    }
}

int main(void) {
    printf("dir=%s\n", getenv("ONELF_DIR") ? getenv("ONELF_DIR") : "(unset)");
    printf("spa_dir=%s\n", getenv("SPA_PLUGIN_DIR") ? getenv("SPA_PLUGIN_DIR") : "(unset)");
    printf("module_dir=%s\n", getenv("PIPEWIRE_MODULE_DIR") ? getenv("PIPEWIRE_MODULE_DIR") : "(unset)");
    printf("cfg_prefix=%s\n", getenv("PIPEWIRE_CONFIG_PREFIX") ? getenv("PIPEWIRE_CONFIG_PREFIX") : "(unset)");
    const char *xdg = getenv("XDG_RUNTIME_DIR");
    if (xdg) {
        char target[256];
        char link[512];
        snprintf(target, sizeof target, "/run/user/%u/pipewire-0", (unsigned)getuid());
        snprintf(link, sizeof link, "%s/pipewire-0", xdg);
        (void)unlink(link);
        (void)symlink(target, link);
    }
    fflush(stdout);
    FILE *p = popen("pw-cli info 0", "r");
    if (!p) {
        printf("spawn=fail\n");
        return 1;
    }
    int has_core = 0;
    char version[128] = "";
    char line[512];
    while (fgets(line, sizeof line, p)) {
        if (strstr(line, "Interface:Core")) has_core = 1;
        grab_version(version, sizeof version, line, "version = \"");
        grab_version(version, sizeof version, line, "version: \"");
    }
    int st = pclose(p);
    printf("pwcli_exit=%d\n", WIFEXITED(st) ? WEXITSTATUS(st) : -1);
    printf("core_seen=%d\n", has_core);
    printf("pw_version=%s\n", version[0] ? version : "(absent)");
    return 0;
}
"#;

/// A malformed client configuration in the user's PipeWire directory
/// stops an unpackaged client cold, and a caller's own configuration
/// prefix, preserved through the packed launch, outranks it: the packed
/// client loads its SPA plugins and modules from the tree's private
/// copies, negotiates core information with the live server, and never
/// parses the hostile file. The raw binary over the same hostile home
/// fails to build a context first, so the hostility is proven real.
#[test]
fn hostile_pipewire_config_leaves_the_private_spa_stack_connected() {
    if !pipewire_server_reachable() {
        skip(
            "pipewire-server",
            "no reachable PipeWire server (pw-cli info 0 failed)",
        );
        return;
    }
    let Some(pwlib) = host_library("libpipewire-0.3.so.0") else {
        skip("pipewire", "the host ships no libpipewire-0.3.so.0");
        return;
    };
    let host_conf = Path::new("/usr/share/pipewire/client.conf");
    if !host_conf.is_file() {
        skip(
            "pipewire-config",
            "the host ships no /usr/share/pipewire/client.conf",
        );
        return;
    }
    let td = workdir("pwclient");

    let home = td.join("home");
    for name in ["client.conf", "client-rt.conf", "pipewire.conf"] {
        write(
            &home.join(".config/pipewire").join(name),
            "garbage {{{ broken\n",
        );
    }
    let clean = td.join("clean-conf");
    std::fs::create_dir_all(&clean).unwrap();
    std::fs::copy(host_conf, clean.join("client.conf")).unwrap();

    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    write(&td.join("pwclient.c"), PWCLIENT_SOURCE);
    if !cc_with(
        &[
            td.join("pwclient.c").to_str().unwrap(),
            &format!("-L{}", pwlib.parent().unwrap().display()),
            "-l:libpipewire-0.3.so.0",
        ],
        &dir.join("bin/app"),
    ) {
        return;
    }
    write(
        &dir.join("onelf.toml"),
        "[package]\nname = \"pwclient\"\ncommand = \"bin/app\"\nmtime = 0\n",
    );
    let o = Command::new(onelf())
        .arg("build")
        .current_dir(&dir)
        .env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .output()
        .expect("spawn onelf build");
    let log = format!(
        "{}{}",
        String::from_utf8_lossy(&o.stdout),
        String::from_utf8_lossy(&o.stderr)
    );
    assert!(o.status.success(), "{log}");
    let pkg = dir.join("pwclient.onelf");
    let line = |stdout: &str, key: &str| {
        stdout
            .lines()
            .find_map(|l| l.strip_prefix(key))
            .unwrap_or_else(|| panic!("no {key} in {stdout}"))
            .to_string()
    };

    // The raw binary over the hostile home: pw refuses to build a
    // context from the malformed configuration.
    let mut base = Command::new(dir.join("bin/app"));
    base.env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", &home)
        .env("XDG_CONFIG_HOME", home.join(".config"))
        .env("XDG_RUNTIME_DIR", td.join("xdg-run"))
        .env("XDG_CACHE_HOME", td.join("xdg-cache"));
    let out = base.output().expect("run the raw PipeWire probe");
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(out.status.success(), "{stdout}");
    assert_eq!(
        line(&stdout, "core_seen="),
        "0",
        "the hostile home did not stop the unpackaged client: {stdout}"
    );

    // Packed over the same hostile home with the caller's configuration
    // prefix: the private SPA and module trees serve, the caller's
    // prefix survives the launch, and the server negotiation completes.
    let mut cmd = packed_launch(&pkg, &td);
    cmd.env("HOME", &home)
        .env("XDG_CONFIG_HOME", home.join(".config"))
        .env("PIPEWIRE_CONFIG_PREFIX", &clean);
    let out = run_package(&mut cmd);
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    let report = format!("{stdout}\n{stderr}");
    assert!(out.status.success(), "{report}");
    let tree = line(&stdout, "dir=");
    for key in ["spa_dir=", "module_dir="] {
        let mapped = line(&stdout, key);
        assert!(
            mapped.starts_with(&tree) && !mapped.contains("/usr/"),
            "{key} is not the package's private copy: {report}"
        );
    }
    assert_eq!(
        line(&stdout, "cfg_prefix="),
        clean.to_str().unwrap(),
        "the launch lost the caller's configuration prefix: {report}"
    );
    assert_eq!(line(&stdout, "pwcli_exit="), "0", "{report}");
    assert_eq!(
        line(&stdout, "core_seen="),
        "1",
        "the packed client reached no server core: {report}"
    );
    let version = line(&stdout, "pw_version=");
    assert_ne!(version, "(absent)", "the server named no version: {report}");
    assert!(
        !stderr.contains("error in config"),
        "the hostile configuration was parsed after all: {report}"
    );

    let _ = std::fs::remove_dir_all(&td);
}

/// A project-local descriptor the local-rule fixtures select: the
/// `libvendor.so` soname activates a plugin group collected from the
/// library directory's `vendor-plugins`, mapped at launch as
/// `VENDOR_PLUGIN_DIR`.
const VENDOR_RULE: &str = r#"schema = 1
id = "vendor-framework"

[[triggers]]
soname-prefix = "libvendor.so"

[[resources.plugins]]
id = "plugins"
kind = "directory"
destination = "lib/vendor-plugins"
requirement = "optional"
candidates = [{ base = "library-dir", path = "vendor-plugins" }]

[[runtime.paths]]
id = "plugins"
kind = "directory"
variables = ["VENDOR_PLUGIN_DIR"]
selection = "first"
inheritance = "replace"
candidates = [{ base = "library-root", path = "vendor-plugins" }]
"#;

/// An AppDir whose `bin/app` links `sonames` from the fixture library
/// directory `lib` and prints the framework mappings the local-rule
/// tests observe, and whether the vendor plugin is present in the
/// directory its mapping names. Returns None without a compiler.
fn mapping_probe_app(td: &Path, lib: &Path, sonames: &[&str]) -> Option<PathBuf> {
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    write(
        &td.join("probe-main.c"),
        r#"#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int framework(void);

static void show(const char *name) {
    const char *value = getenv(name);
    printf("%s=%s\n", name, value ? value : "(unset)");
}

int main(void) {
    show("VENDOR_PLUGIN_DIR");
    show("ALSA_PLUGIN_DIR");
    show("ALSA_CONFIG_DIR");
    const char *dir = getenv("VENDOR_PLUGIN_DIR");
    if (dir) {
        char path[4096];
        snprintf(path, sizeof path, "%s/probe.so", dir);
        printf("member=%s\n", access(path, R_OK) == 0 ? "present" : "absent");
    }
    return framework() - 1;
}
"#,
    );
    let mut args: Vec<String> = vec![
        td.join("probe-main.c").to_string_lossy().into_owned(),
        format!("-L{}", lib.display()),
    ];
    args.extend(sonames.iter().map(|s| format!("-l:{s}")));
    let refs: Vec<&str> = args.iter().map(String::as_str).collect();
    cc_with(&refs, &app.join("bin/app")).then_some(app)
}

/// The value one `NAME=value` line of a probe's output reports.
fn probe_line<'a>(stdout: &'a str, name: &str) -> &'a str {
    stdout
        .lines()
        .find_map(|l| l.strip_prefix(&format!("{name}=")))
        .unwrap_or_else(|| panic!("no {name} in {stdout}"))
}

/// A project-local rule named by a recipe-relative `[bundle] rules`
/// path activates on its soname, collects its plugin group into the
/// AppDir, and maps its variable in a development launch and in the
/// packed launch alike. The packed launch runs after the rule file is
/// deleted, so the mapping comes from the carried runtime record alone.
#[test]
fn a_project_local_rule_collects_its_group_and_maps_it_without_its_file() {
    let td = workdir("local-rule");
    let Some(lib) = plugin_tree_sources(
        &td,
        &["libvendor.so.1"],
        &[("vendor-plugins", &["probe.so"])],
    ) else {
        return;
    };
    let Some(app) = mapping_probe_app(&td, &lib, &["libvendor.so.1"]) else {
        return;
    };
    write(&td.join("rules/vendor.toml"), VENDOR_RULE);
    write(
        &app.join("onelf.toml"),
        &format!(
            "[package]\nname = \"vendor\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [\"{}\"]\nrules = [\"../rules/vendor.toml\"]\n",
            lib.display()
        ),
    );

    let out = onelf_build(&app);
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{err}");
    assert!(
        err.contains("Rule vendor-framework activated by libvendor.so.1; groups: plugins"),
        "{err}"
    );
    assert!(app.join("lib/vendor-plugins/probe.so").is_file(), "{err}");
    let pkg = app.join("vendor.onelf");
    let listing = run_onelf(&["list", pkg.to_str().unwrap()], None);
    assert!(
        String::from_utf8_lossy(&listing.stdout).contains(".onelf/runtime-rules"),
        "the local mapping is carried"
    );

    let mut dev = dev_run(&td, &["--bundle"]);
    dev.arg(&app);
    let out = dev.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        out.status.success(),
        "{stdout}{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(
        probe_line(&stdout, "VENDOR_PLUGIN_DIR").ends_with("/lib/vendor-plugins"),
        "{stdout}"
    );
    assert_eq!(probe_line(&stdout, "member"), "present", "{stdout}");

    std::fs::remove_dir_all(td.join("rules")).unwrap();
    let out = run_package(&mut packed_launch(&pkg, &td));
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        out.status.success(),
        "{stdout}{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let mapped = probe_line(&stdout, "VENDOR_PLUGIN_DIR");
    assert!(
        mapped.ends_with("/lib/vendor-plugins") && !mapped.starts_with(app.to_str().unwrap()),
        "the packed tree's group answers: {stdout}"
    );
    assert_eq!(probe_line(&stdout, "member"), "present", "{stdout}");
    assert!(
        probe_line(&stdout, "ALSA_PLUGIN_DIR") == "(unset)",
        "the carried record keeps the built-ins presence based: {stdout}"
    );
}

/// `[bundle] exclude` also leaves out a collected plugin group member
/// whose file name it matches, and records why, while the group's other
/// members still arrive.
#[test]
fn an_excluded_plugin_member_is_left_out_of_its_group() {
    let td = workdir("local-rule-exclude");
    let Some(lib) = plugin_tree_sources(
        &td,
        &["libvendor.so.1"],
        &[("vendor-plugins", &["probe.so", "libunwanted.so"])],
    ) else {
        return;
    };
    let Some(app) = mapping_probe_app(&td, &lib, &["libvendor.so.1"]) else {
        return;
    };
    write(&td.join("rules/vendor.toml"), VENDOR_RULE);
    write(
        &app.join("onelf.toml"),
        &format!(
            "[package]\nname = \"vendor\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [\"{}\"]\nrules = [\"../rules/vendor.toml\"]\n\
             exclude = [\"libunwanted\"]\n",
            lib.display()
        ),
    );

    let out = onelf_build(&app);
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{err}");
    assert!(app.join("lib/vendor-plugins/probe.so").is_file(), "{err}");
    assert!(
        !app.join("lib/vendor-plugins/libunwanted.so").exists(),
        "{err}"
    );
    assert!(err.contains("left out by [bundle] exclude"), "{err}");
    let _ = std::fs::remove_dir_all(&td);
}

/// `disable-rules` keeps a built-in rule from activating: its plugin
/// group and required data stay uncollected and its mapping is absent
/// at launch, while the same fixture without the disable collects and
/// maps both.
#[test]
fn disabling_a_builtin_rule_leaves_its_group_and_mapping_out() {
    for disabled in [false, true] {
        let td = workdir(if disabled { "alsa-off" } else { "alsa-on" });
        let Some(lib) = plugin_tree_sources(
            &td,
            &["libasound.so.2"],
            &[("alsa-lib", &["libasound_module_pcm_probe.so"])],
        ) else {
            return;
        };
        let Some(app) = mapping_probe_app(&td, &lib, &["libasound.so.2"]) else {
            return;
        };
        write(
            &app.join("onelf.toml"),
            &format!(
                "[package]\nname = \"audio\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
                 [bundle]\nsearch-paths = [\"{}\"]\n{}",
                lib.display(),
                if disabled {
                    "disable-rules = [\"alsa\"]\n"
                } else {
                    ""
                }
            ),
        );
        let out = onelf_build(&app);
        let err = String::from_utf8_lossy(&out.stderr);
        assert!(out.status.success(), "{err}");
        let pkg = app.join("audio.onelf");
        let out = run_package(&mut packed_launch(&pkg, &td));
        let stdout = String::from_utf8_lossy(&out.stdout);
        assert!(
            out.status.success(),
            "{stdout}{}",
            String::from_utf8_lossy(&out.stderr)
        );
        let plugin = app.join("lib/alsa-lib/libasound_module_pcm_probe.so");
        let listing = run_onelf(&["list", pkg.to_str().unwrap()], None);
        let carried = String::from_utf8_lossy(&listing.stdout).contains(".onelf/runtime-rules");
        if disabled {
            assert!(!err.contains("Rule alsa activated"), "{err}");
            assert!(
                !plugin.exists() && !app.join("share/alsa").exists(),
                "{err}"
            );
            assert_eq!(
                probe_line(&stdout, "ALSA_PLUGIN_DIR"),
                "(unset)",
                "{stdout}"
            );
            assert_eq!(
                probe_line(&stdout, "ALSA_CONFIG_DIR"),
                "(unset)",
                "{stdout}"
            );
            assert!(carried, "the disable is carried to the launch");
        } else {
            assert!(
                err.contains("Rule alsa activated by libasound.so.2"),
                "{err}"
            );
            assert!(plugin.is_file(), "{err}");
            assert!(
                probe_line(&stdout, "ALSA_PLUGIN_DIR").ends_with("/lib/alsa-lib"),
                "{stdout}"
            );
            assert!(!carried, "the built-ins alone carry no record");
        }
    }
}

/// A local rule shadowing a built-in identity, an unknown disabled
/// identity, an unsupported schema and a truncated descriptor each fail
/// the build naming the file or the offending identity, and leave the
/// AppDir exactly as it stood.
#[test]
fn invalid_local_rules_fail_before_the_appdir_changes() {
    let td = workdir("local-rule-invalid");
    let Some(lib) = plugin_tree_sources(
        &td,
        &["libvendor.so.1"],
        &[("vendor-plugins", &["probe.so"])],
    ) else {
        return;
    };
    let Some(app) = mapping_probe_app(&td, &lib, &["libvendor.so.1"]) else {
        return;
    };
    let cases: [(&str, String, &str, &[&str]); 4] = [
        (
            "shadow.toml",
            VENDOR_RULE.replace("vendor-framework", "alsa"),
            "disable-rules = [\"alsa\"]\n",
            &["shadow.toml", "rule alsa shadows the built-in"],
        ),
        (
            "vendor.toml",
            VENDOR_RULE.to_string(),
            "disable-rules = [\"no-such-rule\"]\n",
            &["disable-rules", "no-such-rule"],
        ),
        (
            "schema.toml",
            VENDOR_RULE.replace("schema = 1", "schema = 7"),
            "",
            &["schema.toml", "unsupported version 7"],
        ),
        (
            "cut.toml",
            VENDOR_RULE[..VENDOR_RULE.len() / 2].to_string(),
            "",
            &["cut.toml", "TOML line"],
        ),
    ];
    for (file, text, extra, needles) in cases {
        write(&td.join("rules").join(file), &text);
        write(
            &app.join("onelf.toml"),
            &format!(
                "[package]\nname = \"vendor\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
                 [bundle]\nsearch-paths = [\"{}\"]\nrules = [\"../rules/{file}\"]\n{extra}",
                lib.display()
            ),
        );
        let before = state_of(&app);
        let out = onelf_build(&app);
        let err = String::from_utf8_lossy(&out.stderr);
        assert!(!out.status.success(), "{file} must fail:\n{err}");
        for needle in needles {
            assert!(err.contains(needle), "{file}: no {needle:?} in:\n{err}");
        }
        assert_eq!(
            state_of(&app),
            before,
            "{file}: the AppDir changed before the refusal"
        );
    }
}

/// Resources prepared from a set pin activate only for the entrypoints
/// selecting that pin: the default entrypoint's launch names the pin's
/// prepared helper ahead of the raw set's copy, which sits at an
/// earlier candidate, while an entrypoint selecting no set sees no
/// mapping at all, packed and in development.
#[test]
fn prepared_resources_activate_only_for_entrypoints_selecting_their_pin() {
    let td = workdir("prepared-selection");
    let Some(set_tree) = set_library(
        &td,
        "toolkit",
        "libgstreamer-1.0.so.9",
        "int gstreamer_value(void){return 42;}\n",
    ) else {
        return;
    };
    std::fs::create_dir_all(set_tree.join("lib/gstreamer-1.0")).unwrap();
    if !cc(
        &registry_scanner_source(&td),
        &set_tree.join("lib/gstreamer-1.0/gst-plugin-scanner"),
    ) {
        return;
    }
    let (hash, set_pkg) = pack_set(&td, "toolkit", "toolkit");

    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    if !cc_with(
        &[
            helper_spawning_app_source(&td).to_str().unwrap(),
            &format!("-L{}", set_tree.join("lib").display()),
            "-l:libgstreamer-1.0.so.9",
            "-Wl,-rpath,$ORIGIN/../lib",
        ],
        &dir.join("bin/app"),
    ) {
        return;
    }
    write(
        &td.join("plain.c"),
        "#include <stdio.h>\n#include <stdlib.h>\nint main(void){const char *s=getenv(\"GST_PLUGIN_SCANNER\");\
         printf(\"scanner=%s\\n\", s ? s : \"(unset)\");return 0;}\n",
    );
    if !cc(&td.join("plain.c"), &dir.join("bin/plain")) {
        return;
    }
    write(
        &dir.join("onelf.toml"),
        &format!(
            "[package]\nname = \"sel\"\ncommand = \"bin/app\"\nmtime = 0\nsets = [\"toolkit\"]\n\n\
             [[entrypoint]]\nname = \"plain\"\npath = \"bin/plain\"\nsets = []\n\n\
             [sysroot.sets.toolkit]\npackages = [\"libgstreamer\"]\nurl = \"file://{}\"\nblake3 = \"{hash}\"\n",
            set_pkg.display()
        ),
    );
    let out = Command::new(onelf())
        .arg("build")
        .current_dir(&dir)
        .env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("HOME", td.to_str().unwrap())
        .env("ONELF_PLATFORM_STORE", td.join("store"))
        .output()
        .expect("spawn onelf build");
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{err}");
    assert!(
        err.contains("Prepared 1 prepared file(s) for set toolkit"),
        "{err}"
    );
    let prepared = format!(
        "/.onelf-prepared/toolkit/{}/libexec/gstreamer-1.0/gst-plugin-scanner",
        hash.to_ascii_lowercase()
    );
    let selecting = |stdout: &str| {
        assert!(
            probe_line(stdout, "scanner").ends_with(&prepared),
            "the pin's prepared copy precedes the raw set's: {stdout}"
        );
        assert_eq!(probe_line(stdout, "helper"), "0", "{stdout}");
        assert_eq!(probe_line(stdout, "registry"), "(absent)", "{stdout}");
    };

    let pkg = dir.join("sel.onelf");
    let out = run_package(&mut packed_launch(&pkg, &td));
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        out.status.success(),
        "{stdout}{}",
        String::from_utf8_lossy(&out.stderr)
    );
    selecting(&stdout);
    let out = run_package(packed_launch(&pkg, &td).env("ONELF_ENTRYPOINT", "plain"));
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(out.status.success(), "{stdout}");
    assert_eq!(probe_line(&stdout, "scanner"), "(unset)", "{stdout}");

    let mut dev = dev_run(&td, &["--bundle"]);
    dev.arg(&dir);
    let out = dev.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        out.status.success(),
        "{stdout}{}",
        String::from_utf8_lossy(&out.stderr)
    );
    selecting(&stdout);
    let mut dev = dev_run(&td, &["--bundle", "--entrypoint", "plain"]);
    dev.arg(&dir);
    let out = dev.output().expect("spawn onelf run");
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        out.status.success(),
        "{stdout}{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert_eq!(probe_line(&stdout, "scanner"), "(unset)", "{stdout}");
}

/// A recipe whose rule declarations leave the runtime behavior the
/// built-ins already give, a discovery-only local rule and a disabled
/// built-in without runtime mappings, packs byte for byte what the
/// minimal recipe packs, and neither carries a runtime rule or
/// selection record. A local runtime mapping is what adds the record.
#[test]
fn rule_declarations_that_change_no_mapping_pack_identically() {
    let discovery_only = &VENDOR_RULE[..VENDOR_RULE.find("[[runtime.paths]]").unwrap()];
    let build = |tag: &str, bundle: &str, rule: Option<&str>| -> Option<(Vec<u8>, String)> {
        let td = workdir(tag);
        let app = td.join("app");
        std::fs::create_dir_all(app.join("bin")).unwrap();
        write(&td.join("main.c"), "int main(void){return 0;}\n");
        if !cc(&td.join("main.c"), &app.join("bin/prog")) {
            return None;
        }
        if let Some(rule) = rule {
            write(&td.join("rules/local.toml"), rule);
        }
        write(
            &app.join("onelf.toml"),
            &format!(
                "[package]\nname = \"same\"\ncommand = \"bin/prog\"\nmtime = 0\n\
                 exclude = [\"onelf.toml\"]\n\n[bundle]\n{bundle}"
            ),
        );
        let out = onelf_build(&app);
        assert!(
            out.status.success(),
            "{tag}: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        let pkg = app.join("same.onelf");
        let listing = run_onelf(&["list", pkg.to_str().unwrap()], None);
        Some((
            std::fs::read(&pkg).unwrap(),
            String::from_utf8_lossy(&listing.stdout).into_owned(),
        ))
    };
    let Some(minimal) = build("rules-min", "", None) else {
        return;
    };
    let Some(quiet) = build(
        "rules-quiet",
        "rules = [\"../rules/local.toml\"]\ndisable-rules = [\"qt5\"]\n",
        Some(discovery_only),
    ) else {
        return;
    };
    for listing in [&minimal.1, &quiet.1] {
        assert!(
            !listing.contains(".onelf/runtime-rules")
                && !listing.contains(".onelf/entrypoint-sets"),
            "{listing}"
        );
    }
    assert!(
        minimal.0 == quiet.0,
        "declarations that change no mapping must not change the package"
    );
    let Some(mapped) = build(
        "rules-mapped",
        "rules = [\"../rules/local.toml\"]\n",
        Some(VENDOR_RULE),
    ) else {
        return;
    };
    assert!(mapped.1.contains(".onelf/runtime-rules"), "{}", mapped.1);
    assert!(minimal.0 != mapped.0);
}

/// A `[bundle] skip` tree runs no discovery, yet its enabled local rule
/// mappings are still validated and carried, and the report claims no
/// audit: the packed launch maps the variable from the tree as authored.
#[test]
fn a_skipped_tree_carries_its_local_mappings_unchecked() {
    let td = workdir("local-rule-skip");
    let app = td.join("app");
    write(
        &app.join("bin/app"),
        "#!/bin/sh\necho \"VENDOR_DATA_DIR=${VENDOR_DATA_DIR:-(unset)}\"\n",
    );
    std::fs::set_permissions(
        app.join("bin/app"),
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();
    write(&app.join("share/vendor/data.txt"), "data\n");
    write(
        &td.join("rules/data.toml"),
        "schema = 1\nid = \"vendor-data\"\n\n[[runtime.paths]]\nid = \"data\"\n\
         kind = \"directory\"\nvariables = [\"VENDOR_DATA_DIR\"]\nselection = \"first\"\n\
         inheritance = \"preserve\"\ncandidates = [{ base = \"package-root\", path = \"share/vendor\" }]\n",
    );
    write(
        &app.join("onelf.toml"),
        "[package]\nname = \"skipped\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
         [bundle]\nskip = true\nrules = [\"../rules/data.toml\"]\n",
    );
    let out = onelf_build(&app);
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{err}");
    assert!(err.contains("Source: unchecked"), "{err}");
    let pkg = app.join("skipped.onelf");
    let listing = run_onelf(&["list", pkg.to_str().unwrap()], None);
    assert!(String::from_utf8_lossy(&listing.stdout).contains(".onelf/runtime-rules"));
    std::fs::remove_dir_all(td.join("rules")).unwrap();
    let out = run_package(&mut packed_launch(&pkg, &td));
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        out.status.success(),
        "{stdout}{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(
        probe_line(&stdout, "VENDOR_DATA_DIR").ends_with("/share/vendor"),
        "{stdout}"
    );
}

/// A host scan reports the directories a library compiles in against the
/// library's own installation prefix, anchors the copy it carries, and
/// rewrites the compiled-in spellings in the tree's binaries to the
/// anchor path. The rewrite erases discovery's input, so a re-run over
/// the same tree infers nothing fresh; the anchor record keeps the
/// redirect: the report names it again, the record stays byte-identical,
/// and nothing is rewritten twice.
#[test]
fn a_rerun_reports_compiled_in_directories_against_the_same_prefix() {
    let td = workdir("infer-rerun");
    let td = td.canonicalize().unwrap();
    let prefix = td.join("fp");
    std::fs::create_dir_all(prefix.join("lib")).unwrap();
    write(&prefix.join("share/demo/a.conf"), "conf\n");
    write(
        &td.join("demo.c"),
        &format!(
            "const char *demo_dir = \"{}\";\nint demo(void){{return 1;}}\n",
            prefix.join("share/demo").display()
        ),
    );
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libdemo.so.1",
            td.join("demo.c").to_str().unwrap(),
        ],
        &prefix.join("lib/libdemo.so.1"),
    ) {
        return;
    }
    write(
        &td.join("main.c"),
        "int demo(void);\nint main(void){return demo()-1;}\n",
    );
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    let lib_dir = format!("-L{}", prefix.join("lib").display());
    if !cc_with(
        &[
            td.join("main.c").to_str().unwrap(),
            &lib_dir,
            "-l:libdemo.so.1",
        ],
        &app.join("bin/app"),
    ) {
        return;
    }
    let run = || -> String {
        let out = Command::new(onelf())
            .args(["bundle-libs", app.to_str().unwrap(), "--target", "bin/app"])
            .env("LD_LIBRARY_PATH", prefix.join("lib"))
            .output()
            .expect("spawn onelf bundle-libs");
        let err = String::from_utf8_lossy(&out.stderr).into_owned();
        assert!(out.status.success(), "{err}");
        err
    };
    let first = run();
    assert!(app.join("lib/libdemo.so.1").is_file());
    assert!(
        first.contains("  - share/demo: ")
            && first.contains("; inferred from ")
            && first.contains(&prefix.join("share/demo").display().to_string()),
        "{first}"
    );
    assert!(
        first.contains("  Redirected inferred directories:")
            && first.contains("    share/demo: anchor a"),
        "{first}"
    );
    assert!(
        first.contains("Rewrote 1 compiled-in paths to anchor paths in 1 binaries"),
        "{first}"
    );
    let record = std::fs::read(app.join(".onelf/anchors")).unwrap();
    assert_eq!(record, b"a\tshare/demo");
    let lib = std::fs::read(app.join("lib/libdemo.so.1")).unwrap();
    assert!(lib.windows(14).any(|w| w == b"/dev/fd/77/a\0\0"));

    let second = run();
    assert!(
        !second.contains("inferred from"),
        "the rewrite erased discovery's input: {second}"
    );
    assert!(
        second.contains("  Redirected inferred directories:")
            && second.contains("    share/demo: anchor a"),
        "the record restores the redirect: {second}"
    );
    assert!(
        !second.contains("compiled-in paths to anchor paths"),
        "the bytes already name the anchor: {second}"
    );
    assert_eq!(
        std::fs::read(app.join(".onelf/anchors")).unwrap(),
        record,
        "the record stays byte-identical"
    );
    let lib = std::fs::read(app.join("lib/libdemo.so.1")).unwrap();
    assert_eq!(
        lib.windows(14).filter(|w| w == b"/dev/fd/77/a\0\0").count(),
        1,
        "no double rewrite"
    );
}

/// A library's compiled-in plugin directory is carried as a plugin
/// directory and named in `.onelf/plugin-dirs`, with its path below the
/// library directory and its compiled-in spelling, so a launch knows
/// which host directories to consider. A rebuild that discovers nothing
/// fresh keeps the record byte-identical.
#[test]
fn a_carried_plugin_directory_is_named_in_the_record() {
    let td = workdir("plugdirs");
    let td = td.canonicalize().unwrap();
    let prefix = td.join("fp");
    std::fs::create_dir_all(prefix.join("lib/demo/nested")).unwrap();
    write(&td.join("plug.c"), "int demo_plugin(void){return 1;}\n");
    if !cc_with(
        &["-shared", "-fPIC", td.join("plug.c").to_str().unwrap()],
        &prefix.join("lib/demo/libdemo-plugin.so"),
    ) {
        return;
    }
    // A module in the nested directory, and the library naming that
    // directory itself: an object naming its own containing directory is
    // a self-reference, not a resource, so the library carries the
    // nested spelling and the nested dir rides the carried parent.
    write(&td.join("nested.c"), "int demo_nested(void){return 2;}\n");
    if !cc_with(
        &["-shared", "-fPIC", td.join("nested.c").to_str().unwrap()],
        &prefix.join("lib/demo/nested/libdemo-nested.so"),
    ) {
        return;
    }
    write(
        &td.join("demo.c"),
        &format!(
            "const char *demo_dir = \"{}\";\nconst char *nested_dir = \"{}\";\nint demo(void){{return 1;}}\n",
            prefix.join("lib/demo").display(),
            prefix.join("lib/demo/nested").display()
        ),
    );
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libdemo.so.1",
            td.join("demo.c").to_str().unwrap(),
        ],
        &prefix.join("lib/libdemo.so.1"),
    ) {
        return;
    }
    write(
        &td.join("main.c"),
        "int demo(void);\nint main(void){return demo()-1;}\n",
    );
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    let lib_dir = format!("-L{}", prefix.join("lib").display());
    if !cc_with(
        &[
            td.join("main.c").to_str().unwrap(),
            &lib_dir,
            "-l:libdemo.so.1",
        ],
        &app.join("bin/app"),
    ) {
        return;
    }
    let run = || -> String {
        let out = Command::new(onelf())
            .args(["bundle-libs", app.to_str().unwrap(), "--target", "bin/app"])
            .env("LD_LIBRARY_PATH", prefix.join("lib"))
            .output()
            .expect("spawn onelf bundle-libs");
        let err = String::from_utf8_lossy(&out.stderr).into_owned();
        assert!(out.status.success(), "{err}");
        err
    };
    let first = run();
    assert!(
        app.join("lib/demo/libdemo-plugin.so").is_file()
            && app.join("lib/demo/nested/libdemo-nested.so").is_file(),
        "the plugin directories' members arrive:\n{first}"
    );
    let record_path = app.join(".onelf/plugin-dirs");
    let want = format!(
        "lib/demo\tdemo\t{}\nlib/demo/nested\tdemo/nested\t{}",
        prefix.join("lib/demo").display(),
        prefix.join("lib/demo/nested").display()
    );
    assert_eq!(
        std::fs::read(&record_path).unwrap(),
        want.as_bytes(),
        "{first}"
    );

    let second = run();
    assert_eq!(
        std::fs::read(&record_path).unwrap(),
        want.as_bytes(),
        "the rebuild holds the directory and the record stays byte-identical:\n{second}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// Minimal ELF bytes of another machine, enough for collection to refuse
/// them for their architecture.
fn foreign_object() -> Vec<u8> {
    let mut v = vec![0u8; 64];
    v[0..4].copy_from_slice(b"\x7fELF");
    v[4] = 2;
    v[5] = 1;
    v[6] = 1;
    v[16..18].copy_from_slice(&3u16.to_le_bytes());
    let machine: u16 = if cfg!(target_arch = "aarch64") {
        62
    } else {
        183
    };
    v[18..20].copy_from_slice(&machine.to_le_bytes());
    v
}

/// A framework nobody described, installed in a scratch prefix. Its
/// library compiles in two plugin directories and two data directories.
/// One plugin directory holds a module that needs a library of the
/// prefix and compiles in a third data directory, a module built for
/// another machine, and the scripts and manifests that go with them, the
/// way Perl's does. The other holds a backend named `*.so.N`. Returns
/// the prefix and an AppDir whose program links the library, or None
/// without a compiler.
fn examplefw_sources(td: &Path) -> Option<(PathBuf, PathBuf)> {
    let prefix = td.join("dist/usr");
    let plugins = prefix.join("lib/examplefw/plugins");
    let backends = prefix.join("lib/examplefw/backends");
    std::fs::create_dir_all(plugins.join("nested")).unwrap();
    std::fs::create_dir_all(&backends).unwrap();
    write(&prefix.join("share/examplefw/conf.d/a.conf"), "conf\n");
    write(&prefix.join("share/examplefw-extra/b.conf"), "extra\n");
    write(&prefix.join("share/probefw/c.conf"), "probe\n");
    write(&plugins.join("Probe.pm"), "package Probe;\n1;\n");
    write(&plugins.join("nested/probe.conf"), "module probe\n");
    write(&plugins.join("run-probe.sh"), "#!/bin/sh\n");
    std::fs::set_permissions(
        plugins.join("run-probe.sh"),
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();
    write_bytes(&plugins.join("foreign.so"), &foreign_object());
    let library = |name: &str, source: &str, out: &Path, extra: &[&str]| -> bool {
        let src = td.join(format!("{name}.c"));
        write(&src, source);
        let mut args = vec!["-shared", "-fPIC", src.to_str().unwrap()];
        args.extend_from_slice(extra);
        cc_with(&args, out)
    };
    let compiled = |dirs: &[&str]| -> String {
        let names: Vec<String> = dirs
            .iter()
            .map(|d| format!("\"{}\"", prefix.join(d).display()))
            .collect();
        format!("const char *dirs[] = {{{}}};\n", names.join(", "))
    };
    let lib_dir = format!("-L{}", prefix.join("lib").display());
    let ok = library(
        "dep",
        "int dep_value(void){return 4;}\n",
        &prefix.join("lib/libdep.so.1"),
        &["-Wl,-soname,libdep.so.1"],
    ) && library(
        "examplefw",
        &format!(
            "{}int framework(void){{return 1;}}\n",
            compiled(&[
                "lib/examplefw/plugins",
                "lib/examplefw/backends",
                "share/examplefw",
                "share/examplefw-extra",
            ])
        ),
        &prefix.join("lib/libexamplefw.so.1"),
        &["-Wl,-soname,libexamplefw.so.1"],
    ) && library(
        "probe",
        &format!(
            "{}int dep_value(void);\nint plugin_probe(void){{return dep_value();}}\n",
            compiled(&["share/probefw"])
        ),
        &plugins.join("nested/probe.so"),
        &[&lib_dir, "-Wl,--no-as-needed", "-l:libdep.so.1"],
    ) && library(
        "backend",
        "int backend_value(void){return 5;}\n",
        &backends.join("backend.so.1"),
        &[],
    );
    if !ok {
        return None;
    }
    write(
        &td.join("main.c"),
        "int framework(void);\nint main(void){return framework()-1;}\n",
    );
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    if !cc_with(
        &[
            td.join("main.c").to_str().unwrap(),
            &lib_dir,
            "-l:libexamplefw.so.1",
        ],
        &app.join("bin/app"),
    ) {
        return None;
    }
    Some((prefix, app))
}

/// The completeness findings an assembly printed.
fn findings_block(stderr: &str) -> Vec<&str> {
    stderr
        .lines()
        .skip_while(|l| !l.starts_with("Completeness findings ("))
        .take_while(|l| l.starts_with("Completeness findings (") || l.starts_with("  - "))
        .collect()
}

/// Build the descriptor-free framework fixture below `td`, returning the
/// AppDir and the build's output, or None without a compiler.
fn build_examplefw(td: &Path) -> Option<(PathBuf, std::process::Output)> {
    let (prefix, app) = examplefw_sources(td)?;
    write(
        &app.join("onelf.toml"),
        &format!(
            "[package]\nname = \"examplefw\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [\"{}\"]\n",
            prefix.join("lib").display()
        ),
    );
    let mut c = Command::new(onelf());
    c.arg("build")
        .current_dir(&app)
        .env("SOURCE_DATE_EPOCH", "1700000000");
    if let Some(pe) = patchelf() {
        c.env("ONELF_PATCHELF", pe);
    }
    let out = c.output().expect("spawn onelf build");
    Some((app, out))
}

/// A framework without a descriptor has its compiled-in directories
/// collected. A plugin directory is carried whole: its compatible module
/// with the library it needs, and the scripts and manifests beside it,
/// while the module built for another machine is omitted with its
/// reason. A backend named `*.so.N` is an object too, the data
/// directories are carried whole and recorded in the generated ledger,
/// and a directory the collected module itself compiles in is found in a
/// later round. Every directory is reported with the library that
/// compiles it in, and building the same inputs again from scratch
/// produces the same package bytes.
#[test]
fn a_descriptor_free_framework_has_its_directories_collected() {
    let base = workdir("examplefw");
    let td = base.canonicalize().unwrap().join("tree");
    let Some((app, out)) = build_examplefw(&td) else {
        return;
    };
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{err}");
    for file in [
        "lib/examplefw/plugins/nested/probe.so",
        "lib/examplefw/plugins/nested/probe.conf",
        "lib/examplefw/plugins/Probe.pm",
        "lib/examplefw/plugins/run-probe.sh",
        "lib/examplefw/backends/backend.so.1",
        "lib/libdep.so.1",
        "share/examplefw/conf.d/a.conf",
        "share/examplefw-extra/b.conf",
        "share/probefw/c.conf",
    ] {
        assert!(app.join(file).is_file(), "{file}: {err}");
    }
    assert!(
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::mode(
            &app.join("lib/examplefw/plugins/run-probe.sh")
                .metadata()
                .unwrap()
                .permissions()
        ) & 0o111
            != 0,
        "the helper script beside the plugins stays executable: {err}"
    );
    assert!(!app.join("lib/examplefw/plugins/foreign.so").exists());
    let ledger = std::fs::read_to_string(app.join(".onelf/generated")).unwrap();
    for file in [
        "share/examplefw/conf.d/a.conf",
        "lib/examplefw/plugins/Probe.pm",
        "lib/examplefw/plugins/run-probe.sh",
        "share/probefw/c.conf",
    ] {
        assert!(ledger.contains(file), "{file} is recorded as generated");
    }
    let findings = findings_block(&err);
    let plugin = findings
        .iter()
        .find(|l| {
            l.contains(
                "lib/examplefw/plugins: selected: plugin directory, 1 object(s) and 3 other file(s)",
            )
        })
        .unwrap_or_else(|| panic!("{findings:#?}"));
    assert!(
        plugin.contains("foreign.so omitted: machine")
            && plugin.contains("compiled in by libexamplefw.so.1"),
        "{plugin}"
    );
    for (dir, by) in [
        (
            "lib/examplefw/backends: selected: plugin directory, 1 object(s)",
            "libexamplefw.so.1",
        ),
        (
            "share/examplefw: selected: data directory",
            "libexamplefw.so.1",
        ),
        (
            "share/examplefw-extra: selected: data directory",
            "libexamplefw.so.1",
        ),
        ("share/probefw: selected: data directory", "probe.so"),
    ] {
        assert!(
            findings
                .iter()
                .any(|l| l.contains(dir) && l.contains(&format!("compiled in by {by}"))),
            "{dir}: {findings:#?}"
        );
    }

    let first = std::fs::read(app.join("examplefw.onelf")).unwrap();
    std::fs::remove_dir_all(&td).unwrap();
    let (app, out) = build_examplefw(&td).expect("the compiler stays available");
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let second = std::fs::read(app.join("examplefw.onelf")).unwrap();
    assert!(
        first == second,
        "a build of the same inputs is byte-identical ({} vs {} bytes)",
        first.len(),
        second.len()
    );
}

/// A sysroot build infers from the sysroot's own objects and carries
/// only what the build admitted: the framework's plugin and data
/// directories come from the sysroot, never from the packer's machine.
#[test]
fn a_sysroot_build_collects_inferred_directories_from_the_sysroot() {
    let td = workdir("examplefw-sysroot");
    let Some(dir) = examplefw_sysroot(&td) else {
        return;
    };
    let archive = td.join("root.tar");
    write(
        &dir.join("onelf.toml"),
        &format!(
            "[package]\nname = \"examplefw\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [sysroot]\npath = \"../sysroot\"\narchive = \"{}\"\n",
            archive.display()
        ),
    );
    let out = onelf_build(&dir);
    let err = String::from_utf8_lossy(&out.stderr);
    eprintln!("DEBUG-SYSROOT-BASELINE\n{err}");
    assert!(out.status.success(), "{err}");
    assert!(
        dir.join("lib/examplefw/plugins/probe.so").is_file(),
        "{err}"
    );
    assert_eq!(
        std::fs::read_to_string(dir.join("share/examplefw/a.conf")).unwrap(),
        "conf\n"
    );
    let plugins = dir.join("lib/examplefw/plugins");
    assert_eq!(
        std::fs::read_link(plugins.join("probe.conf")).unwrap(),
        Path::new("module.conf"),
        "the member link arrives as a link: {err}"
    );
    assert_eq!(
        std::fs::read_to_string(plugins.join("module.conf")).unwrap(),
        "module\n",
        "{err}"
    );
    assert!(
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::mode(
            &plugins
                .join("run-probe.sh")
                .metadata()
                .unwrap()
                .permissions()
        ) & 0o111
            != 0,
        "the member script keeps its executable bit: {err}"
    );
    assert!(
        !plugins.join("abs.conf").exists(),
        "an absolute member link is left out: {err}"
    );
    assert!(
        !plugins.join("listed").exists(),
        "a directory the package lists is not carried whole: {err}"
    );
    let findings = findings_block(&err);
    assert!(
        findings
            .iter()
            .any(|l| l.contains("share/examplefw: selected: data directory")
                && l.contains("sysroot/usr/share/examplefw below the prefix")),
        "the data comes from the sysroot: {findings:#?}"
    );
    assert!(
        findings.iter().any(|l| {
            l.contains("lib/examplefw/plugins: selected: plugin directory, 1 object(s)")
                && l.contains("sysroot/usr/lib/examplefw/plugins below the prefix")
        }),
        "the plugin directory and its members come from the sysroot: {findings:#?}"
    );
}

/// The examplefw sysroot fixture: a rootfs holding the framework, its
/// plugin directory with a member link, a member script and the files a
/// package lists, and a candidate file for a rule, packed as an archive,
/// with the AppDir's skeleton written beside it. Returns the AppDir, or
/// None without a compiler. The caller writes the AppDir's `onelf.toml`
/// and runs the build.
fn examplefw_sysroot(td: &Path) -> Option<PathBuf> {
    let rootfs = td.join("rootfs");
    for d in [
        "usr/bin",
        "usr/lib/examplefw/plugins",
        "usr/share/examplefw",
    ] {
        std::fs::create_dir_all(rootfs.join(d)).unwrap();
    }
    write(&rootfs.join("usr/share/examplefw/a.conf"), "conf\n");
    write(
        &td.join("examplefw.c"),
        "const char *dirs[] = {\"/usr/lib/examplefw/plugins\", \"/usr/share/examplefw\"};\n\
         int framework(void){return 1;}\n",
    );
    write(&td.join("probe.c"), "int plugin_probe(void){return 2;}\n");
    write(
        &td.join("main.c"),
        "int framework(void);\nint main(void){return framework()-1;}\n",
    );
    let lib_dir = format!("-L{}", rootfs.join("usr/lib").display());
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libexamplefw.so.1",
            td.join("examplefw.c").to_str().unwrap(),
        ],
        &rootfs.join("usr/lib/libexamplefw.so.1"),
    ) || !cc_with(
        &["-shared", "-fPIC", td.join("probe.c").to_str().unwrap()],
        &rootfs.join("usr/lib/examplefw/plugins/probe.so"),
    ) || !cc_with(
        &[
            td.join("main.c").to_str().unwrap(),
            &lib_dir,
            "-l:libexamplefw.so.1",
        ],
        &rootfs.join("usr/bin/app"),
    ) {
        return None;
    }
    write(
        &rootfs.join("usr/lib/examplefw/plugins/module.conf"),
        "module\n",
    );
    std::fs::create_dir_all(rootfs.join("usr/lib/examplefw/plugins/listed")).unwrap();
    write(
        &rootfs.join("usr/lib/examplefw/plugins/listed/inside.conf"),
        "inside\n",
    );
    write(
        &rootfs.join("usr/lib/examplefw/plugins/run-probe.sh"),
        "#!/bin/sh\n",
    );
    std::fs::set_permissions(
        rootfs.join("usr/lib/examplefw/plugins/run-probe.sh"),
        <std::fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o755),
    )
    .unwrap();
    std::os::unix::fs::symlink(
        "module.conf",
        rootfs.join("usr/lib/examplefw/plugins/probe.conf"),
    )
    .unwrap();
    std::os::unix::fs::symlink(
        "/etc/hosts",
        rootfs.join("usr/lib/examplefw/plugins/abs.conf"),
    )
    .unwrap();
    let (Some(host_libc), Some(host_ld)) = (
        ldd_path(&rootfs.join("usr/bin/app"), "libc.so.6"),
        ldd_path(&rootfs.join("usr/bin/app"), "ld-linux"),
    ) else {
        return None;
    };
    std::fs::copy(&host_libc, rootfs.join("usr/lib/libc.so.6")).unwrap();
    std::fs::copy(&host_ld, rootfs.join("usr/lib/ld-linux-x86-64.so.2")).unwrap();
    write_pacman_entry(
        &rootfs,
        "glibc",
        "2.99-1",
        &[],
        &[],
        &["usr/lib/libc.so.6", "usr/lib/ld-linux-x86-64.so.2"],
    );
    write_pacman_entry(
        &rootfs,
        "examplefw",
        "1.0-1",
        &["glibc"],
        &[],
        &[
            "usr/lib/libexamplefw.so.1",
            "usr/lib/examplefw/plugins/probe.so",
            "usr/lib/examplefw/plugins/module.conf",
            "usr/lib/examplefw/plugins/probe.conf",
            "usr/lib/examplefw/plugins/run-probe.sh",
            "usr/lib/examplefw/plugins/abs.conf",
            "usr/lib/examplefw/plugins/listed",
            "usr/share/examplefw/a.conf",
        ],
    );
    write_pacman_entry(
        &rootfs,
        "app",
        "1.0-1",
        &["glibc", "examplefw"],
        &[],
        &["usr/bin/app"],
    );
    let archive = td.join("root.tar");
    let st = Command::new("tar")
        .args(["--create", "--file"])
        .arg(&archive)
        .args(["--sort=name", "--owner=0", "--group=0", "-C"])
        .arg(&rootfs)
        .arg(".")
        .status()
        .expect("spawn tar");
    assert!(st.success());
    let dir = td.join("app");
    std::fs::create_dir_all(dir.join("bin")).unwrap();
    Some(dir)
}

/// A descriptor that declares a directory inference also finds keeps
/// its members allowlist: only the listed member is collected, and
/// inference does not collect the directory a second time.
#[test]
fn a_descriptors_members_allowlist_limits_an_inferred_directory() {
    let td = workdir("examplefw-rule");
    let td = td.canonicalize().unwrap();
    let Some((prefix, app)) = examplefw_sources(&td) else {
        return;
    };
    write(&td.join("other.c"), "int other_probe(void){return 3;}\n");
    if !cc_with(
        &["-shared", "-fPIC", td.join("other.c").to_str().unwrap()],
        &prefix.join("lib/examplefw/plugins/other.so"),
    ) {
        return;
    }
    write(
        &td.join("rules/examplefw.toml"),
        "schema = 1\nid = \"examplefw\"\n\n[[triggers]]\nsoname-prefix = \"libexamplefw.so\"\n\n\
         [[resources.plugins]]\nid = \"plugins\"\nkind = \"directory\"\n\
         destination = \"lib/examplefw/plugins\"\nrequirement = \"optional\"\n\
         candidates = [{ base = \"library-dir\", path = \"examplefw/plugins\" }]\n\
         members = [\"other.so\"]\n",
    );
    write(
        &app.join("onelf.toml"),
        &format!(
            "[package]\nname = \"examplefw\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [\"{}\"]\nrules = [\"../rules/examplefw.toml\"]\n",
            prefix.join("lib").display()
        ),
    );
    let out = onelf_build(&app);
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{err}");
    assert!(
        app.join("lib/examplefw/plugins/other.so").is_file(),
        "{err}"
    );
    assert!(
        !app.join("lib/examplefw/plugins/nested/probe.so").exists(),
        "only the listed member is collected: {err}"
    );
    let findings = findings_block(&err);
    assert!(
        !findings
            .iter()
            .any(|l| l.contains("lib/examplefw/plugins") && l.contains("inferred from")),
        "{findings:#?}"
    );
    assert!(
        findings
            .iter()
            .any(|l| l.contains("share/examplefw: selected: data directory")),
        "the undescribed data directory is still inferred: {findings:#?}"
    );
}

/// A descriptor's planned write inside a directory inference collects
/// stands: the inferred carry is undone whole and omitted naming the
/// clash, so the descriptor's bytes are what the tree holds.
#[test]
fn an_inferred_dir_omits_itself_rather_than_replace_a_descriptors_write() {
    let td = workdir("infer-clash-inner");
    let td = td.canonicalize().unwrap();
    write(&td.join("fp/share/fw/sub/config"), "host\n");
    write(&td.join("fp/share/fw/top.conf"), "host top\n");
    write(&td.join("fp/opt/rulefw/config"), "authored\n");
    let Some((app, lib_dirs)) = inferred_dirs_app(&td, &[("fp", "libfw.so.1", &["share/fw"])])
    else {
        return;
    };
    let paths: Vec<String> = lib_dirs
        .iter()
        .map(|d| format!("\"{}\"", d.display()))
        .collect();
    write(
        &td.join("rules/fw.toml"),
        "schema = 1\nid = \"rulefw\"\n\n[[triggers]]\nsoname-prefix = \"libfw.so\"\n\n\
         [[resources.data]]\nid = \"config\"\nkind = \"file\"\n\
         destination = \"share/fw/sub/config\"\nrequirement = \"optional\"\n\
         candidates = [{ base = \"installation-prefix\", path = \"opt/rulefw/config\" }]\n",
    );
    write(
        &app.join("onelf.toml"),
        &format!(
            "[package]\nname = \"inferred\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [{}]\nrules = [\"../rules/fw.toml\"]\n",
            paths.join(", ")
        ),
    );
    let out = onelf_build(&app);
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{err}");
    assert_eq!(
        std::fs::read_to_string(app.join("share/fw/sub/config")).unwrap(),
        "authored\n",
        "the descriptor's write stands: {err}"
    );
    assert!(
        !app.join("share/fw/top.conf").exists(),
        "the inferred directory is omitted whole: {err}"
    );
    let findings = findings_block(&err);
    assert!(
        findings.iter().any(|l| {
            l.contains("share/fw: optional omission")
                && l.contains("collides with the write planned at share/fw/sub/config")
        }),
        "{findings:#?}"
    );
}

/// A link beside an inferred directory's other members is judged like
/// the carry it belongs to: where a descriptor's write is planned
/// already, the link is a clash and not an alias for the descriptor's
/// file, so the inferred directory is undone and omitted whole and the
/// descriptor's bytes stand.
#[test]
fn an_inferred_link_yields_to_a_descriptors_write() {
    let td = workdir("infer-clash-link");
    let td = td.canonicalize().unwrap();
    write(&td.join("fp/share/fw/top.conf"), "host top\n");
    std::os::unix::fs::symlink("top.conf", td.join("fp/share/fw/link.conf")).unwrap();
    write(&td.join("fp/opt/rulefw/link.conf"), "authored\n");
    let Some((app, lib_dirs)) = inferred_dirs_app(&td, &[("fp", "libfw.so.1", &["share/fw"])])
    else {
        return;
    };
    let paths: Vec<String> = lib_dirs
        .iter()
        .map(|d| format!("\"{}\"", d.display()))
        .collect();
    write(
        &td.join("rules/fw.toml"),
        "schema = 1\nid = \"rulefw\"\n\n[[triggers]]\nsoname-prefix = \"libfw.so\"\n\n\
         [[resources.data]]\nid = \"config\"\nkind = \"file\"\n\
         destination = \"share/fw/link.conf\"\nrequirement = \"optional\"\n\
         candidates = [{ base = \"installation-prefix\", path = \"opt/rulefw/link.conf\" }]\n",
    );
    write(
        &app.join("onelf.toml"),
        &format!(
            "[package]\nname = \"inferred\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [{}]\nrules = [\"../rules/fw.toml\"]\n",
            paths.join(", ")
        ),
    );
    let out = onelf_build(&app);
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{err}");
    assert_eq!(
        std::fs::read_to_string(app.join("share/fw/link.conf")).unwrap(),
        "authored\n",
        "the descriptor's bytes stand where the link wanted to be: {err}"
    );
    assert!(
        !app.join("share/fw/top.conf").exists(),
        "the inferred directory is omitted whole: {err}"
    );
    let findings = findings_block(&err);
    assert!(
        findings.iter().any(|l| {
            l.contains("share/fw: optional omission")
                && l.contains("collides with the write planned at share/fw/link.conf")
        }),
        "{findings:#?}"
    );
}

/// An anchored inferred directory rewrites the library's compiled-in
/// path to the anchor path in the bundled copy, NUL-padded to the
/// original length, writes the anchor record beside the package
/// metadata, and records both in the generated ledger.
#[test]
fn an_anchored_directory_rewrites_the_compiled_in_path_to_the_anchor() {
    let td = workdir("infer-anchor-rewrite");
    let td = td.canonicalize().unwrap();
    write(&td.join("fp/share/fw/top.conf"), "host top\n");
    let Some((app, lib_dirs)) = inferred_dirs_app(&td, &[("fp", "libfw.so.1", &["share/fw"])])
    else {
        return;
    };
    let paths: Vec<String> = lib_dirs
        .iter()
        .map(|d| format!("\"{}\"", d.display()))
        .collect();
    write(
        &app.join("onelf.toml"),
        &format!(
            "[package]\nname = \"inferred\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [{}]\n",
            paths.join(", ")
        ),
    );
    let out = onelf_build(&app);
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{err}");
    let compiled = td.join("fp/share/fw");
    let compiled = compiled.to_str().unwrap();
    let lib = std::fs::read(app.join("lib/libfw.so.1")).unwrap();
    assert!(
        lib.windows(14).any(|w| w == b"/dev/fd/77/a\0\0"),
        "the compiled-in path becomes the anchor path: {err}"
    );
    assert!(
        !lib.windows(compiled.len())
            .any(|w| w == compiled.as_bytes()),
        "the original spelling is gone from the copy: {err}"
    );
    let record = std::fs::read(app.join(".onelf/anchors")).unwrap();
    assert_eq!(record, b"a\tshare/fw", "{err}");
    let ledger = std::fs::read_to_string(app.join(".onelf/generated")).unwrap();
    assert!(ledger.contains(".onelf/anchors"), "{ledger}");
    assert!(
        err.contains("Redirected inferred directories:") && err.contains("share/fw: anchor a"),
        "{err}"
    );
    assert!(
        err.contains("Rewrote 1 compiled-in paths to anchor paths in 1 binaries"),
        "{err}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// An incremental rerun that bundles another library naming the already
/// anchored directory rewrites that library's bytes to the persisted
/// anchor too: the tree holds the directory, so the carry is held, and
/// only the record's anchor reaches the fresh spelling.
#[test]
fn an_incremental_rerun_rewrites_a_new_library_to_the_persisted_anchor() {
    let td = workdir("infer-anchor-incremental");
    let td = td.canonicalize().unwrap();
    let prefix = td.join("fp");
    std::fs::create_dir_all(prefix.join("lib")).unwrap();
    write(&prefix.join("share/demo/a.conf"), "conf\n");
    write(
        &td.join("demo.c"),
        &format!(
            "const char *demo_dir = \"{}\";\nint demo(void){{return 1;}}\n",
            prefix.join("share/demo").display()
        ),
    );
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libdemo.so.1",
            td.join("demo.c").to_str().unwrap(),
        ],
        &prefix.join("lib/libdemo.so.1"),
    ) {
        return;
    }
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    let lib_dir = format!("-L{}", prefix.join("lib").display());
    write(
        &td.join("main.c"),
        "int demo(void);\nint main(void){return demo()-1;}\n",
    );
    assert!(cc_with(
        &[
            td.join("main.c").to_str().unwrap(),
            &lib_dir,
            "-l:libdemo.so.1",
        ],
        &app.join("bin/app"),
    ));
    write(
        &app.join("onelf.toml"),
        &format!(
            "[package]\nname = \"inferred\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [\"{}\"]\n",
            prefix.join("lib").display()
        ),
    );
    let first = onelf_build(&app);
    let err = String::from_utf8_lossy(&first.stderr);
    assert!(first.status.success(), "{err}");
    let record = std::fs::read(app.join(".onelf/anchors")).unwrap();
    assert_eq!(record, b"a\tshare/demo", "{err}");

    // The second library names the same directory, and the app is
    // relinked to need it. The tree already holds the directory, so the
    // carry is held, and the record's anchor must still reach the new
    // library's bytes.
    write(
        &td.join("more.c"),
        &format!(
            "const char *more_dir = \"{}\";\nint more(void){{return 2;}}\n",
            prefix.join("share/demo").display()
        ),
    );
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libmore.so.1",
            td.join("more.c").to_str().unwrap(),
        ],
        &prefix.join("lib/libmore.so.1"),
    ) {
        return;
    }
    write(
        &td.join("main2.c"),
        "int demo(void);int more(void);\nint main(void){return demo()+more()-3;}\n",
    );
    assert!(cc_with(
        &[
            td.join("main2.c").to_str().unwrap(),
            &lib_dir,
            "-l:libdemo.so.1",
            "-l:libmore.so.1",
        ],
        &app.join("bin/app"),
    ));
    let second = onelf_build(&app);
    let err = String::from_utf8_lossy(&second.stderr);
    assert!(second.status.success(), "{err}");
    let more = std::fs::read(app.join("lib/libmore.so.1")).unwrap();
    assert!(
        more.windows(14).any(|w| w == b"/dev/fd/77/a\0\0"),
        "the new library's spelling is rewritten to the record's anchor: {err}"
    );
    assert!(
        err.contains("Rewrote 1 compiled-in paths to anchor paths in 1 binaries"),
        "{err}"
    );
    assert!(err.contains("share/demo: anchor a"), "{err}");
    assert_eq!(
        std::fs::read(app.join(".onelf/anchors")).unwrap(),
        record,
        "the record stays byte-identical: {err}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// An incremental rerun whose new library names a held carried
/// directory and an anchored directory inside it rewrites the new
/// library's bytes for the anchored child too: the child rides the
/// held parent, so it has no carry entry of its own, and only the
/// record's anchor reaches its spellings. The parent names no anchor,
/// so its own spelling stays the host path.
#[test]
fn an_incremental_rerun_rewrites_a_riding_child_to_its_persisted_anchor() {
    let td = workdir("infer-anchor-riding");
    let td = td.canonicalize().unwrap();
    let prefix = td.join("fp");
    std::fs::create_dir_all(prefix.join("lib")).unwrap();
    write(&prefix.join("share/fw/sub/b.conf"), "conf\n");
    write(
        &td.join("demo.c"),
        &format!(
            "const char *demo_dir = \"{}\";\nint demo(void){{return 1;}}\n",
            prefix.join("share/fw/sub").display()
        ),
    );
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libdemo.so.1",
            td.join("demo.c").to_str().unwrap(),
        ],
        &prefix.join("lib/libdemo.so.1"),
    ) {
        return;
    }
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    let lib_dir = format!("-L{}", prefix.join("lib").display());
    write(
        &td.join("main.c"),
        "int demo(void);\nint main(void){return demo()-1;}\n",
    );
    assert!(cc_with(
        &[
            td.join("main.c").to_str().unwrap(),
            &lib_dir,
            "-l:libdemo.so.1",
        ],
        &app.join("bin/app"),
    ));
    write(
        &app.join("onelf.toml"),
        &format!(
            "[package]\nname = \"inferred\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [\"{}\"]\n",
            prefix.join("lib").display()
        ),
    );
    let first = onelf_build(&app);
    let err = String::from_utf8_lossy(&first.stderr);
    assert!(first.status.success(), "{err}");
    let record = std::fs::read(app.join(".onelf/anchors")).unwrap();
    assert_eq!(record, b"a\tshare/fw/sub", "{err}");

    // The second library names both the parent and the anchored child
    // inside it, and the app is relinked to need it. The tree holds
    // both directories, so both carries are held, and the child rides
    // the held parent without a carry entry of its own.
    write(
        &td.join("more.c"),
        &format!(
            "const char *fw_dir = \"{}\";\nconst char *sub_dir = \"{}\";\n\
             int more(void){{return 2;}}\n",
            prefix.join("share/fw").display(),
            prefix.join("share/fw/sub").display()
        ),
    );
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libmore.so.1",
            td.join("more.c").to_str().unwrap(),
        ],
        &prefix.join("lib/libmore.so.1"),
    ) {
        return;
    }
    write(
        &td.join("main2.c"),
        "int demo(void);int more(void);\nint main(void){return demo()+more()-3;}\n",
    );
    assert!(cc_with(
        &[
            td.join("main2.c").to_str().unwrap(),
            &lib_dir,
            "-l:libdemo.so.1",
            "-l:libmore.so.1",
        ],
        &app.join("bin/app"),
    ));
    let second = onelf_build(&app);
    let err = String::from_utf8_lossy(&second.stderr);
    assert!(second.status.success(), "{err}");
    let more = std::fs::read(app.join("lib/libmore.so.1")).unwrap();
    assert!(
        more.windows(14).any(|w| w == b"/dev/fd/77/a\0\0"),
        "the riding child's spelling is rewritten to the record's anchor: {err}"
    );
    let parent = format!("{}\0", prefix.join("share/fw").display());
    assert!(
        more.windows(parent.len()).any(|w| w == parent.as_bytes()),
        "the parent names no anchor, so its whole spelling stays: {err}"
    );
    let child = format!("{}\0", prefix.join("share/fw/sub").display());
    assert!(
        !more.windows(child.len()).any(|w| w == child.as_bytes()),
        "the riding child's raw spelling is gone: {err}"
    );
    assert!(
        err.contains("Rewrote 1 compiled-in paths to anchor paths in 1 binaries"),
        "{err}"
    );
    assert!(err.contains("share/fw/sub: anchor a"), "{err}");
    assert_eq!(
        std::fs::read(app.join(".onelf/anchors")).unwrap(),
        record,
        "the record stays byte-identical: {err}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// An incremental rerun whose new library names a held carried
/// An incremental rerun whose new library names a carried directory's
/// parent from its own prefix and an overlapping child from another
/// prefix leaves the other prefix's child alone: collection omits it,
/// because its source is not the carried child's, and the rewrite's
/// own source test mirrors that omission. The carried child's bytes
/// already name the record's anchor, so the rerun rewrites nothing and
/// the record stays byte-identical.
#[test]
fn an_overlapping_child_from_another_prefix_stays_unrewritten() {
    let td = workdir("infer-anchor-overlap");
    let td = td.canonicalize().unwrap();
    let prefix_a = td.join("fa");
    let prefix_b = td.join("fb");
    std::fs::create_dir_all(prefix_a.join("lib")).unwrap();
    std::fs::create_dir_all(prefix_b.join("lib")).unwrap();
    write(&prefix_a.join("share/fw/sub/b.conf"), "conf\n");
    write(&prefix_b.join("share/fw/sub/other.conf"), "other\n");
    write(
        &td.join("demo.c"),
        &format!(
            "const char *demo_dir = \"{}\";\nint demo(void){{return 1;}}\n",
            prefix_a.join("share/fw/sub").display()
        ),
    );
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libdemo.so.1",
            td.join("demo.c").to_str().unwrap(),
        ],
        &prefix_a.join("lib/libdemo.so.1"),
    ) {
        return;
    }
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    write(
        &td.join("main.c"),
        "int demo(void);\nint main(void){return demo()-1;}\n",
    );
    assert!(cc_with(
        &[
            td.join("main.c").to_str().unwrap(),
            &format!("-L{}", prefix_a.join("lib").display()),
            "-l:libdemo.so.1",
        ],
        &app.join("bin/app"),
    ));
    write(
        &app.join("onelf.toml"),
        &format!(
            "[package]\nname = \"inferred\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [\"{}\", \"{}\"]\n",
            prefix_a.join("lib").display(),
            prefix_b.join("lib").display()
        ),
    );
    let first = onelf_build(&app);
    let err = String::from_utf8_lossy(&first.stderr);
    assert!(first.status.success(), "{err}");
    let record = std::fs::read(app.join(".onelf/anchors")).unwrap();
    assert_eq!(record, b"a\tshare/fw/sub", "{err}");

    // The second library names the carried directory's parent from
    // prefix A, which its own prefix never claims, and the child of
    // prefix B, whose source is not the carried child's.
    write(
        &td.join("more.c"),
        &format!(
            "const char *fw_dir = \"{}\";\nconst char *other_dir = \"{}\";\n\
             int more(void){{return 2;}}\n",
            prefix_a.join("share/fw").display(),
            prefix_b.join("share/fw/sub").display()
        ),
    );
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libmore.so.1",
            td.join("more.c").to_str().unwrap(),
        ],
        &prefix_b.join("lib/libmore.so.1"),
    ) {
        return;
    }
    write(
        &td.join("main2.c"),
        "int demo(void);int more(void);\nint main(void){return demo()+more()-3;}\n",
    );
    assert!(cc_with(
        &[
            td.join("main2.c").to_str().unwrap(),
            &format!("-L{}", prefix_a.join("lib").display()),
            &format!("-L{}", prefix_b.join("lib").display()),
            "-l:libdemo.so.1",
            "-l:libmore.so.1",
        ],
        &app.join("bin/app"),
    ));
    let second = onelf_build(&app);
    let err = String::from_utf8_lossy(&second.stderr);
    assert!(second.status.success(), "{err}");
    let more = std::fs::read(app.join("lib/libmore.so.1")).unwrap();
    let other = format!("{}\0", prefix_b.join("share/fw/sub").display());
    assert!(
        more.windows(other.len()).any(|w| w == other.as_bytes()),
        "the overlapping child is omitted whole, its bytes stay: {err}"
    );
    assert!(
        !more.windows(14).any(|w| w == b"/dev/fd/77/a\0\0"),
        "no anchor reaches the omitted child: {err}"
    );
    let demo = std::fs::read(app.join("lib/libdemo.so.1")).unwrap();
    assert!(
        demo.windows(14).any(|w| w == b"/dev/fd/77/a\0\0"),
        "the tree's carried copy keeps the record's anchor: {err}"
    );
    assert!(
        !err.contains("compiled-in paths"),
        "the recorded bytes already are the anchor, so the rerun rewrites nothing: {err}"
    );
    assert!(err.contains("share/fw/sub: anchor a"), "{err}");
    assert_eq!(
        std::fs::read(app.join(".onelf/anchors")).unwrap(),
        record,
        "the record stays byte-identical: {err}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// A build that fails after the rewrite still leaves the anchor record:
/// the rewritten bytes mean nothing without it, and the rerun that
/// fixes the failure carries the same anchor and record again.
#[test]
fn a_failed_build_leaves_the_record_its_rerun_needs() {
    let td = workdir("infer-anchor-failed");
    let td = td.canonicalize().unwrap();
    let prefix = td.join("fp");
    std::fs::create_dir_all(prefix.join("lib")).unwrap();
    write(&prefix.join("share/demo/a.conf"), "conf\n");
    write(
        &td.join("demo.c"),
        &format!(
            "const char *demo_dir = \"{}\";\nint demo(void){{return 1;}}\n",
            prefix.join("share/demo").display()
        ),
    );
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libdemo.so.1",
            td.join("demo.c").to_str().unwrap(),
        ],
        &prefix.join("lib/libdemo.so.1"),
    ) {
        return;
    }
    write(&td.join("dep.c"), "int gone_value(void){return 3;}\n");
    let missing = prefix.join("lib/libmissing.so.1");
    let build_missing = || {
        cc_with(
            &[
                "-shared",
                "-fPIC",
                "-Wl,-soname,libmissing.so.1",
                td.join("dep.c").to_str().unwrap(),
            ],
            &missing,
        )
    };
    if !build_missing() {
        return;
    }
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    let lib_dir = format!("-L{}", prefix.join("lib").display());
    write(
        &td.join("main.c"),
        "int demo(void);int gone_value(void);\nint main(void){return demo()+gone_value()-4;}\n",
    );
    assert!(cc_with(
        &[
            td.join("main.c").to_str().unwrap(),
            &lib_dir,
            "-l:libdemo.so.1",
            "-l:libmissing.so.1",
        ],
        &app.join("bin/app"),
    ));
    write(
        &app.join("onelf.toml"),
        &format!(
            "[package]\nname = \"inferred\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [\"{}\"]\n",
            prefix.join("lib").display()
        ),
    );
    // The needed library is unreachable, so the strict host scan stops
    // the build after the rewrite has landed.
    std::fs::remove_file(&missing).unwrap();
    let failed = onelf_build(&app);
    let err = String::from_utf8_lossy(&failed.stderr);
    assert!(!failed.status.success(), "{err}");
    assert!(err.contains("libmissing.so.1"), "{err}");
    let record = std::fs::read(app.join(".onelf/anchors")).unwrap();
    assert_eq!(record, b"a\tshare/demo", "{err}");
    let lib = std::fs::read(app.join("lib/libdemo.so.1")).unwrap();
    assert!(lib.windows(14).any(|w| w == b"/dev/fd/77/a\0\0"), "{err}");

    // The fix makes the library reachable again. The rebuild refreshes
    // the staged copy from the host, so discovery also runs again; what
    // matters is that the mapping never fell out of the tree: the build
    // succeeds and the package carries the same anchor and record.
    assert!(build_missing());
    let fixed = onelf_build(&app);
    let err = String::from_utf8_lossy(&fixed.stderr);
    assert!(fixed.status.success(), "{err}");
    assert!(
        err.contains("Redirected inferred directories:") && err.contains("share/demo: anchor a"),
        "{err}"
    );
    assert_eq!(
        std::fs::read(app.join(".onelf/anchors")).unwrap(),
        record,
        "{err}"
    );
    let _ = std::fs::remove_dir_all(&td);
}

/// A directory inference collects inside a directory a descriptor
/// carries whole is omitted naming the clash: the descriptor's copy is
/// planned around it, and its bytes are what the tree holds.
#[test]
fn an_inferred_dir_inside_a_descriptors_copy_is_omitted() {
    let td = workdir("infer-clash-outer");
    let td = td.canonicalize().unwrap();
    write(&td.join("fp/share/fw/sub/host.conf"), "host\n");
    write(&td.join("fp/opt/ruletree/rule.txt"), "authored\n");
    let Some((app, lib_dirs)) = inferred_dirs_app(&td, &[("fp", "libfw.so.1", &["share/fw/sub"])])
    else {
        return;
    };
    let paths: Vec<String> = lib_dirs
        .iter()
        .map(|d| format!("\"{}\"", d.display()))
        .collect();
    write(
        &td.join("rules/fw.toml"),
        "schema = 1\nid = \"rulefw\"\n\n[[triggers]]\nsoname-prefix = \"libfw.so\"\n\n\
         [[resources.data]]\nid = \"tree\"\nkind = \"directory\"\n\
         destination = \"share/fw\"\nrequirement = \"optional\"\n\
         candidates = [{ base = \"installation-prefix\", path = \"opt/ruletree\" }]\n",
    );
    write(
        &app.join("onelf.toml"),
        &format!(
            "[package]\nname = \"inferred\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [{}]\nrules = [\"../rules/fw.toml\"]\n",
            paths.join(", ")
        ),
    );
    let out = onelf_build(&app);
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{err}");
    assert_eq!(
        std::fs::read_to_string(app.join("share/fw/rule.txt")).unwrap(),
        "authored\n",
        "the descriptor's copy stands: {err}"
    );
    assert!(
        !app.join("share/fw/sub").exists(),
        "the inferred directory is omitted: {err}"
    );
    let findings = findings_block(&err);
    assert!(
        findings.iter().any(|l| {
            l.contains("share/fw/sub: optional omission")
                && l.contains("collides with the whole-directory copy planned at share/fw")
        }),
        "{findings:#?}"
    );
}

/// A descriptor's own write inside the directory copy its descriptor
/// plans stops the build, whichever group is declared first: two writes
/// in one subtree would replace each other by declaration order, so the
/// conflict is named instead of settled by luck.
#[test]
fn a_descriptors_write_inside_its_directory_copy_stops_the_build() {
    for tag in ["tree-first", "override-first"] {
        let td = workdir(&format!("desc-subtree-{tag}"));
        let td = td.canonicalize().unwrap();
        write(&td.join("fp/opt/ruletree/rule.txt"), "authored\n");
        write(&td.join("fp/opt/rulefile/override.conf"), "override\n");
        let Some((app, _)) = inferred_dirs_app(&td, &[("fp", "libfw.so.1", &["share/nothing"])])
        else {
            return;
        };
        let tree_group = "[[resources.data]]\nid = \"tree\"\nkind = \"directory\"\n\
             destination = \"share/fw\"\nrequirement = \"optional\"\n\
             candidates = [{ base = \"installation-prefix\", path = \"opt/ruletree\" }]\n";
        let override_group = "[[resources.data]]\nid = \"override\"\nkind = \"file\"\n\
             destination = \"share/fw/override.conf\"\nrequirement = \"optional\"\n\
             candidates = [{ base = \"installation-prefix\", path = \"opt/rulefile/override.conf\" }]\n";
        let (first, second) = if tag == "tree-first" {
            (tree_group, override_group)
        } else {
            (override_group, tree_group)
        };
        write(
            &td.join("rules/fw.toml"),
            &format!(
                "schema = 1\nid = \"rulefw\"\n\n[[triggers]]\nsoname-prefix = \"libfw.so\"\n\n\
                 {first}{second}"
            ),
        );
        write(
            &app.join("onelf.toml"),
            &format!(
                "[package]\nname = \"inferred\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
                 [bundle]\nsearch-paths = [\"{}\"]\nrules = [\"../rules/fw.toml\"]\n",
                td.join("fp/lib").display()
            ),
        );
        let out = onelf_build(&app);
        let err = String::from_utf8_lossy(&out.stderr);
        assert!(!out.status.success(), "the clash stops the build: {err}");
        assert!(
            err.contains("share/fw: copies a whole directory there")
                && err.contains("share/fw/override.conf"),
            "{err}"
        );
        assert!(
            !app.join("share/fw").exists(),
            "nothing is written once planning fails: {err}"
        );
    }
}

/// A second member under one name, carried at its own place in an
/// inferred plugin directory's layout, has its compiled-in
/// directories inferred from its own bytes too: a data directory only
/// that member names arrives beside the plugin directory.
#[test]
fn a_second_same_named_member_has_its_compiled_in_directory_inferred() {
    let td = workdir("infer-second-member");
    let td = td.canonicalize().unwrap();
    let Some((app, _)) =
        inferred_dirs_app(&td, &[("fp", "libfw.so.1", &["lib/examplefw/plugins"])])
    else {
        return;
    };
    let plugins = td.join("fp/lib/examplefw/plugins");
    let more = td.join("fp/lib/examplefw/more");
    std::fs::create_dir_all(plugins.join("a")).unwrap();
    std::fs::create_dir_all(plugins.join("b")).unwrap();
    write(&td.join("a.c"), "int probe_value(void){return 0;}\n");
    write(
        &td.join("b.c"),
        &format!(
            "const char *more_dirs[] = {{\"{}\"}};\nint probe_value(void){{return 0;}}\n",
            more.display()
        ),
    );
    if !cc_with(
        &["-shared", "-fPIC", td.join("a.c").to_str().unwrap()],
        &plugins.join("a/probe.so"),
    ) || !cc_with(
        &["-shared", "-fPIC", td.join("b.c").to_str().unwrap()],
        &plugins.join("b/probe.so"),
    ) {
        return;
    }
    write(&more.join("extra.conf"), "extra\n");
    let out = onelf_build(&app);
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{err}");
    assert!(
        app.join("lib/examplefw/plugins/a/probe.so").is_file(),
        "the first member arrives at its place: {err}"
    );
    assert!(
        app.join("lib/examplefw/plugins/b/probe.so").is_file(),
        "the second member arrives at its own place: {err}"
    );
    let extra = std::fs::read_to_string(app.join("lib/examplefw/more/extra.conf"));
    assert!(
        matches!(&extra, Ok(text) if text == "extra\n"),
        "the directory only the second member names arrives: {extra:?} {err}"
    );
}

/// An AppDir whose program links one library per prefix, each library
/// compiling in the directories listed with it below its own prefix.
/// Returns the AppDir and the libraries' directories, or None without a
/// compiler.
fn inferred_dirs_app(
    td: &Path,
    libraries: &[(&str, &str, &[&str])],
) -> Option<(PathBuf, Vec<PathBuf>)> {
    let mut lib_dirs = Vec::new();
    let mut args: Vec<String> = Vec::new();
    for (prefix, soname, dirs) in libraries {
        let prefix = td.join(prefix);
        let names: Vec<String> = dirs
            .iter()
            .map(|d| format!("\"{}\"", prefix.join(d).display()))
            .collect();
        let stem = soname.split('.').next().unwrap();
        let src = td.join(format!("{stem}.c"));
        write(
            &src,
            &format!(
                "const char *{stem}_dirs[] = {{{}}};\nint {stem}_value(void){{return 0;}}\n",
                names.join(", ")
            ),
        );
        let out = prefix.join("lib").join(soname);
        std::fs::create_dir_all(out.parent().unwrap()).unwrap();
        if !cc_with(
            &[
                "-shared",
                "-fPIC",
                &format!("-Wl,-soname,{soname}"),
                src.to_str().unwrap(),
            ],
            &out,
        ) {
            return None;
        }
        args.push(format!("-L{}", prefix.join("lib").display()));
        args.push(format!("-l:{soname}"));
        lib_dirs.push(prefix.join("lib"));
    }
    write(&td.join("main.c"), "int main(void){return 0;}\n");
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    let main = td.join("main.c").to_string_lossy().into_owned();
    let mut refs: Vec<&str> = vec![&main];
    refs.extend(args.iter().map(String::as_str));
    if !cc_with(&refs, &app.join("bin/app")) {
        return None;
    }
    let paths: Vec<String> = lib_dirs
        .iter()
        .map(|d| format!("\"{}\"", d.display()))
        .collect();
    write(
        &app.join("onelf.toml"),
        &format!(
            "[package]\nname = \"inferred\"\ncommand = \"bin/app\"\nmtime = 0\n\n\
             [bundle]\nsearch-paths = [{}]\n",
            paths.join(", ")
        ),
    );
    Some((app, lib_dirs))
}

/// A file the build may not read inside an inferred data directory
/// omits that directory with the reason, and the build goes on. Root
/// reads it regardless, so the check needs another user.
#[test]
fn an_unreadable_file_omits_its_inferred_directory_without_failing() {
    use std::os::unix::fs::PermissionsExt;
    if root_flavor() == Some(RootFlavor::AlreadyRoot) {
        skip("non-root", "root reads a mode 000 file");
        return;
    }
    let td = workdir("infer-unreadable");
    let td = td.canonicalize().unwrap();
    write(&td.join("fp/share/lockedfw/secret"), "secret\n");
    write(&td.join("fp/share/openfw/a.conf"), "open\n");
    let Some((app, _)) = inferred_dirs_app(
        &td,
        &[("fp", "libfw.so.1", &["share/lockedfw", "share/openfw"])],
    ) else {
        return;
    };
    let secret = td.join("fp/share/lockedfw/secret");
    std::fs::set_permissions(&secret, std::fs::Permissions::from_mode(0o000)).unwrap();
    let out = onelf_build(&app);
    std::fs::set_permissions(&secret, std::fs::Permissions::from_mode(0o644)).unwrap();
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{err}");
    assert!(app.join("share/openfw/a.conf").is_file(), "{err}");
    assert!(!app.join("share/lockedfw").exists(), "{err}");
    let findings = findings_block(&err);
    assert!(
        findings.iter().any(|l| l
            .contains("share/lockedfw: optional omission: omitted because it cannot be carried")),
        "{findings:#?}"
    );
}

/// Two prefixes whose inferred directories nest at one destination are
/// never both written: whichever sorts first is carried, and the other
/// is omitted, the inner one naming the source it overlaps and the outer
/// one naming the carried directory inside it.
#[test]
fn nested_inferred_directories_from_two_sources_are_never_mixed() {
    for (outer, inner) in [("a", "b"), ("b", "a")] {
        let td = workdir(&format!("infer-nested-{outer}"));
        let td = td.canonicalize().unwrap();
        write(&td.join(outer).join("share/foo/outer.conf"), "outer\n");
        write(&td.join(inner).join("share/foo/sub/inner.conf"), "inner\n");
        let Some((app, _)) = inferred_dirs_app(
            &td,
            &[
                (outer, "libouter.so.1", &["share/foo"]),
                (inner, "libinner.so.1", &["share/foo/sub"]),
            ],
        ) else {
            return;
        };
        let out = onelf_build(&app);
        let err = String::from_utf8_lossy(&out.stderr);
        assert!(out.status.success(), "{outer} first: {err}");
        let findings = findings_block(&err);
        let omitted: Vec<&&str> = findings
            .iter()
            .filter(|l| l.contains("optional omission: omitted because"))
            .collect();
        assert_eq!(omitted.len(), 1, "{outer} first: {findings:#?}");
        if outer == "a" {
            assert!(
                omitted[0].contains("overlaps it at"),
                "{outer} first: {findings:#?}"
            );
        } else {
            assert!(
                omitted[0].contains("share/foo/sub inside it is carried already"),
                "{outer} first: {findings:#?}"
            );
        }
        let outer_carried = app.join("share/foo/outer.conf").is_file();
        let inner_carried = app.join("share/foo/sub/inner.conf").is_file();
        assert!(
            outer_carried != inner_carried,
            "{outer} first: exactly one source is carried: {findings:#?}"
        );
        assert_eq!(
            outer_carried,
            outer == "a",
            "{outer} first: the source that sorts first is carried"
        );
    }
}

/// An inferred destination that passes through a symlinked AppDir path
/// is omitted with the link named, and the build goes on: the plan's
/// refusal is undone instead of stopping the build over a directory
/// that was optional all along.
#[test]
fn an_inferred_dir_through_a_symlinked_appdir_path_is_omitted_without_failing() {
    let td = workdir("infer-symlink");
    let td = td.canonicalize().unwrap();
    write(&td.join("fp/share/lockedfw/a.conf"), "conf\n");
    write(&td.join("gp/lib/twowfw/b.conf"), "two\n");
    let Some((app, _)) = inferred_dirs_app(
        &td,
        &[
            ("fp", "libfw.so.1", &["share/lockedfw"]),
            ("gp", "libgw.so.1", &["lib/twowfw"]),
        ],
    ) else {
        return;
    };
    std::fs::create_dir_all(app.join("usr/share")).unwrap();
    std::os::unix::fs::symlink("usr/share", app.join("share")).unwrap();
    let out = onelf_build(&app);
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(out.status.success(), "{err}");
    assert!(app.join("lib/twowfw/b.conf").is_file(), "{err}");
    assert!(!app.join("usr/share/lockedfw").exists(), "{err}");
    let findings = findings_block(&err);
    assert!(
        findings.iter().any(|l| {
            l.contains("share/lockedfw: optional omission")
                && l.contains("passes through the symlink share")
        }),
        "{findings:#?}"
    );
    assert!(
        findings
            .iter()
            .any(|l| l.contains("lib/twowfw: selected: data directory")),
        "{findings:#?}"
    );
}

/// An incremental build that adds a directory sorting before the
/// recorded one cannot keep the record's keys: the tree's rewritten
/// bytes name the old key, and handing that key to the new directory
/// would resolve them into the wrong content. The build stops naming
/// both, the record and its bytes stay as they were, and the next run
/// proceeds with the new directory held, which takes no fresh decision.
#[test]
fn an_anchor_addition_that_would_move_a_recorded_key_stops_the_build() {
    let td = workdir("infer-anchor-move");
    let td = td.canonicalize().unwrap();
    let prefix = td.join("fp");
    std::fs::create_dir_all(prefix.join("lib")).unwrap();
    write(&prefix.join("share/fw/top.conf"), "host top\n");
    write(
        &td.join("demo.c"),
        &format!(
            "const char *demo_dir = \"{}\";\nint demo(void){{return 1;}}\n",
            prefix.join("share/fw").display()
        ),
    );
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libdemo.so.1",
            td.join("demo.c").to_str().unwrap(),
        ],
        &prefix.join("lib/libdemo.so.1"),
    ) {
        return;
    }
    let app = td.join("app");
    std::fs::create_dir_all(app.join("bin")).unwrap();
    write(
        &td.join("main.c"),
        "int demo(void);\nint main(void){return demo()-1;}\n",
    );
    let lib_dir = format!("-L{}", prefix.join("lib").display());
    assert!(cc_with(
        &[
            td.join("main.c").to_str().unwrap(),
            &lib_dir,
            "-l:libdemo.so.1",
        ],
        &app.join("bin/app"),
    ));
    let run = |extra: &[&str]| -> (bool, String) {
        let mut command = Command::new(onelf());
        command
            .args(["bundle-libs", app.to_str().unwrap(), "--target", "bin/app"])
            .env("LD_LIBRARY_PATH", prefix.join("lib"));
        for arg in extra {
            command.arg(arg);
        }
        let out = command.output().expect("spawn onelf bundle-libs");
        let err = String::from_utf8_lossy(&out.stderr).into_owned();
        (out.status.success(), err)
    };
    let (ok, first) = run(&[]);
    assert!(ok, "{first}");
    let record = std::fs::read(app.join(".onelf/anchors")).unwrap();
    assert_eq!(record, b"a\tshare/fw", "{first}");
    let demo_before = std::fs::read(app.join("lib/libdemo.so.1")).unwrap();

    // The second run adds a second directory sorting before share/fw,
    // carried whole and long enough to carry an anchor of its own.
    write(&prefix.join("share/aaa/a.conf"), "conf\n");
    write(
        &td.join("intro.c"),
        &format!(
            "const char *demo_dir = \"{}\";\nint intro(void){{return 2;}}\n",
            prefix.join("share/aaa").display()
        ),
    );
    if !cc_with(
        &[
            "-shared",
            "-fPIC",
            "-Wl,-soname,libintro.so.1",
            td.join("intro.c").to_str().unwrap(),
        ],
        &prefix.join("lib/libintro.so.1"),
    ) {
        return;
    }
    write(
        &td.join("main2.c"),
        "int demo(void);int intro(void);\nint main(void){return demo()+intro()-3;}\n",
    );
    assert!(cc_with(
        &[
            td.join("main2.c").to_str().unwrap(),
            &lib_dir,
            "-l:libdemo.so.1",
            "-l:libintro.so.1",
        ],
        &app.join("bin/app"),
    ));
    let (ok, second) = run(&[]);
    assert!(!ok, "{second}");
    assert!(
        second.contains("anchor a names share/fw in the tree's record"),
        "{second}"
    );
    assert!(second.contains("bundle a fresh tree"), "{second}");
    assert_eq!(
        std::fs::read(app.join("lib/libdemo.so.1")).unwrap(),
        demo_before,
        "the refused merge rewrote no recorded bytes: {second}"
    );
    let intro = std::fs::read(app.join("lib/libintro.so.1")).unwrap();
    let aaa = prefix.join("share/aaa").display().to_string();
    let anchor_prefix = b"/dev/fd/77/";
    assert!(
        intro.windows(aaa.len()).any(|w| w == aaa.as_bytes())
            && !intro
                .windows(anchor_prefix.len())
                .any(|w| w == anchor_prefix),
        "the refused merge left the new library's spelling alone: {second}"
    );
    assert_eq!(
        std::fs::read(app.join(".onelf/anchors")).unwrap(),
        record,
        "the record stays byte-identical: {second}"
    );

    // The next run proceeds: the refused run had already copied the new
    // directory, so it is held now, and a held carry takes no fresh
    // decision. The recorded keys stand, and the record is untouched.
    let (ok, third) = run(&[]);
    assert!(ok, "{third}");
    assert!(third.contains("share/fw: anchor a"), "{third}");
    assert_eq!(
        std::fs::read(app.join(".onelf/anchors")).unwrap(),
        record,
        "the record stays byte-identical: {third}"
    );
    let _ = std::fs::remove_dir_all(&td);
}
